window.OOP = {"chapters":[{"n":1,"title":"Tổng quan về lập trình hướng đối tượng","lang":"Lý thuyết","qs":[{"id":"1-1","n":1,"stem":"OOP là từ viết tắt của thuật ngữ tiếng Anh gì?","code":"","lang":"","opts":["Object-oriented programming","Object-oriented design","Object-oriented analysis","Cả 3 câu trên"],"ans":"A","exp":"OOP viết tắt của Object-oriented programming, nghĩa là lập trình hướng đối tượng. Hai đáp án còn lại cũng là thuật ngữ có thật nhưng thuộc giai đoạn khác: design là thiết kế hướng đối tượng, analysis là phân tích hướng đối tượng. Chữ P cuối cùng là Programming nên chọn A.","topic":"","note":""},{"id":"1-2","n":2,"stem":"Những phát biểu nào sau đây, thể hiện các đặc điểm cơ bản của lập trình hướng đối tượng?","code":"","lang":"","opts":["Tính đóng gói, tính kế thừa, tính đa hình, tính đặc biệt hóa.","Tính đóng gói, tính trừu tượng.","Tính chia nhỏ, tính kế thừa.","Tính đóng gói, tính kế thừa, tính đa hình, tính trừu tượng"],"ans":"D","exp":"Bốn tính chất trụ cột của OOP là đóng gói, kế thừa, đa hình và trừu tượng. Đáp án A sai vì không có tính chất nào tên là đặc biệt hóa. B và C kể thiếu. Cách nhớ nhanh: bốn chữ Đ - K - Đ - T.","topic":"","note":""},{"id":"1-3","n":3,"stem":"Hãy chọn câu trả lời đúng:","code":"","lang":"","opts":["Ngôn ngữ lập trình C, C++, C# là ngôn ngữ lập trình cấu trúc.","Ngôn ngữ lập trình C#, C++ là ngôn ngữ lập trình hướng đối tượng.","Ngôn ngữ lập trình Pascal, C là ngôn ngữ lập trình cấu trúc.","Ngôn ngữ lập trình C++, Java là ngôn ngữ lập trình cấu trúc."],"ans":"C","exp":"Pascal và C ra đời trước OOP, cả hai chỉ có hàm và cấu trúc chứ không có class nên là ngôn ngữ lập trình cấu trúc. C++, C#, Java đều có class nên thuộc nhóm hướng đối tượng. Đáp án B thiếu Java nhưng nội dung không sai, tuy nhiên câu C mới là câu chính xác và đầy đủ theo slide.","topic":"","note":""},{"id":"1-4","n":4,"stem":"Trong lập trình hướng đối tượng, sự đóng gói có thuật ngữ tiếng Anh là gì?","code":"","lang":"","opts":["Polymorphism.","Abstraction.","Encapsulation.","Inheritance."],"ans":"C","exp":"Encapsulation là đóng gói. Nghĩa gốc của từ là bỏ vào viên nang, giống như gói dữ liệu lại trong lớp rồi chỉ cho bên ngoài dùng qua phương thức. Hiểu vậy sẽ không lẫn với ba từ còn lại.","topic":"","note":""},{"id":"1-5","n":5,"stem":"Trong lập trình hướng đối tượng, sự trừu tượng có thuật ngữ tiếng Anh là gì?","code":"","lang":"","opts":["Encapsulation.","Polymorphism.","Inheritance.","Abstraction."],"ans":"D","exp":"Abstraction là trừu tượng. Abstract nghĩa là tóm tắt, chỉ giữ phần cốt lõi và bỏ chi tiết. Giống như bạn vặn tay ga cho xe chạy nhanh mà không cần biết động cơ hoạt động thế nào.","topic":"","note":""},{"id":"1-6","n":6,"stem":"Trong lập trình hướng đối tượng, sự kế thừa có thuật ngữ tiếng Anh là gì?","code":"","lang":"","opts":["Abstraction.","Encapsulation.","Polymorphism.","Inheritance."],"ans":"D","exp":"Inheritance là kế thừa. Từ này trong đời thường có nghĩa là thừa hưởng tài sản từ cha mẹ, đúng như lớp con thừa hưởng thuộc tính và phương thức của lớp cha.","topic":"","note":""},{"id":"1-7","n":7,"stem":"Trong lập trình hướng đối tượng, lớp kế thừa có thuật ngữ tiếng Anh là gì?","code":"","lang":"","opts":["Inheritance Class.","Object Class.","Derived Class.","Base Class."],"ans":"C","exp":"Lớp kế thừa còn gọi là lớp con hay lớp dẫn xuất, tiếng Anh là Derived Class. Derive nghĩa là dẫn ra từ cái đã có. Base Class là lớp cha, đừng nhầm hai từ này.","topic":"","note":""},{"id":"1-8","n":8,"stem":"Trong lập trình hướng đối tượng, trong kế thừa. Lớp cơ sở (hay còn gọi là lớp cha) có thuật ngữ tiếng Anh là gì?","code":"","lang":"","opts":["Base Class.","Derived Class.","Object Class.","Inheritance Class."],"ans":"A","exp":"Lớp cơ sở hay lớp cha là Base Class. Base nghĩa là nền móng, lớp này nằm dưới cùng và các lớp khác xây lên từ nó.","topic":"","note":""},{"id":"1-9","n":9,"stem":"Hãy chọn câu phát biểu sai:","code":"","lang":"","opts":["C++ là ngôn ngữ lập trình cấu trúc.","Ngôn ngữ C++, Java là ngôn ngữ lập trình hướng đối tượng.","Ngôn ngữ Pascal là ngôn ngữ lập trình hướng đối tượng.","C và Pascal là ngôn ngữ chỉ lập trình cấu trúc."],"ans":"C","exp":"Đề hỏi câu SAI. Pascal không có class, chỉ có record và procedure, nên nói Pascal là ngôn ngữ hướng đối tượng là sai. Ba câu còn lại đều đúng, kể cả câu A vì C++ vẫn viết được theo kiểu cấu trúc thuần.","topic":"","note":""},{"id":"1-10","n":10,"stem":"Trong lập trình hướng đối tượng, Sự đa hình có thuật ngữ tiếng Anh là gì?","code":"","lang":"","opts":["Abstraction.","Encapsulation.","Polymorphism.","Inheritance."],"ans":"C","exp":"Polymorphism là đa hình. Poly nghĩa là nhiều, morph nghĩa là hình dạng, ghép lại là nhiều hình dạng: cùng một tên phương thức nhưng mỗi lớp làm một kiểu khác nhau.","topic":"","note":""}]},{"n":2,"title":"Lớp và đối tượng","lang":"C++","qs":[{"id":"2-1","n":1,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, phương thức Rectangle(int w = 0, int h = 0){} được gọi là?","code":"class Rectangle {\nprivate:\n    int w;\n    int h;\npublic:\n    Rectangle(int w = 0, int h = 0) {}\n    void output() {}\n    ~Rectangle() {}\n};","lang":"cpp","opts":["Phương thức khởi tạo (Constructor)","Phương thức huỷ (Destructor)","Phương thức bạn (Friend)","Phương thức ảo (Virtual)"],"ans":"A","exp":"Constructor là phương thức có tên trùng tên lớp và không có kiểu trả về. Ở đây Rectangle(int w = 0, int h = 0) trùng tên lớp Rectangle nên nó là hàm khởi tạo. Nó chạy tự động ngay khi bạn tạo đối tượng.","topic":"4.1. Phương thức khởi tạo (Constructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"2-2","n":2,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, phương thức ~Rectangle(){} được gọi là?","code":"class Rectangle {\nprivate:\n    int w;\n    int h;\npublic:\n    Rectangle(int w = 0, int h = 0) {}\n    void output() {}\n    ~Rectangle() {}\n};","lang":"cpp","opts":["Phương thức khởi tạo (Constructor)","Phương thức hủy (Destructor)","Phương thức bạn (Friend)","Phương thức ảo (Virtual)"],"ans":"B","exp":"Dấu ngã trước tên lớp là dấu hiệu của destructor, tức phương thức hủy. Nó chạy tự động khi đối tượng hết phạm vi sống hoặc khi bạn gọi delete. Mỗi lớp chỉ có đúng một destructor và nó không nhận tham số.","topic":"4.2. Phương thức hủy (Destructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"2-3","n":3,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Geeks {\npublic:\n    string geekname;\n    void printName() {\n        cout << \"Geekname is:\" << geekname;\n    }\n};\nint main() {\n    Geeks obj;\n    obj.geekname = \"Abhi\";\n    return 0;\n}","lang":"cpp","opts":["Geekname is:","Abhi","Geekname is:Abhi","Cả 3 đáp án đều sai"],"ans":"D","exp":"Chương trình chỉ gán geekname rồi kết thúc, không hề gọi printName nên màn hình trống. Vì vậy cả ba đáp án in ra chữ đều sai, chọn D. Bẫy của câu này là thấy hàm in ra thì tưởng nó tự chạy.","topic":"","note":""},{"id":"2-4","n":4,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Geeks {\npublic:\n    string geekname;\n    void printName() {\n        cout << \"Geekname is:\" << geekname;\n    }\n};\nint main() {\n    Geeks* obj = NULL;\n    obj->geekname = \"Abhi\";\n    obj->printName();\n    return 0;\n}","lang":"cpp","opts":["Geekname is:","Abhi","Geekname is:Abhi","Lỗi thực thi"],"ans":"D","exp":"obj đang là NULL, tức không trỏ tới đối tượng nào. Gán obj->geekname là ghi vào vùng nhớ số 0 nên chương trình vẫn biên dịch được nhưng chết ngay lúc chạy. Đó là lỗi thực thi chứ không phải lỗi biên dịch.","topic":"2.2. Tạo và hủy đối tượng bằng new và delete / 2. KHAI BÁO ĐỐI TƯỢNG","note":""},{"id":"2-5","n":5,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Geeks {\npublic:\n    string geekname;\n    int id;\n    void printName();\n    void printId() {\n        cout << \"Geek id is: \" << id;\n    }\n};\nvoid Geeks::printName() {\n    cout << \"Geek name is: \" << geekname;\n}\nint main() {\n    Geeks obj;\n    obj.geekname = \"HITC\";\n    obj.id = 15;\n    obj.printName();\n    cout << \",\";\n    obj.printId();\n    return 0;\n}","lang":"cpp","opts":["Geek name is: HITC,Geek id is: 15","Geek id is: 15","Geek id is: 15, Geek name is: HITC","HITC,Geek id is: 15"],"ans":"A","exp":"Hai phương thức đều public nên gọi bình thường. Chương trình in theo đúng thứ tự lệnh: printName in \"Geek name is: HITC\", rồi dấu phẩy, rồi printId in \"Geek id is: 15\". Câu này kiểm tra việc viết thân hàm bên ngoài lớp bằng toán tử :: vẫn chạy y hệt viết bên trong.","topic":"","note":""},{"id":"2-6","n":6,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Geeks {\npublic:\n    int id;\n    Geeks() {\n        id = -1;\n    }\n    Geeks(int x) {\n        id = x;\n    }\n};\nint main() {\n    Geeks obj1;\n    cout << \"Geek id is: \" << obj1.id;\n    cout << \",\";\n    Geeks obj2(21);\n    cout << \"Geek id is: \" << obj2.id;\n    return 0;\n}","lang":"cpp","opts":["Geek id is: -1","Geek id is: 21","Geek id is: -1,Geek id is: 21","Lỗi biên dịch"],"ans":"C","exp":"obj1 khai báo không tham số nên gọi Geeks() và id bằng -1. obj2 khai báo có số 21 nên gọi Geeks(int x) và id bằng 21. Trình biên dịch chọn constructor nào là dựa vào số lượng và kiểu tham số bạn truyền.","topic":"","note":""},{"id":"2-7","n":7,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Geeks\n{\npublic:\n    int id;\n    ~Geeks() {\n        cout << id << \" \";\n    }\n};\nint main() {\n    for (int i = 0; i < 3; i++) {\n        Geeks obj;\n        obj.id = i;\n    }\n    return 0;\n}","lang":"cpp","opts":["0","1","2","0 1 2"],"ans":"D","exp":"Mỗi vòng lặp tạo một obj mới, hết vòng lặp là obj ra khỏi phạm vi nên destructor chạy ngay. Vòng lặp chạy ba lần với i bằng 0, 1, 2 nên in ra 0 1 2. Điểm cần nhớ: hết khối lệnh là đối tượng bị hủy.","topic":"4.2. Phương thức hủy (Destructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"2-8","n":8,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Demo {\npublic:\n    int a = 0;\n    int b = 0;\n    Demo(int a) {\n        cout << a << \" \";\n    }\n    Demo(int a, int b) : Demo(a + b) {\n        cout << a + b;\n    }\n};\nint main() {\n    Demo d(100, 200);\n    return 0;\n}","lang":"cpp","opts":["10","200","300 300","Lỗi thực thi"],"ans":"C","exp":"Demo(int a, int b) : Demo(a + b) gọi constructor một tham số trước với giá trị 100 + 200 = 300, nên in 300 trước. Sau đó thân hàm của constructor hai tham số in tiếp a + b cũng bằng 300. Kết quả là 300 300.","topic":"4.1. Phương thức khởi tạo (Constructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"2-9","n":9,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Demo {\npublic:\n    int a, b;\n    Demo() {\n        cout << \"Default Constructor\" << endl;\n    }\n    Demo(int a, int b) :a(a), b(b) {\n        cout << \"Parameterized Constructor: \" << a << \" \" << b << endl;\n    }\n};\nint main() {\n    Demo d(100, 200);\n    return 0;\n}","lang":"cpp","opts":["Default Constructor","Parameterized Constructor:","Parameterized Constructor: 100 200","100 200"],"ans":"C","exp":"Dấu hai chấm ở đây là danh sách khởi tạo, nó gán a = 100 và b = 200 rồi mới chạy thân hàm. Thân hàm in chuỗi kèm hai tham số a và b nên ra Parameterized Constructor: 100 200. Trong thân hàm, a và b là tham số truyền vào chứ không phải thuộc tính.","topic":"4.1. Phương thức khởi tạo (Constructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"2-10","n":10,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Demo {\npublic:\n    int a = 0;\n    int b = 0;\n    Demo(int a) {\n        cout << a << \" \";\n    }\n    Demo(int a, int b) :Demo(a) {\n        cout << a << \" \" << b << endl;\n    }\n};\nint main() {\n    Demo d(100, 200);\n    return 0;\n}","lang":"cpp","opts":["100","200","100 200","100 100 200"],"ans":"D","exp":"Demo(a) được gọi trước với a bằng 100 nên in 100 kèm khoảng trắng. Sau đó thân hàm constructor hai tham số in tiếp 100 và 200. Ghép lại thành 100 100 200.","topic":"4.1. Phương thức khởi tạo (Constructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"2-11","n":11,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Circle {\npublic:\n    double radius;\n    double compute_area() {\n        return 3.14 * radius * radius;\n    }\n};\nint main() {\n    Circle obj;\n    obj.radius = 5.5;\n    cout << \"Radius: \" << obj.radius << \" Area: \" << obj.compute_area();\n    return 0;\n}","lang":"cpp","opts":["Radius: 94.985","Radius is: 5.5","Area is: 94.95","Radius: 5.5 Area: 94.985"],"ans":"D","exp":"radius là public nên gán 5.5 được. compute_area trả về 3.14 nhân 5.5 nhân 5.5 bằng 94.985. Lệnh cout in đủ cả chuỗi Radius, giá trị bán kính rồi tới Area và diện tích.","topic":"","note":""},{"id":"2-12","n":12,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Circle {\nprivate:\n    double radius;\npublic:\n    double  compute_area() {\n        return 3.14 * radius * radius;\n    }\n};\nint main() {\n    Circle obj;\n    obj.radius = 1.5;\n    cout << \"Area is:\" << obj.compute_area();\n    return 0;\n}","lang":"cpp","opts":["Radius: 94.985","Radius is: 5.5","Area is: 94.95","Lỗi biên dịch"],"ans":"D","exp":"radius nằm trong vùng private nên main không được đụng vào. Dòng obj.radius = 1.5 làm trình biên dịch báo lỗi ngay, chương trình không chạy được. Muốn sửa thì phải thêm hàm set public hoặc chuyển radius sang public.","topic":"3.2. Phạm vi truy cập của thuộc tính và phương thức / 3. TRUY XUẤT CÁC THÀNH PHẦN CỦA LỚP","note":""},{"id":"2-13","n":13,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Circle {\nprivate:\n    double radius;\npublic:\n    void compute_area(double r) {\n        radius = r;\n        double area = 3.14 * radius * radius;\n        cout << \"Radius:\" << radius << \" Area:\" << area;\n    }\n};\nint main() {\n    Circle obj;\n    obj.compute_area(1.5);\n    return 0;\n}","lang":"cpp","opts":["Radius:1.5","Area:7.065","Radius:1.5 Area:7.065","Lỗi biên dịch"],"ans":"C","exp":"Lần này radius vẫn private nhưng main không đụng trực tiếp, nó truyền giá trị qua hàm public compute_area. Đây đúng là cách đóng gói: dữ liệu giấu bên trong, bên ngoài tác động qua phương thức. Diện tích là 3.14 nhân 1.5 nhân 1.5 bằng 7.065.","topic":"3.2. Phạm vi truy cập của thuộc tính và phương thức / 3. TRUY XUẤT CÁC THÀNH PHẦN CỦA LỚP","note":""},{"id":"2-14","n":14,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, Lựa chọn nào được viết ở dòng //you code here, để gán giá trị 10 vào biến a","code":"class RectangleA\n{\n    int a = 6;\npublic:\n    void display() {\n        cout << a;\n    }\n};\nint main() {\n    RectangleA rectA;\n    //you code here\n    return 0;\n}","lang":"cpp","opts":["rectA.a  = 10;","RectangleA::a = 10;","rectA(a  = 10;","Không có đáp án đúng"],"ans":"D","exp":"Trong C++, nếu không ghi từ khóa phạm vi thì mặc định là private, nên biến a của RectangleA là private. Vì vậy rectA.a = 10 sai, RectangleA::a = 10 cũng sai, còn dòng C thì sai cú pháp. Không có cách nào trong ba đáp án gán được nên chọn D.","topic":"3.2. Phạm vi truy cập của thuộc tính và phương thức / 3. TRUY XUẤT CÁC THÀNH PHẦN CỦA LỚP","note":""},{"id":"2-15","n":15,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Rectangle {\nprivate:\n    int a;\n    int b;\npublic:\n    Rectangle() {\n        cout << \"Hi\";\n    }\n    Rectangle(int m, int n) {\n        cout << \"Hello\";\n    }\n};\nint main() {\n    Rectangle rect(3, 4);\n    return 0;\n}","lang":"cpp","opts":["Hi","Hello","HiHello","Lỗi biên dịch"],"ans":"B","exp":"Rectangle rect(3, 4) truyền hai số nên trình biên dịch chọn constructor hai tham số và in Hello. Constructor không tham số chỉ chạy khi bạn viết Rectangle rect; không có ngoặc.","topic":"4.1. Phương thức khởi tạo (Constructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"2-16","n":16,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, Hãy cho biết chương trình sau có lỗi ở dòng nào:","code":"1   class RectangleInt\n2   {\n3   private:\n4       int a = 7;\n5       int b = 9;\n6\n7   };\n8   class RectangleFloat\n9   {\n10  private:\n11      float x = 6;\n12      float y = 8;\n13      friend void output();\n14  };\n15  void output()\n16  {\n17      RectangleInt obj1;\n18      RectangleFloat obj2;\n19      cout << obj1.a;\n20      cout << obj2.x;\n21  }\n22  int main() {\n23      output();\n24      return 0;\n25  }","lang":"cpp","opts":["Lỗi tại dòng 17, 18","Lỗi tại dòng 15","Lỗi tại dòng 19","Không lỗi ở dòng nào"],"ans":"C","exp":"Lớp RectangleInt không khai báo friend cho hàm output, mà a lại là private, nên dòng 19 in obj1.a là sai. Dòng 20 không lỗi vì RectangleFloat đã khai báo friend void output() nên hàm này được phép đọc x.","topic":"3.2. Phạm vi truy cập của thuộc tính và phương thức / 3. TRUY XUẤT CÁC THÀNH PHẦN CỦA LỚP","note":""},{"id":"2-17","n":17,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Rectangle {\nprivate:\n    int a;\n    int b;\npublic:\n    Rectangle() {\n        cout << \"Hi\";\n    }\n    Rectangle(int m, int n) {\n        cout << \"Hello\";\n    }\n};\nint main() {\n    Rectangle rect;\n    return 0;\n}","lang":"cpp","opts":["Hi","Hello","HiHello","Lỗi biên dịch"],"ans":"A","exp":"Rectangle rect; không truyền tham số nên constructor mặc định chạy và in Hi. Lưu ý không viết Rectangle rect(); vì như vậy trình biên dịch hiểu là khai báo một hàm chứ không phải đối tượng.","topic":"4.1. Phương thức khởi tạo (Constructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"2-18","n":18,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Rectangle {\nprivate:\n    int a;\n    int b;\npublic:\n    Rectangle() {\n        cout << \"Hi\";\n    }\n    Rectangle(int m, int n) {\n        cout << \"Hello\";\n    }\n};\nint main() {\n    Rectangle* rect = new Rectangle();\n    return 0;\n}","lang":"cpp","opts":["Hi","Hello","HiHello","Lỗi biên dịch"],"ans":"A","exp":"new Rectangle() cũng gọi constructor không tham số nên in Hi. Khác biệt duy nhất so với cách khai báo thường là đối tượng nằm ở vùng nhớ Heap và bạn phải tự delete.","topic":"4.1. Phương thức khởi tạo (Constructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"2-19","n":19,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Rectangle {\nprivate:\n    int a;\n    int b;\npublic:\n    Rectangle() {\n        cout << \"Hi\";\n    }\n    Rectangle(int m, int n) {\n        cout << \"Hello\";\n    }\n};\nint main() {\n    Rectangle* rect = new Rectangle(3, 4);\n    return 0;\n}","lang":"cpp","opts":["Hi","Hello","HiHello","Lỗi biên dịch"],"ans":"B","exp":"new Rectangle(3, 4) truyền hai số nên constructor hai tham số chạy và in Hello. Toán tử new vừa xin bộ nhớ vừa gọi constructor tương ứng.","topic":"4.1. Phương thức khởi tạo (Constructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"2-20","n":20,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Rectangle {\nprivate:\n    int a;\n    int b;\npublic:\n    Rectangle() {\n        cout << \"Hi\";\n    }\n    Rectangle(int m, int n) {\n        cout << \"Hello\";\n    }\n};\nint main() {\n    Rectangle* rect = new Rectangle(3, 4);\n    return 0;\n}","lang":"cpp","opts":["Hi","Hello","HiHello","Lỗi biên dịch"],"ans":"B","exp":"Câu này giống hệt câu trước, new Rectangle(3, 4) gọi constructor hai tham số nên in Hello. Đề lặp lại để kiểm tra bạn có nhớ quy tắc chọn constructor theo tham số không.","topic":"","note":""},{"id":"2-21","n":21,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Rectangle {\nprivate:\n    int a;\n    int b;\npublic:\n    Rectangle() {\n        cout << \"Hi\";\n    }\n    Rectangle(int m, int n):Rectangle {\n        cout << \"Hello\";\n    }\n};\nint main() {\n    Rectangle *rect= new Rectangle(3);\n    return 0;\n}","lang":"cpp","opts":["Hi","Hello","HiHello","Lỗi biên dịch"],"ans":"D","exp":"Dòng Rectangle(int m, int n):Rectangle { viết sai cú pháp, sau dấu hai chấm phải là một lời gọi có ngoặc như Rectangle(m). Thêm nữa new Rectangle(3) chỉ truyền một số mà lớp không có constructor một tham số. Cả hai chỗ đều làm chương trình lỗi biên dịch.","topic":"4.1. Phương thức khởi tạo (Constructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"2-22","n":22,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch chương trình, lỗi tại dòng nào?","code":"class A{\nprivate:\n    int x;\npublic:\n    int y;\n};\nvoid main()\n{\n    A obj;\n    obj.x = 10;\n    obj.y = 8;\n}","lang":"cpp","opts":["Lỗi tại dòng int x;","Lỗi tại dòng obj.y=8;","Lỗi tại dòng A.obj;","Lỗi tại dòng obj.x=10;"],"ans":"D","exp":"x nằm trong private nên bên ngoài lớp không được phép truy cập. Dòng obj.x = 10 là dòng bị báo lỗi, còn obj.y = 8 hợp lệ vì y là public.","topic":"3.2. Phạm vi truy cập của thuộc tính và phương thức / 3. TRUY XUẤT CÁC THÀNH PHẦN CỦA LỚP","note":""},{"id":"2-23","n":23,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch chương trình, lỗi tại obj.x=10, nguyên nhân của lỗi này là?","code":"class A{\nprivate:\n    int x;\npublic:\n    int y;\n};\nvoid main(){\n    A obj;\n    obj.x = 10;\n    obj.y = 8;\n}","lang":"cpp","opts":["Chưa khai báo x","Không thể truy cập vào thành phần private của lớp","Không xác định được giá trị x","Phải gọi thông qua tên lớp không được gọi thông qua tên đối tượng"],"ans":"B","exp":"Nguyên nhân là x có phạm vi private, chỉ dùng được bên trong lớp hoặc trong hàm bạn, lớp bạn. Biến x đã được khai báo đầy đủ nên không phải lỗi thiếu khai báo.","topic":"3.2. Phạm vi truy cập của thuộc tính và phương thức / 3. TRUY XUẤT CÁC THÀNH PHẦN CỦA LỚP","note":""},{"id":"2-24","n":24,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, phương thức Rectangle(){} được gọi là?","code":"public class Rectangle\n{\n    private int w;\n    private int h;\n    public Rectangle(){}\n    public Rectangle(int w, int h){}\n    void output(){}\n}","lang":"java","opts":["Phương thức khởi tạo (Constructor)","Phương thức huỷ (Destructor)","Phương thức bạn (Friend)","Phương thức ảo (Virtual)"],"ans":"A","exp":"Trong Java quy tắc cũng giống C++: phương thức trùng tên lớp và không có kiểu trả về chính là constructor. Ở đây có hai constructor, một không tham số và một nhận hai tham số, đó là quá tải hàm khởi tạo.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.1. Constructor","note":""},{"id":"2-25","n":25,"stem":"class Point","code":"{\n    int x, y;\npublic:\n    Point(int i = 0, int j = 0)\n    {\n        x = i;\n        y = j;\n    }\n    int getX() { return x; }\n    int getY() { return y; }\n};\nint main()\n{\n    Point p1;\n    Point p2 = p1;\n    cout << \"x = \" << p2.getX() << \" y = \" << p2.getY();\n    return 0;\n}","lang":"cpp","opts":["x = 0","y = 0","x = 0 y = 0","y = 0 x = 0"],"ans":"C","exp":"Point p1; gọi constructor với hai giá trị mặc định nên x và y đều bằng 0. Point p2 = p1; gọi constructor sao chép mặc định, chép nguyên hai giá trị đó sang p2. Kết quả in ra là x = 0 y = 0.","topic":"4.1. Phương thức khởi tạo (Constructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"2-26","n":26,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Point {\n    int x, y;\npublic:\n    Point(int i = 0, int j = 0) {\n        x = i;\n        y = j;\n    }\n    int getX() { return x; }\n    int getY() { return y; }\n};\nint main(){\n    Point p1(6,8);\n    Point p2 = p1;\n    cout << \"x = \" << p2.getX() << \" y = \" << p2.getY();\n    return 0;\n}","lang":"cpp","opts":["x = 0","y = 0","x = 0 y = 0","x = 6 y = 8"],"ans":"D","exp":"p1 được tạo với 6 và 8 nên x bằng 6, y bằng 8. Dòng Point p2 = p1 sao chép toàn bộ giá trị từ p1 sang p2 nên p2 cũng có 6 và 8. Đây là constructor sao chép mặc định do trình biên dịch tự sinh.","topic":"4.1. Phương thức khởi tạo (Constructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"2-27","n":27,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"int i;\nclass A {\n    int i = 5;\npublic:\n    ~A() {\n        i = 10;\n    }\n};\nint foo(){\n    i = 3;\n    A ob;\n    return i;\n}\nint main(){\n    cout << foo() << endl;\n    return 0;\n}","lang":"cpp","opts":["3","5","3 5","5 3"],"ans":"A","exp":"Có hai biến tên i khác nhau: một biến toàn cục và một thuộc tính trong lớp A. Hàm foo gán biến toàn cục i bằng 3 rồi trả về 3. Destructor của ob có sửa i nhưng đó là thuộc tính riêng của đối tượng, hơn nữa nó chạy sau khi giá trị trả về đã được lấy, nên kết quả in ra là 3.","topic":"4.2. Phương thức hủy (Destructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"2-28","n":28,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch chương trình, lỗi ở dòng nào?","code":"class POINT {\n    int x, y;\npublic:\n    void input();\n};\nclass HCN {\n    POINT p; //Dòng 1\n    int d, r;\npublic:\n    void input() {\n        cout <<\"d, r =\"; cin >> d, r;//Dòng 2\n        cout <<\"x, y =\"; cin >> p.x, p.y;//Dòng 3\n    }\n};","lang":"cpp","opts":["Dòng 1","Dòng 2","Dòng 3","Lỗi ở cả 3 dòng"],"ans":"C","exp":"x và y của lớp POINT không ghi phạm vi nên mặc định là private. Trong lớp HCN, hàm input cố đọc p.x và p.y trong khi HCN không phải bạn của POINT, nên dòng 3 báo lỗi. Dòng 1 và dòng 2 đều hợp lệ về mặt cú pháp.","topic":"3.2. Phạm vi truy cập của thuộc tính và phương thức / 3. TRUY XUẤT CÁC THÀNH PHẦN CỦA LỚP","note":""},{"id":"2-29","n":29,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Game {\nprivate:\n    int n = 0;\n    Game(int x){\n        n = x;\n    }\npublic:\n    void print() {\n        cout << n;\n    }\n};\nvoid main() {\n    Game pt(4);\n    pt.print();\n}","lang":"cpp","opts":["4","0","Lỗi biên dịch","Lỗi thực thi"],"ans":"C","exp":"Constructor Game(int x) bị đặt trong vùng private nên main không gọi được. Theo đúng quy tắc, constructor bắt buộc phải public thì bên ngoài mới tạo đối tượng được, vì vậy chương trình lỗi biên dịch.","topic":"4.1. Phương thức khởi tạo (Constructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"2-30","n":30,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Sum{\nprivate:\n    int  a, b;\npublic:\n    Sum (){\n        cout << \"Contructor 1\";\n    }\n    Sum (int m, int n){\n        cout << \"Contructor 2\";\n    }\n};\nvoid main(){\n    Sum (3,6);\n}","lang":"cpp","opts":["Contructor 1","Contructor 2","Lỗi biên dịch","Lỗi thực thi"],"ans":"B","exp":"Sum(3,6); tạo một đối tượng tạm không tên, nhưng nó vẫn gọi constructor hai tham số nên in Contructor 2. Đối tượng tạm này bị hủy ngay sau dòng lệnh.","topic":"4.1. Phương thức khởi tạo (Constructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"2-31","n":31,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Sum{\nprivate:\n    int  a, b;\npublic:\n    Sum(){\n        cout << \"Contructor 1\";\n    }\n    Sum(int m, int n){\n        cout << \"Contructor 2\";\n    }\n};\nvoid main(){\n    Sum *t = new Sum(3,6);\n}","lang":"cpp","opts":["Contructor 1","Contructor 2","Lỗi biên dịch","Lỗi thực thi"],"ans":"B","exp":"new Sum(3,6) truyền hai số nên constructor hai tham số chạy và in Contructor 2. Toán tử new luôn gọi constructor khớp với danh sách tham số bạn đưa vào.","topic":"4.1. Phương thức khởi tạo (Constructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"2-32","n":32,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class  Sum{\nprivate:\n    int  a, b;\npublic:\n    Sum(){\n        cout << \"Contructor 1\";\n    }\n    Sum(int m, int n){\n        cout << \"Contructor 2\";\n    }\n};\nvoid main(){\n    Sum *t = new Sum();\n}","lang":"cpp","opts":["Contructor 1","Contructor 2","Lỗi biên dịch","Lỗi thực thi"],"ans":"A","exp":"new Sum() không có tham số nên constructor mặc định chạy và in Contructor 1. So sánh với câu trước để thấy chỉ khác nhau ở tham số truyền vào.","topic":"4.1. Phương thức khởi tạo (Constructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"2-33","n":33,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class  Sum {\nprivate:\n    int  a, b;\npublic:\n    Sum() {\n        cout << \" Contructor 1 \";\n    }\n    Sum(int m, int n) {\n        Sum();\n        cout << \" Contructor 2 \";\n    }\n};\nvoid main() {\n    Sum* t = new Sum( 3,6);\n}","lang":"cpp","opts":["Contructor 1","Contructor 2","Contructor 1 Contructor 2","Contructor 2 Contructor 1"],"ans":"C","exp":"new Sum(3,6) gọi constructor hai tham số. Trong thân hàm, dòng Sum(); tạo thêm một đối tượng tạm và chạy constructor mặc định nên in Contructor 1 trước, xong mới in Contructor 2. Lưu ý dòng này không khởi tạo lại chính đối tượng đang tạo mà chỉ đẻ ra một đối tượng tạm.","topic":"4.1. Phương thức khởi tạo (Constructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"2-34","n":34,"stem":"Cho chương trình viết bằng ngôn ngữ C++, Định nghĩa hàm constructor nào là đúng?","code":"","lang":"cpp","opts":["Một hàm dùng để hủy đối tượng.","Một hàm dùng để sao chép đối tượng.","Một hàm dùng để khởi tạo đối tượng.","Một hàm dùng để so sánh hai đối tượng."],"ans":"C","exp":"Constructor là hàm khởi tạo, nhiệm vụ của nó là thiết lập giá trị ban đầu cho đối tượng ngay lúc đối tượng ra đời. Hủy đối tượng là việc của destructor, còn so sánh hai đối tượng là việc của toán tử hoặc hàm riêng.","topic":"","note":""},{"id":"2-35","n":35,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class MyClass {\nprivate:\n    int n;\npublic:\n    MyClass()\n    {\n         n = 16;\n    }\n    void hienThi()\n    {\n        cout << n;\n    }\n};\nvoid main() {\n    MyClass t;\n    t.hienThi();\n}","lang":"cpp","opts":["Chương trình thực thi xuất ra màn hình: 16","Lỗi thực thi","Lỗi biên dịch","Chương trình thực thi mà không xuất gì ra màn hình"],"ans":"A","exp":"Constructor mặc định gán n bằng 16, sau đó hienThi in n ra màn hình. Cả constructor và hienThi đều public nên không có lỗi truy cập, kết quả in ra 16.","topic":"3.2. Phạm vi truy cập của thuộc tính và phương thức / 3. TRUY XUẤT CÁC THÀNH PHẦN CỦA LỚP","note":""},{"id":"2-36","n":36,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class MyClass {\n    int n;\npublic:\n    MyClass(int x)\n    {\n        n = x;\n    }\n    void Print()\n    {\n        cout << n;\n    }\n};\nvoid main() {\n    MyClass t(5);\n    t.n = 14;\n    t.Print();\n}","lang":"cpp","opts":["Lỗi biên dịch","Chương trình thực thi xuất ra màn hình: 5","Chương trình thực thi mà không xuất gì ra màn hình","Chương trình thực thi xuất ra màn hình: 16"],"ans":"A","exp":"Lớp MyClass không ghi từ khóa phạm vi trước int n nên n mặc định là private. Dòng t.n = 14 trong main truy cập thẳng vào thành phần private nên lỗi biên dịch, chương trình không chạy.","topic":"3.2. Phạm vi truy cập của thuộc tính và phương thức / 3. TRUY XUẤT CÁC THÀNH PHẦN CỦA LỚP","note":""},{"id":"2-37","n":37,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class AAA {\n    int na;\npublic :\n        AAA(int a=0) {\n            na = a ;\n        }\n        ~AAA() {cout<< \" \"<<na ;}\n};\nvoid Func(const AAA &aaa) {\n    AAA *a1 = new AAA(3);\n    delete a1;\n}\nvoid main() {\n    AAA aaa(4);\n    Func(aaa);\n}","lang":"cpp","opts":["Xuất ra màn hình : 3","Xuất ra màn hình : 3 3 4","Xuất ra màn hình : 3 4","Xuất ra màn hình : 3 4 4"],"ans":"C","exp":"Destructor in giá trị na kèm một khoảng trắng. Trong hàm Func, delete a1 hủy đối tượng có na bằng 3 nên in 3. Tham số aaa truyền theo tham chiếu nên không tạo bản sao và không gọi thêm destructor. Cuối main, đối tượng aaa hết phạm vi nên in tiếp 4, kết quả là 3 4.","topic":"4.2. Phương thức hủy (Destructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"2-38","n":38,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Lop1\n{\nprivate:\n    int a,b;\npublic:\n    float x,y;\n    friend class Lop2;\n    friend class Lop3;\n};\nclass Lop2\n{\n    Lop1 objA;\n};\nclass Lop3\n{\n    Lop1 objB;\n};","lang":"cpp","opts":["objA và objB truy cập được tất cả các biến","objA truy cập được tất cả các biến. objB truy cập được các biến x,y","objA và objB chỉ truy cập được các biến a,b","objA và objB chỉ truy cập được các biến x,y"],"ans":"A","exp":"Lop1 khai báo cả Lop2 và Lop3 là lớp bạn, mà lớp bạn được phép đọc mọi thành phần kể cả private. Vì vậy cả objA lẫn objB đều dùng được a, b, x, y.","topic":"3.2. Phạm vi truy cập của thuộc tính và phương thức / 3. TRUY XUẤT CÁC THÀNH PHẦN CỦA LỚP","note":""},{"id":"2-39","n":39,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì? Khi đó, trong số các khai báo con trỏ đối tượng sau, những khai báo nào là đúng:","code":"class MyClass{\npublic:\n    MyClass(int i = 0, int j = 0, float k = 0);\n};","lang":"cpp","opts":["MyClass *me = new MyClass();","MyClass *me = new MyClass(1, 20);","MyClass *me = new MyClass(1, 20, 30);","Tất cả đều đúng"],"ans":"D","exp":"Constructor có cả ba tham số đều mang giá trị mặc định nên bạn truyền 0, 1, 2 hay 3 tham số đều hợp lệ. Tham số nào bị bỏ qua thì lấy giá trị mặc định. Do đó cả ba cách khai báo đều đúng.","topic":"5. PHƯƠNG THỨC VỚI THAM SỐ MẶC ĐỊNH / Ta có thể cung cấp giá trị mặc định trong khai báo hoặc trong định nghĩa hàm, nhưng không thể trong cả 2 (nên cung cấp trong khai báo).","note":""},{"id":"2-40","n":40,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Base{\npublic:\n    Base(){}\n    ~Base()\n    { cout << \"Base class \"; }\n};\nclass Derive :Base\n{\npublic:\n    Derive(){}\n    ~Derive()\n    { cout << \"Derive class \"; }\n};\nint main(){\n    Derive d;\n    return 0;\n}","lang":"cpp","opts":["Derive class Base class","Derive class","Base class Derive class","Base class"],"ans":"A","exp":"Khi tạo đối tượng lớp con, constructor chạy từ cha xuống con, còn destructor chạy ngược lại từ con lên cha. Ở đây chỉ có destructor in chữ nên thứ tự in là Derive class rồi mới tới Base class.","topic":"2.4. Phương thức khởi tạo và phương thức hủy trong lớp dẫn xuất / 2. ĐƠN KẾ THỪA","note":""},{"id":"2-41","n":41,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Circle {\nprivate:\n    double radius;\n    string color;\npublic:\n    Circle(double r = 1.0, string c = \"red\") {\n        radius = r;\n        color = c;\n    }\n    double getRadius() {\n        return radius;\n    }\n    string getColor() {\n        return color;\n    }\n    double getArea() {\n        return radius * radius * 3.1416;\n    }\n};\nint main() {\n    Circle c1(1.2, \"blue\");\n    cout << \"Radius=\" << c1.getRadius() << \" Area=\" << c1.getArea()\n        << \" Color=\" << c1.getColor() << endl;\n    return 0;\n}","lang":"cpp","opts":["Radius=1.2 Area=4.5239 Color=blue","Radius=3.4 Area=36.3169 Color=red","Radius=1 Area=3.1416 Color=red","Cả 3 câu đều sai"],"ans":"A","exp":"c1 truyền đủ hai tham số nên radius là 1.2 và color là blue, hai giá trị mặc định bị bỏ qua. Diện tích bằng 1.2 nhân 1.2 nhân 3.1416 và ra 4.5239.","topic":"","note":""},{"id":"2-42","n":42,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Circle {\nprivate:\n    double radius;\n    string color;\npublic:\n    Circle(double r = 1.0, string c = \"red\");\n    double getRadius();\n    string getColor();\n    double getArea();\n};\nCircle::Circle(double r, string c) {\n    radius = r;\n    color = c;\n}\ndouble Circle::getRadius() {\n    return radius;\n}\nstring Circle::getColor() {\n    return color;\n}\ndouble Circle::getArea() {\n    return radius*radius*3.1416;\n}\nint main() {\n    Circle c2(3.4);\n    cout << \"Radius=\" << c2.getRadius() << \" Area=\" << c2.getArea()\n        << \" Color=\" << c2.getColor() << endl;\n    return 0;\n}","lang":"cpp","opts":["Radius=1.2 Area=4.5239 Color=blue","Radius=3.4 Area=36.3169 Color=red","Radius=1 Area=3.1416 Color=red","Cả 3 câu đều sai"],"ans":"B","exp":"c2 chỉ truyền một tham số nên radius bằng 3.4, còn color lấy giá trị mặc định là red. Diện tích bằng 3.4 nhân 3.4 nhân 3.1416 và ra 36.3169. Nhớ rằng giá trị mặc định chỉ ghi ở phần khai báo trong lớp, không ghi lại ở phần định nghĩa bên ngoài.","topic":"","note":""},{"id":"2-43","n":43,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Rectangle {\n    int x, y;\npublic:\n    void setValues(int a, int b);\n    int area();\n};\nvoid Rectangle::setValues(int a, int b) {\n    x = a;\n    y = b;\n}\nint Rectangle::area() {\n    return (x*y);\n}\nint main() {\n    Rectangle *rect = new Rectangle();\n    rect->setValues(5, 20);\n    cout << \"area: \" << rect->area();\n    delete rect;\n    return 0;\n}","lang":"cpp","opts":["area:20","area:5","area:100","area:25"],"ans":"C","exp":"rect được tạo bằng new nên là con trỏ, muốn gọi phương thức phải dùng mũi tên. setValues gán x bằng 5 và y bằng 20, area trả về 5 nhân 20 bằng 100.","topic":"","note":""},{"id":"2-44","n":44,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Rectangle {\n    int x, y;\npublic:\n    void setValues(int a, int b);\n    int area();\n};\nvoid Rectangle::setValues(int a, int b) {\n    x = a;\n    y = b;\n}\nint Rectangle::area() {\n    return (x*y);\n}\nint main() {\n    Rectangle *rect = new Rectangle();\n    rect.setValues(5, 20);\n    cout << \"area: \" << rect.area();\n    delete rect;\n    return 0;\n}","lang":"cpp","opts":["area:20","area:5","Lỗi biên dịch tại dòng rect.setValues(5, 20);","area:25"],"ans":"C","exp":"rect là con trỏ nên bắt buộc dùng rect->setValues, viết rect.setValues là sai cú pháp và trình biên dịch báo lỗi ngay. Quy tắc gọn: biến thường dùng dấu chấm, con trỏ dùng mũi tên.","topic":"3.1. Toán tử truy xuất / 3. TRUY XUẤT CÁC THÀNH PHẦN CỦA LỚP","note":""},{"id":"2-45","n":45,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Rectangle {\n    int width, height;\npublic:\n    Rectangle(int, int);\n    int area();\n};\nint Rectangle::area() {\n    return (width*height);\n}\nint main() {\n    Rectangle recta(3, 4);\n    cout << \"area a:\" << recta.area();\n    return 0;\n}","lang":"cpp","opts":["area a:12","area a:3","Lỗi biên dịch do lớp Rectangle chưa cài đặt Constructor hai tham số","area a:7"],"ans":"C","exp":"Lớp mới chỉ khai báo Rectangle(int, int); mà chưa viết phần thân ở đâu cả. Khi main gọi Rectangle recta(3, 4) thì không tìm thấy mã của constructor nên chương trình lỗi. Khai báo và cài đặt là hai việc khác nhau, phải làm đủ cả hai.","topic":"4.1. Phương thức khởi tạo (Constructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"2-46","n":46,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Rectangle {\n    int width, height;\npublic:\n    Rectangle(int, int);\n    int area();\n};\nRectangle::Rectangle(int a, int b) {\n    width = a;\n    height = b;\n}\nint Rectangle::area() {\n    return (width*height);\n}\nint main() {\n    Rectangle recta(3, 4);\n    Rectangle rectb(5, 6);\n    cout << \"area a:\" << recta.area() << \" area b:\" << rectb.area();\n    return 0;\n}","lang":"cpp","opts":["area a:12 area b:30","area a:30 area b:30","area a:30 area b:12","Lỗi biên dịch do lớp Rectangle chưa cài đặt Constructor hai tham số"],"ans":"A","exp":"Constructor đã được cài đặt đầy đủ bên ngoài lớp bằng toán tử ::. recta có 3 nhân 4 bằng 12, rectb có 5 nhân 6 bằng 30. So sánh với câu trước để thấy chỗ khác biệt là phần cài đặt constructor.","topic":"4.1. Phương thức khởi tạo (Constructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"2-47","n":47,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau. Đoạn chương trình có tính chất gì?","code":"class Rectangle {\n    int width, height;\npublic:\n    Rectangle();\n    Rectangle(int, int);\n    int area();\n};\nRectangle::Rectangle() {\n    width = 5;\n    height = 5;\n}\nRectangle::Rectangle(int a, int b) {\n    width = a;\n    height = b;\n}\nint Rectangle::area() {\n    return (width*height);\n}\nint main() {\n    Rectangle recta(3, 4);\n    Rectangle rectb;\n    cout << \"area a:\" << recta.area();\n    cout << \"area b:\" << rectb.area();\n    return 0;\n}","lang":"cpp","opts":["Kế thừa","Trừu tượng","Chồng hàm khởi tạo","Quá tải hàm khởi tạo"],"ans":"D","exp":"Lớp có hai constructor cùng tên nhưng khác số tham số, đó gọi là quá tải hàm khởi tạo. Đáp án C chỉ là cách dịch sai vì override là ghi đè, xảy ra khi có kế thừa chứ không phải trường hợp này.","topic":"7.2. Tính chất / 7. QUÁ TẢI PHƯƠNG THỨC","note":""},{"id":"2-48","n":48,"stem":"Đối tượng rect sẽ được lưu trữ ở vùng nhớ nào khi chương trình thực thi?","code":"class Rectangle {\n    int x, y;\npublic:\n    void setValues(int a, int b);\n    int area();\n};\nvoid Rectangle::setValues(int a, int b) {\n    x = a;\n    y = b;\n}\nint Rectangle::area() {\n    return (x*y);\n}\nint main() {\n    Rectangle *rect = new Rectangle();\n    rect->setValues(5, 20);\n    cout << \"area: \" << rect->area();\n    delete rect;\n    return 0;\n}","lang":"cpp","opts":["Stack","BSS","Data","Heap"],"ans":"D","exp":"rect được tạo bằng toán tử new nên nó là cấp phát động và nằm ở vùng nhớ Heap. Nếu khai báo kiểu Rectangle rect; thì mới nằm ở Stack.","topic":"2.1. Tạo đối tượng tự động / 2. KHAI BÁO ĐỐI TƯỢNG","note":""},{"id":"2-49","n":49,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Rectangle {\n    int *width, *height;\npublic:\n    Rectangle(int, int);\n    int area();\n};\nRectangle::Rectangle(int a, int b) {\n    width = new int;\n    height = new int;\n    width = a;\n    height = b;\n}\nint Rectangle::area() {\n    return (width*height);\n}\nint main() {\n    Rectangle recta(3, 4);\n    cout << \"area a:\" << recta.area();\n    return 0;\n}","lang":"cpp","opts":["area a:12","area a:3","area a:4","Lỗi biên dịch tại hàm area() {  return (width*height); }"],"ans":"D","exp":"width và height là con trỏ int, nhân hai con trỏ với nhau là phép toán không hợp lệ nên hàm area bị lỗi biên dịch. Muốn nhân giá trị thì phải viết (*width) nhân (*height). Ngoài ra hai dòng gán width = a cũng sai kiểu.","topic":"","note":""},{"id":"2-50","n":50,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Rectangle {\n    int w, h;\npublic:\n    Rectangle(int a, int b);\n    void setValues(int a, int b);\n    int area();\n};\nRectangle::Rectangle(int a, int b){\n    w = a;\n    h = b;\n}\nvoid Rectangle::setValues(int a, int b) {\n    w = a;\n    h = b;\n}\nint Rectangle::area() {\n    return (w*h);\n}\nint main() {\n    Rectangle recta(5,20);\n    Rectangle *rectb;\n    rectb = &recta;\n    rectb->setValues(3, 4);\n    cout << \"Area a: \" << recta.area() << \" Area b: \" << rectb->area();\n    return 0;\n}","lang":"cpp","opts":["Area a:12 Area b:100","Area a:12 Area b:12","Area a:100 Area b:100","Area a:100 Area b:12"],"ans":"B","exp":"rectb được gán bằng địa chỉ của recta nên cả hai cùng trỏ về một đối tượng duy nhất. Lệnh rectb->setValues(3, 4) sửa luôn dữ liệu của recta, nên hai lần gọi area đều trả về 12.","topic":"2.2. Tạo và hủy đối tượng bằng new và delete / 2. KHAI BÁO ĐỐI TƯỢNG","note":""},{"id":"2-51","n":51,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Rectangle {\n    int w, h;\npublic:\n    void setValues(int a, int b);\n    int area();\n};\nvoid Rectangle::setValues(int a, int b) {\n    w = a;\n    h = b;\n}\nint Rectangle::area() {\n    return (w*h);\n}\nint main() {\n    Rectangle recta;\n    Rectangle *rectb = new Rectangle();\n    recta.setValues(5, 20);\n    rectb = &recta;\n    cout << \"Area a: \" << rectb.area() << \"Area b: \" << recta.area();\n    return 0;\n}","lang":"cpp","opts":["Area a:20 Area b:100","Area a:5 Area b:100","Area a:100 Area b:100","Lỗi biên dịch tại rectb.area()"],"ans":"D","exp":"Lỗi nằm ở cách gọi phương thức. rectb là con trỏ nên phải viết rectb->area(), viết rectb.area() là sai cú pháp và chương trình không biên dịch được.","topic":"3.1. Toán tử truy xuất / 3. TRUY XUẤT CÁC THÀNH PHẦN CỦA LỚP","note":""},{"id":"2-52","n":52,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, đối tượng rect trong hàm main sẽ được lưu trữ ở vùng nhớ nào khi chương trình thực thi?","code":"class Rectangle {\n    int x, y;\npublic:\n    void setValues(int a, int b);\n    int area();\n};\nvoid Rectangle::setValues(int a, int b) {\n    x = a;\n    y = b;\n}\nint Rectangle::area() {\n    return (x*y);\n}\nint main() {\n    Rectangle rect;\n    rect.setValues(5, 20);\n    cout << \"area: \" << rect.area();\n    delete rect;\n    return 0;\n}","lang":"cpp","opts":["Stack","BSS","Data","Heap"],"ans":"A","exp":"Ở đây rect khai báo trực tiếp không dùng new nên nó là biến cục bộ của hàm main và nằm ở vùng nhớ Stack. Dòng delete rect cũng sai vì chỉ được delete những gì đã xin bằng new.","topic":"2.2. Tạo và hủy đối tượng bằng new và delete / 2. KHAI BÁO ĐỐI TƯỢNG","note":""},{"id":"2-53","n":53,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, Hàm setValues trong lớp Rectangle có đặc điểm gì?","code":"class Rectangle {\n    int width, height;\npublic:\n    Rectangle();\n    Rectangle(int, int);\n    int area();\n    void setValues(int w, int h);\n    void setValues();\n};\nRectangle::Rectangle() {\n    width = 5;\n    height = 5;\n}\nRectangle::Rectangle(int a, int b) {\n    width = a;\n    height = b;\n}\nvoid Rectangle::setValues(int w, int h) {\n    width = w;\n    height = h;\n}\nvoid Rectangle::setValues() {\n    width = 0;\n    height = 0;\n}\nint Rectangle::area() {\n    return (width * height);\n}\nint main() {\n    Rectangle recta(3, 4);\n    Rectangle rectb;\n    cout << \"area a:\" << recta.area();\n    cout << \"area b:\" << rectb.area();\n    return 0;\n}","lang":"cpp","opts":["Chồng hàm (override)","Quá tải hàm (overload)","Hàm khởi tạo (constructor)","Hàm hủy (destructor)"],"ans":"B","exp":"Lớp có hai hàm cùng tên setValues nhưng một hàm nhận hai tham số, một hàm không nhận tham số nào. Cùng tên khác danh sách tham số trong cùng một lớp chính là quá tải hàm.","topic":"7.2. Tính chất / 7. QUÁ TẢI PHƯƠNG THỨC","note":""},{"id":"2-54","n":54,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Array {\n    int* data;\n    int size;\npublic:\n    Array(int s) {\n        size = s;\n        data = new int[size];\n    }\n    ~Array() {\n        delete data;\n    }\n    void out() {\n        cout << size;\n    }\n};\nvoid main() {\n    Array a1(10);\n    a1.out();\n}","lang":"cpp","opts":["5","10","0","Lỗi thực thi tại dòng lệnh delete data;"],"ans":"B","exp":"Chương trình tạo a1 với size bằng 10 rồi gọi out nên in ra 10. Việc dùng delete thay vì delete[] là viết thiếu chuẩn khi giải phóng mảng, nhưng nó xảy ra lúc hủy đối tượng, sau khi số 10 đã được in xong.","topic":"","note":""},{"id":"2-55","n":55,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Array {\n    int size;\npublic:\n    Array(int s) {\n        size = s;\n        cout << \"Constructor...\";\n    }\n    ~Array() {\n        cout << \"Destructor...\";\n    }\n};\nvoid out() {\n    Array a1(10);\n    Array a2 = a1;\n    cout << \"Out...\";\n}\nvoid main() {\n    out();\n}","lang":"cpp","opts":["Constructor...Out...Destructor...Destructor...","Constructor...Out...Destructor...","Constructor...Out...","Lỗi biên dịch do lớp Array không có hàm hủy (Destructor)"],"ans":"A","exp":"a1 gọi constructor nên in Constructor... một lần. a2 = a1 dùng constructor sao chép mặc định nên không in gì thêm. Sau khi in Out..., hết hàm thì cả hai đối tượng bị hủy nên Destructor... in hai lần.","topic":"4.2. Phương thức hủy (Destructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"2-56","n":56,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"Đoạn lệnh sau sai ở đâu, lý do tại sao, cách sửa lại cho đúng\nclass Array {\n    int* data;\n    int size;\npublic:\n    Array(int s) {\n        size = s;\n        data = new int[size];\n    }\n    ~Array() {\n        delete data;\n    }\n    void out() {\n        cout << size * 2;\n    }\n};\nvoid main() {\n    Array a1(10);\n    Array a2 = a1;\n    a2.out();\n}","lang":"cpp","opts":["10","5","0","Lỗi thực thi"],"ans":"D","exp":"Array a2 = a1 dùng constructor sao chép mặc định, nó chỉ chép địa chỉ con trỏ data chứ không chép vùng nhớ. Kết quả là hai đối tượng cùng trỏ về một vùng nhớ, khi cả hai cùng hủy thì vùng nhớ bị giải phóng hai lần và chương trình lỗi lúc chạy. Cách sửa là tự viết constructor sao chép để cấp phát vùng nhớ mới.","topic":"4.2. Phương thức hủy (Destructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"2-57","n":57,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Array {\n    int size;\npublic:\n    Array(int s) {\n        size = s;\n        cout << \"Constructor...\";\n    }\n    ~Array() {\n        cout << \"Destructor...\";\n    }\n};\nvoid out() {\n    Array a1(10);\n    Array a2 = a1;\n    cout << \"Out...\";\n}\nvoid main() {\n    out();\n}","lang":"cpp","opts":["Constructor...Out...Destructor...Destructor...","Constructor...Out...Destructor...","Constructor...Out...","Lỗi biên dịch do lớp Array không có hàm hủy (Destructor)"],"ans":"A","exp":"Giống câu 55: một lần Constructor..., rồi Out..., rồi hai lần Destructor... vì có hai đối tượng a1 và a2 cùng bị hủy khi hàm out kết thúc. Constructor sao chép mặc định không in gì nên dễ khiến bạn đếm thiếu một lần hủy.","topic":"4.2. Phương thức hủy (Destructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"2-58","n":58,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch, chương trình trên sẽ bị lỗi biên dịch tại dòng nào?","code":"1 class A {\n2 private:\n3    int x;\n     int  y;\n4 public:\n5   A(int x1, int y1);\n6   void In();\n7 };\n8 A::A(int x1, int y1) {\n9   x = x1;\n    y = y1;\n10 }\n11 void A::In() {\n12  cout << x << y;\n13 }\n14 void main() {\n15  A a1(1);\n16  A a2(20, 10);\n17  a1 = a2;\n18  a1.In();\n19 }","lang":"cpp","opts":["Dòng 9 - do sai lỗi cú pháp","Dòng 11 - do sai lỗi cú pháp","Dòng 15 - do không có hàm khởi tạo với tham số tương ứng","Dòng 17 - do không có toán tử gán = trong định nghĩa lớp"],"ans":"C","exp":"Lớp A chỉ có constructor hai tham số. Dòng 15 viết A a1(1); chỉ truyền một số nên không tìm được constructor phù hợp và báo lỗi. Muốn chạy được thì phải thêm constructor một tham số hoặc cho tham số thứ hai một giá trị mặc định.","topic":"4.1. Phương thức khởi tạo (Constructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"2-59","n":59,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class A {\nprivate:\n    int x;\n    int y;\npublic:\n    A(int x1, int y1) {\n        x = x1;\n        y = y1;\n    }\n    void In() {\n        cout << x << \"...\" << y;\n    }\n};\nvoid main()\n{\n    A a(10, 10);\n    a.x += 10;\n    a.y = a.x;\n    a.In();\n}","lang":"cpp","opts":["10...10","20...10","20...20","Lỗi biên dịch (lỗi do truy cập đến thành phần private của lớp A)"],"ans":"D","exp":"x và y là private nên main không đụng vào được. Dòng a.x += 10 gây lỗi biên dịch ngay, chương trình không chạy tới phần in.","topic":"3.2. Phạm vi truy cập của thuộc tính và phương thức / 3. TRUY XUẤT CÁC THÀNH PHẦN CỦA LỚP","note":""},{"id":"2-60","n":60,"stem":"Giới hạn truy xuất nào không có trong các lớp của C++","code":"","lang":"","opts":["public","private","protected","hidden"],"ans":"D","exp":"C++ chỉ có ba mức phạm vi là public, private và protected. Không hề có từ khóa hidden, đó là đáp án bịa ra để gây nhầm.","topic":"3.2. Phạm vi truy cập của thuộc tính và phương thức / 3. TRUY XUẤT CÁC THÀNH PHẦN CỦA LỚP","note":""},{"id":"2-61","n":61,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, Trong lớp Test phương thức nào được gọi là phương thức hủy (Destructor)?","code":"class Test {\npublic:\n    int n;\nprivate:\n    void display() {\n        cout << n;\n    }\npublic:\n    Test() {\n        n = 5;\n    }\n    ~Test() {\n        n = 0;\n    }\n};","lang":"cpp","opts":["display()","Test()","~Test()","Không có phương thức hủy (Destructor)"],"ans":"C","exp":"Phương thức hủy là phương thức có dấu ngã trước tên lớp, ở đây là ~Test(). Test() là hàm khởi tạo còn display chỉ là phương thức thường.","topic":"4.2. Phương thức hủy (Destructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"2-62","n":62,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, Trong lớp Test phương thức nào được gọi là phương thức khởi tạo (Contructor)?","code":"class Test {\npublic:\n    int n;\nprivate:\n    void display() {\n        cout << n;\n    }\npublic:\n    Test() {\n        n = 5;\n    }\n    ~Test() {\n        n = 0;\n    }\n};","lang":"cpp","opts":["display()","Test()","~Test()","Không có phương thức khởi tạo (Contructor)"],"ans":"B","exp":"Phương thức khởi tạo là hàm trùng tên lớp và không có kiểu trả về, tức là Test(). Dấu ngã chỉ dành cho hàm hủy.","topic":"4.1. Phương thức khởi tạo (Constructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"2-63","n":63,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Test {\npublic:\n    int n;\nprivate:\n    void Display() {\n        cout << n;\n    }\npublic:\n    Test() {\n        n = 5;\n    }\n};\nvoid main() {\n    Test t;\n    t.Display();\n}","lang":"cpp","opts":["5","Chương trình thực thi mà không xuất gì ra màn hình.","Lỗi biên dịch tại lệnh t.Display do hàm Display có thuộc tính private","Lỗi thực thi do đối tượng t chưa được cấp phát vùng nhớ"],"ans":"C","exp":"Display nằm trong vùng private nên chỉ gọi được từ bên trong lớp. Dòng t.Display() trong main gọi từ bên ngoài nên trình biên dịch báo lỗi.","topic":"3.2. Phạm vi truy cập của thuộc tính và phương thức / 3. TRUY XUẤT CÁC THÀNH PHẦN CỦA LỚP","note":""},{"id":"2-64","n":64,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Point {\n    int xVal, yVal;\npublic:\n    Point(int x = 0, int y = 0) {\n        xVal = x;\n        yVal = y;\n    }\n    void Print() {\n        cout << \" (\" << xVal << \",\" << yVal << \" )\";\n    }\n};\nvoid main() {\n    Point pt(5);\n    pt.Print();\n}","lang":"cpp","opts":["(5,0)","(5,5)","(0,5)","Lỗi do tạo đối tượng không đúng"],"ans":"A","exp":"Point pt(5) chỉ truyền một số nên x bằng 5, còn y lấy giá trị mặc định là 0. Kết quả in ra là (5,0). Tham số mặc định luôn được điền từ phải sang.","topic":"5. PHƯƠNG THỨC VỚI THAM SỐ MẶC ĐỊNH / Ta có thể cung cấp giá trị mặc định trong khai báo hoặc trong định nghĩa hàm, nhưng không thể trong cả 2 (nên cung cấp trong khai báo).","note":""},{"id":"2-65","n":65,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Point {\n    int xVal, yVal;\npublic:\n    Point(int x = 0, int y = 0) {\n        xVal = x;\n        yVal = y;\n        cout << \"So nguyen \";\n    }\n    Point(double x = 0, double y = 0) {\n        xVal = x;\n        yVal = y;\n        cout << \"So thuc \";\n    }\n    void Print();\n};\nvoid Point::Print() {\n    cout << \" (\" << xVal << \",\" << yVal << \" )\";\n}\nint main() {\n    Point pt(5.7);\n    pt.Print();\n    return 0;\n}","lang":"cpp","opts":["(5,0)","(5,5)","(0,0)","Lỗi biên dịch tại pt.Print(); do phương thức Print có thuộc tính public"],"ans":"A","exp":"Trình biên dịch không phân biệt được nên đây là trường hợp nhập nhằng, tuy nhiên theo đáp án của đề thì 5.7 được ép về int và cắt phần thập phân thành 5, còn y lấy mặc định là 0, in ra (5,0). Ghi nhớ điểm chính: gán số thực vào biến int thì phần thập phân bị cắt bỏ chứ không làm tròn.","topic":"7.1. Khái niệm / 7. QUÁ TẢI PHƯƠNG THỨC","note":""},{"id":"2-66","n":66,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Point {\n    int n;\npublic:\n    Point(int x) {\n        n = x;\n    }\n    void Print() {\n        cout << n;\n    }\n};\nvoid main() {\n    Point pt(4);\n    pt.Print();\n}","lang":"cpp","opts":["4","0","Lỗi biên dịch tại pt.Print(); do phương thức Print có thuộc tính public","Không xuất gì ra màn hình."],"ans":"A","exp":"Lớp chỉ có một constructor nhận một tham số, pt(4) truyền đúng một số nên n bằng 4 và Print in ra 4. Phương thức public thì gọi từ main hoàn toàn bình thường.","topic":"4.1. Phương thức khởi tạo (Constructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"2-67","n":67,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Test {\n    int t;\npublic:\n    Test(int t) {\n        Test::t = t;\n    }\n    void Print() {\n        cout << t;\n    }\n};\nvoid main() {\n    Test test(4);\n    test.Test::Print();\n}","lang":"cpp","opts":["Lỗi biên dịch tại test.Test::Print(); do gọi phương thức Print sai","4","0","Không xuất gì ra màn hình."],"ans":"B","exp":"Test::t = t trong constructor dùng toán tử phạm vi để chỉ rõ t bên trái là thuộc tính của lớp, còn t bên phải là tham số, nên gán được giá trị 4. Cách gọi test.Test::Print() cũng hợp lệ, nó chỉ ghi rõ Print thuộc lớp Test. Kết quả in ra 4.","topic":"3.2. Phạm vi truy cập của thuộc tính và phương thức / 3. TRUY XUẤT CÁC THÀNH PHẦN CỦA LỚP","note":""},{"id":"2-68","n":68,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Teacher {\npublic:\n    static int n;\n    Teacher (){\n        cout<<\" \"<<n++ ;\n    }\n};\nint Teacher::n = 0;\nint main() {\n    Teacher t1;\n    Teacher t2;\n    Teacher t3;\n    cout<<\" \"<<t1.n ;\n    return 0;\n}","lang":"cpp","opts":["0 1 2 3","1 2 3 4","1 1 1 1","0 1 3 2"],"ans":"A","exp":"n là biến static nên dùng chung cho cả lớp, khởi tạo bằng 0. Mỗi lần tạo đối tượng, constructor in giá trị n hiện tại rồi mới tăng lên, nên lần lượt in 0, 1, 2. Sau ba lần tạo thì n bằng 3 và dòng cuối in 3, tổng cộng là 0 1 2 3.","topic":"6.1. Thuộc tính tĩnh / 6. THUỘC TÍNH TĨNH VÀ PHƯƠNG THỨC TĨNH","note":""},{"id":"2-69","n":69,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Employee {\n    char name[30];\n    char id[10];\n    int age;\npublic:\n    Employee(const char n[], const char i[], int a) : age(a) {\n        strcpy_s(name, n);\n        strcpy_s(id, i);\n    }\n    void Display() {\n        cout << \"ID: \" << id << \" Name: \" << name << \" Age: \" << age << endl;\n    }\n};\nint main() {\n    Employee e(\"Tom\", \"001\", 20);\n    e.Display();\n    return 0;\n}","lang":"cpp","opts":["ID:001 Name:Tome Age:20","Lỗi thực thi do đối tượng e chưa được cấp phát vùng nhớ","Lỗi biên dịch do lớp Employee không có hàm khởi tạo 3 tham số","Không xuất gì ra màn hình."],"ans":"A","exp":"Constructor nhận đủ ba tham số, dùng danh sách khởi tạo cho age và dùng hàm chép chuỗi cho name và id. Display in đúng thứ tự ID, Name, Age nên ra ID: 001 Name: Tom Age: 20.","topic":"","note":""},{"id":"2-70","n":70,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Rectangle {\n    int *width, *height;\npublic:\n    Rectangle(int, int);\n    ~Rectangle();\n    int area();\n};\nRectangle::Rectangle(int a, int b) {\n    cout << \"Constructor Rect...\";\n}\nRectangle:: ~Rectangle(){\n    cout << \"Destructor Rect.\";\n}\nint Rectangle::area() {\n    return (*width)*(*height);\n}\nint main() {\n    Rectangle recta(3, 4);\n    cout << \" Rect a...\";\n    return 0;\n}","lang":"cpp","opts":["Constructor Rect...Rect a...Destructor Rect.","Constructor Rect...Rect a...","Constructor Rect...Destructor Rect.","Rect a..."],"ans":"A","exp":"Tạo recta thì constructor chạy và in Constructor Rect... Sau đó main in Rect a... Khi main kết thúc, recta hết phạm vi nên destructor chạy và in Destructor Rect. Đó là thứ tự của đáp án A.","topic":"4.2. Phương thức hủy (Destructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"2-71","n":71,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Rectangle {\n    int *width;\n    int *height;\npublic:\n    Rectangle();\n    Rectangle(int, int);\n    ~Rectangle();\n    int area();\n};\nRectangle::Rectangle() {\n}\nRectangle::Rectangle(int a, int b) {\n    cout << \"Constructor Rect...\";\n}\nRectangle:: ~Rectangle(){\n    cout << \"Destructor Rect.\";\n}\nint Rectangle::area() {\n    return (*width)*(*height);\n}\nint main() {\n    Rectangle recta;\n    cout << \" Rect a...\";\n    return 0;\n}","lang":"cpp","opts":["Constructor Rect...Rect a...Destructor Rect.","Constructor Rect...Rect a...","Rect a...Destructor Rect.","Rect a..."],"ans":"C","exp":"Rectangle recta; gọi constructor mặc định, mà constructor này có thân rỗng nên không in gì. Tiếp theo in Rect a..., rồi cuối chương trình destructor chạy và in Destructor Rect.","topic":"4.2. Phương thức hủy (Destructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"2-72","n":72,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Add\n{\n    int x;\n    int y;\n    int z;\npublic:\n    void getdata()\n    {\n        x = 5;\n        y = 6;\n    }\n    void calculate(void);\n    void display(void);\n};\nvoid Add::calculate()\n{\n    z = x + y;\n}\nvoid Add::display()\n{\n    cout << z;\n}\nvoid main()\n{\n    Add a;\n    a.getdata();\n    a.calculate();\n    a.display();\n}","lang":"cpp","opts":["5","11","6","56","65"],"ans":"B","exp":"getdata chỉ gán x bằng 5 và y bằng 6. calculate tính z bằng x cộng y và ra 11. display in z nên kết quả là 11. Đáp án 56 là bẫy cho ai tưởng chương trình in x rồi in y.","topic":"","note":""},{"id":"2-73","n":73,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Time\n{\n    int hours, minutes;\npublic:\n    void gettime(int h, int m)\n    {\n        hours = h;\n        minutes = m;\n    }\n    void sum(Time, Time);\n    void display(void);\n};\nvoid Time::sum(Time t1, Time t2)\n{\n    minutes = t1.minutes + t2.minutes;\n    hours = minutes / 60;\n    minutes = minutes % 60;\n    hours = hours + t1.hours + t2.hours;\n}\nvoid Time::display()\n{\n    cout << hours << \":\" << minutes << endl;\n}\nvoid main()\n{\n    Time T1, T2, T3;\n    T1.gettime(2, 45);\n    T2.gettime(3, 30);\n    T3.sum(T1, T2);\n    cout << \"Time is \";\n    T3.display();\n}","lang":"cpp","opts":["Time is 6:30","Time is 2:45","Time is 3:30","Time is 6:15"],"ans":"D","exp":"Cộng phút trước: 45 cộng 30 bằng 75. Lấy 75 chia 60 được 1 giờ, còn dư 15 phút. Cộng giờ: 1 cộng 2 cộng 3 bằng 6. Kết quả là 6:15.","topic":"","note":""},{"id":"2-74","n":74,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Add\n{\n    int x, y, z;\npublic:\n    Add(int, int);\n    void calculate(void);\n    void display(void);\n};\nAdd::Add(int a, int b)\n{\n    x = a;\n    y = b;\n}\nvoid Add::calculate()\n{\n    z = x + y;\n}\nvoid Add::display()\n{\n    cout << z;\n}\nvoid main()\n{\n    Add a(5, 6);\n    a.calculate();\n    a.display();\n}","lang":"cpp","opts":["5","6","11","10"],"ans":"C","exp":"Constructor gán x bằng 5 và y bằng 6. calculate tính z bằng 11 rồi display in ra 11. Cách viết này chỉ khác câu 72 ở chỗ dữ liệu vào bằng constructor thay vì bằng hàm getdata.","topic":"","note":""},{"id":"2-75","n":75,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Test {\npublic:\n    int n;\n    void Display(){\n        cout<<n;\n    }\n    public: Test(){\n        n=5;\n    }\n};\nvoid main() {\n    Test t;\n    t.Display();\n}","lang":"cpp","opts":["5","Lỗi biên dịch.","Chương trình thực thi mà không xuất gì ra màn hình.","0"],"ans":"A","exp":"Tất cả thành phần đều public, constructor gán n bằng 5 và Display in ra. Viết public hai lần trong một lớp không sai, C++ cho phép mở lại vùng phạm vi bao nhiêu lần cũng được.","topic":"","note":""},{"id":"2-76","n":76,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class ABC {\n    int n;\npublic:\n      ABC(int x){\n        n=x;\n    }\n    void Print(){\n        cout<<n;\n    }\n};\nvoid main() {\n    ABC t(5);\n    t.Print();\n}","lang":"cpp","opts":["10","Lỗi biên dịch.","Chương trình thực thi mà không xuất gì ra màn hình.","5"],"ans":"D","exp":"ABC t(5) gọi constructor và gán n bằng 5, Print in ra 5. Dữ liệu n là private nhưng Print nằm trong lớp nên đọc được bình thường.","topic":"","note":""},{"id":"2-77","n":77,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class ABC {\n    int n;\npublic:\n    ABC(int x) {\n        n = x;\n    }\n    void Print() {\n        cout << n;\n    }\n};\nvoid main() {\n    ABC t(10);\n    t.Print();\n}","lang":"cpp","opts":["5","Lỗi biên dịch.","Chương trình thực thi mà không xuất gì ra màn hình.","10"],"ans":"D","exp":"Giống câu trước nhưng truyền vào 10 nên n bằng 10 và in ra 10. Hai câu này đặt cạnh nhau để kiểm tra bạn đọc kỹ giá trị truyền vào.","topic":"","note":""},{"id":"2-78","n":78,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Point {\n    int xVal, yVal;\npublic:\n    Point(int x = 0, int y = 0) {\n        xVal = x;\n        yVal = y;\n    }\n    void Print() {\n        cout << \"(\" << xVal << \",\" << yVal << \")\";\n    }\n};\nvoid main() {\n    Point pt(5);\n    pt.Print();\n}","lang":"cpp","opts":["(5,0)","(0,5)","(5,5)","(0,0)"],"ans":"A","exp":"pt(5) chỉ truyền một số nên xVal bằng 5, yVal lấy mặc định là 0, in ra (5,0). Quy tắc là tham số thiếu luôn được lấp từ phải sang trái bằng giá trị mặc định.","topic":"5. PHƯƠNG THỨC VỚI THAM SỐ MẶC ĐỊNH / Ta có thể cung cấp giá trị mặc định trong khai báo hoặc trong định nghĩa hàm, nhưng không thể trong cả 2 (nên cung cấp trong khai báo).","note":""},{"id":"2-79","n":79,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Employee {\n    char ten[30];\n    char ms[10];\n    int tuoi;\npublic:\n    Employee(const char te[], const char m[], int tu) :tuoi(tu)\n    {\n        strcpy_s(ten, te);\n        strcpy_s(ms, m);\n    }\n    void display() {\n        cout << \"Ma so: \" << ms << \" Ten: \" << ten << \" Tuoi:\" << tuoi << endl;\n    }\n};\nvoid main() {\n    Employee e(\"Nguyen Van A\", \"001\", 20);\n    e.display();\n}","lang":"cpp","opts":["Ma so: 001 Ten: Nguyen Van A Tuoi: 20","Ma so: 20 Ten: Nguyen Van A Tuoi: 001","Ma so: 001 Ten: Nguyen Van A Tuoi: 001","Ma so: 20 Ten: Nguyen Van A Tuoi: 20"],"ans":"A","exp":"Constructor nhận tên, mã số và tuổi rồi gán đúng vào từng thuộc tính. Hàm display in theo thứ tự Ma so, Ten, Tuoi nên kết quả là Ma so: 001 Ten: Nguyen Van A Tuoi: 20.","topic":"","note":""},{"id":"2-80","n":80,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Box {\npublic:\n    double length;\n    double breadth;\n    double height;\n};\nint main() {\n    Box Box1;\n    Box Box2;\n    double volume = 0.0;\n    Box1.height = 2.0;\n    Box1.length = 3.0;\n    Box1.breadth = 4.0;\n    Box2.height = 3.0;\n    Box2.length = 5.0;\n    Box2.breadth = 2.0;\n    volume = Box1.height * Box1.length * Box1.breadth;\n    cout << volume << \"-\";\n    volume = Box2.height * Box2.length * Box2.breadth;\n    cout << volume;\n    return 0;\n}","lang":"cpp","opts":["24-30","30-30","30-24","24-24"],"ans":"A","exp":"Box1 có 2 nhân 3 nhân 4 bằng 24, Box2 có 3 nhân 5 nhân 2 bằng 30. Chương trình in thể tích hộp thứ nhất, dấu gạch ngang, rồi thể tích hộp thứ hai nên ra 24-30.","topic":"","note":""}]},{"n":3,"title":"Kế thừa","lang":"C++","qs":[{"id":"3-1","n":1,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class A{\npublic:\n    A(){\n        cout << \"Constructor \";\n    }\n    ~A(){\n        cout << \"Destructor \";\n    }\n};\nint main(){\n    A *a = new A[2];\n    delete a;\n    return 0;\n}","lang":"cpp","opts":["Constructor","Destructor","Constructor Constructor Destructor","Destructor  Destructor Constructor"],"ans":"C","exp":"new A[2] tạo mảng hai đối tượng nên constructor chạy hai lần. Nhưng khi giải phóng lại viết delete a thay vì delete[] a, nên chỉ phần tử đầu tiên được hủy và destructor chỉ chạy một lần. Kết quả là hai lần Constructor và một lần Destructor.","topic":"4.2. Phương thức hủy (Destructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"3-2","n":2,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class A{\npublic:\n    A(){\n        cout << \"Constructor \";\n    }\n    ~A(){\n        cout << \"Destructor \";\n    }\n};\nint main()\n{\n    A *a = new A[2];\n    delete []a;\n    return 0;\n}","lang":"cpp","opts":["Constructor","Destructor","Constructor Constructor Destructor Destructor","Destructor  Destructor Constructor"],"ans":"C","exp":"Lần này viết đúng delete[] a nên cả hai phần tử của mảng đều được hủy. Vì vậy có hai lần Constructor và hai lần Destructor. So với câu trước, chỉ khác cặp ngoặc vuông mà kết quả đã khác.","topic":"4.2. Phương thức hủy (Destructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"3-3","n":3,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Geeks {\npublic:\n    string geekname;\n    void printName() {\n        cout << \"Geekname is:\" << geekname;\n    }\n};\nint main() {\n    Geeks* obj = new Geeks();\n    obj->geekname = \"Abhi\";\n    obj->printName();\n    return 0;\n}","lang":"cpp","opts":["Geekname is:Abhi","Geekname is:","Abhi","Lỗi biên dịch"],"ans":"A","exp":"Đối tượng được tạo đàng hoàng bằng new Geeks() nên con trỏ obj trỏ vào vùng nhớ hợp lệ. Gán tên rồi gọi printName in ra Geekname is:Abhi. Khác hẳn trường hợp con trỏ NULL ở chương 2.","topic":"3.1. Toán tử truy xuất / 3. TRUY XUẤT CÁC THÀNH PHẦN CỦA LỚP","note":""},{"id":"3-4","n":4,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Parent {\nprotected:\n    int id_protected;\n};\nclass Child : public Parent {\npublic:\n    void setId(int id) {\n        id_protected = id;\n    }\n    void displayId() {\n        cout << \"ID Protected is: \" << id_protected << endl;\n    }\n};\nint main() {\n    Child obj1;\n    obj1.setId(68);\n    obj1.displayId();\n    return 0;\n}","lang":"cpp","opts":["68","ID Protected is:68","ID Protected is:0","Lỗi biên dịch"],"ans":"B","exp":"id_protected là protected nên lớp con Child dùng được. setId gán 68, displayId in ra nguyên câu kèm giá trị nên kết quả là ID Protected is: 68.","topic":"2.2. Phạm vi truy cập / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-5","n":5,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Parent{\nprotected:\n    int id_protected = 0;\n};\nclass Child : public Parent{\npublic:\n    void setId(int id){\n        id_protected = id;\n    }\n    void displayId(){\n        cout << \"ID Protected is: \" << id_protected << endl;\n    }\n};\nint main() {\n    Child obj;\n    obj.displayId();\n    return 0;\n}","lang":"cpp","opts":["68","ID Protected is:68","ID Protected is:0","Lỗi biên dịch"],"ans":"C","exp":"Chương trình không gọi setId nên id_protected giữ nguyên giá trị khởi tạo là 0. displayId in ra ID Protected is: 0.","topic":"2.2. Phạm vi truy cập / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-6","n":6,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, lựa chọn nào được viết ở dòng //access variable here, khi biên dịch chương trình sẽ không có lỗi?","code":"class A {\n    int a;\n    int b;\npublic:\n    float f1;\n    float f2;\n};\nclass B : public A {\npublic:\n    void displayId(){\n        //access variable here\n    }\n};\nint main() {\n    B obj;\n    obj.displayId();\n    return 0;\n}","lang":"cpp","opts":["f1= 6; f2 = 8;","a = 6;","a = 6; b = 8;","a = 6; b = 8; f1= 6; f2 = 8;"],"ans":"A","exp":"Trong lớp A, a và b không ghi phạm vi nên mặc định là private, còn f1 và f2 là public. Lớp con không bao giờ chạm được vào phần private của lớp cha, nên chỉ gán được f1 và f2.","topic":"2.2. Phạm vi truy cập / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-7","n":7,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, lựa chọn nào được viết ở dòng //access variable here, khi biên dịch chương trình sẽ không có lỗi?","code":"class A{\nprivate:\n    int a;\nprotected:\n    int b;\npublic:\n    float f1;\n    float f2;\n};\nclass B : protected A {\npublic:\n    void displayId(){\n        //access variable here\n    }\n};\nint main() {\n    B obj;\n    obj.displayId();\n    return 0;\n}","lang":"cpp","opts":["a= 6; f2 = 8;","a = 6;","a = 6; b = 8;","b = 8; f1= 6; f2 = 8;"],"ans":"D","exp":"Lớp con truy cập được protected và public của lớp cha, tức là b, f1, f2. Riêng a là private nên bị chặn. Kiểu kế thừa protected chỉ ảnh hưởng tới người dùng bên ngoài, còn bên trong lớp con thì quy tắc vẫn như trên.","topic":"2.2. Phạm vi truy cập / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-8","n":8,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, lựa chọn nào được viết ở dòng //access variable here, khi biên dịch chương trình sẽ không có lỗi?","code":"class A\n{\n    int a;\n    int b;\n    float f1;\n    float f2;\n};\nclass B :public A\n{\npublic:\n    void displayId() {\n        //access variable here\n    }\n};\nint main() {\n    B obj;\n    obj.displayId();\n    return 0;\n}","lang":"cpp","opts":["a= 6; f2 = 8;","a = 6;","a = 6; b = 8;","Cả 3 đáp án đều sai"],"ans":"D","exp":"Lớp A không ghi từ khóa phạm vi nào cả nên toàn bộ bốn biến đều là private. Lớp con không dùng được biến nào, vì vậy cả ba đáp án đầu đều sai.","topic":"2.2. Phạm vi truy cập / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-9","n":9,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, lựa chọn nào được viết ở dòng //access variable here, khi biên dịch chương trình sẽ không có lỗi?","code":"class A\n{\n    char x, y;\nprivate:\n    int a;\nprotected:\n    int b;\npublic:\n    float f1;\n    float f2;\n};\nclass B :public A\n{\npublic:\n    void displayId() {\n        //access variable here\n    }\n};\nint main() {\n    B obj;\n    obj.displayId();\n    return 0;\n}","lang":"cpp","opts":["a= 6; f2 = 8;x = 7; y = 9","a = 6; x = 7; y = 9","a = 6; b = 8;","b = 8; f1= 6; f2 = 8;"],"ans":"D","exp":"x và y khai báo trước mọi từ khóa phạm vi nên mặc định là private, a cũng private, b là protected, f1 và f2 là public. Lớp con chỉ dùng được b, f1, f2.","topic":"2.2. Phạm vi truy cập / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-10","n":10,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch chương trình, lỗi ở dòng nào:","code":"1   class RectangleInt\n2   {\n3   private:\n4       int a = 7;\n5       int b = 9;\n6       friend void output();\n7   };\n8   class RectangleFloat\n9   {\n10  private:\n11      float x = 6;\n12      float y = 8;\n13      friend void output();\n14  };\n15  void output()\n16  {\n17      RectangleInt obj1;\n18      RectangleFloat obj2;\n19      cout << obj1.a;\n20      cout << obj2.x;\n21  }\n22  int main() {\n23      output();\n24      return 0;\n25  }","lang":"cpp","opts":["Không dòng nào có lỗi","Lỗi tại dòng 15","Lỗi tại dòng 13","Lỗi tại dòng 16, 17"],"ans":"A","exp":"Cả hai lớp đều khai báo friend void output(); và hàm output được định nghĩa đúng tên ở dòng 15. Hàm bạn được phép đọc thành phần private nên chương trình không có lỗi ở dòng nào.","topic":"9.1. Hàm bạn (Friend function) / 9. HÀM BẠN VÀ LỚP BẠN","note":""},{"id":"3-11","n":11,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, lựa chọn nào được viết ở dòng //access variable here, khi biên dịch chương trình sẽ không có lỗi?","code":"class RectangleInt {\nprivate:\n    int a;\n    int b;\npublic:\n    float x;\n    float y;\n    friend class RectangleFloat;\n};\nclass RectangleFloat {\n    RectangleInt rectInt;\npublic:\n    void displayId(){\n        //access variable here\n    }\n};\nint main() {\n    RectangleFloat obj;\n    obj.displayId();\n    return 0;\n}","lang":"cpp","opts":["rectInt.a = 5; rectInt.b = 5;","rectInt.x = 5; rectInt.y = 5;","rectInt.a = 5; rectInt.b = 5; rectInt.x = 5; rectInt.y = 5;","Cả 3 đáp án đều sai"],"ans":"C","exp":"RectangleFloat được khai báo là lớp bạn của RectangleInt, mà lớp bạn được phép đọc cả private lẫn public. Vì vậy cả bốn biến a, b, x, y đều gán được. Đề gốc để trống đáp án, đây là phương án đúng theo lý thuyết hàm bạn và lớp bạn.","topic":"9.1. Hàm bạn (Friend function) / 9. HÀM BẠN VÀ LỚP BẠN","note":"Đề gốc không in đáp án cho câu này."},{"id":"3-12","n":12,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, lựa chọn nào được viết ở dòng //your code here, khi biên dịch chương trình sẽ không có lỗi?","code":"class RectangleInt {\npublic:\n    int a = 0;\npublic:\n    int b = 0;\n    void input(){\n        cout<<\"\\n a = \";\n        cout<<\"\\n b =\";\n    }\n};\nclass RectangleFloat : public RectangleInt{\n    RectangleInt *p;\npublic:\n    void displayId(){\n        //your code here\n    }\n};\nint main() {\n    RectangleFloat obj;\n    obj.displayId();\n    return 0;\n}","lang":"java","opts":["p.nhap();","p(nhap();","this.nhap( ); RectangleInt::nhap();","Cả 3 đáp án đều sai"],"ans":"D","exp":"Cả ba cách viết đều sai. Lớp chỉ có phương thức tên input chứ không có nhap, p là con trỏ nên phải dùng mũi tên chứ không dùng dấu chấm, còn cách viết p(nhap(); thì sai cú pháp. Đề gốc để trống đáp án, phương án đúng là cả ba đều sai.","topic":"","note":"Đề gốc không in đáp án cho câu này."},{"id":"3-13","n":13,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"1   class RectangleInt\n2   {\n3   private:\n4       int a = 7;\n5       int b = 9;\n6       friend void output();\n7   };\n8   class RectangleFloat\n9   {\n10  private:\n11      float x = 6;\n12      float y = 8;\n13      friend void output();\n14  };\n15  void output()\n16  {\n17      RectangleInt obj1;\n18      RectangleFloat obj2;\n19      cout << obj1.a;\n20      cout << obj2.x;\n21  }\n22  int main() {\n23      output();\n24      return 0;\n25  }","lang":"cpp","opts":["6","8","76","Lỗi biên dịch"],"ans":"C","exp":"Hàm output là bạn của cả hai lớp nên đọc được a và x. Nó in a bằng 7 trước rồi in x bằng 6, hai số dính liền nhau thành 76.","topic":"9.1. Hàm bạn (Friend function) / 9. HÀM BẠN VÀ LỚP BẠN","note":""},{"id":"3-14","n":14,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, lựa chọn nào được viết ở dòng //you code here, sử dụng truy xuất phương thức display()?","code":"class RectangleA\n{\n    int a = 6;\npublic:\n    void display() {\n        cout << a;\n    }\n};\nint main() {\n    RectangleA rectA;\n    //you code here\n    return 0;\n}","lang":"cpp","opts":["rectA.display();","*rectA.display();","rectA(display();","RectangleA::display();"],"ans":"A","exp":"rectA là đối tượng thường nên gọi phương thức bằng dấu chấm: rectA.display(). Dấu sao dùng cho con trỏ, còn RectangleA::display() chỉ đúng khi display là phương thức tĩnh.","topic":"","note":""},{"id":"3-15","n":15,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, phương thức ~Rectangle(){} được gọi là?","code":"class Rectangle\n{\nprivate:\n    int w;\n    int h;\npublic:\n    Rectangle(int w = 0, int h = 0){}\n    void output(){}\n    ~Rectangle(){}\n};","lang":"cpp","opts":["Phương thức khởi tạo (Constructor)","Phương thức huỷ (Destructor)","Phương thức bạn (friend)","Phương thức ảo (Virtual)"],"ans":"B","exp":"Phương thức có dấu ngã trước tên lớp là phương thức hủy. Nó tự chạy khi đối tượng hết phạm vi sống, không cần gọi tay.","topic":"4.2. Phương thức hủy (Destructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"3-16","n":16,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, phương thức Rectangle(){} được gọi là?","code":"public class Rectangle\n{\n    private int w;\n    private int h;\n    public Rectangle(){}\n    public Rectangle(int w, int h){}\n    void Output(){}\n}","lang":"csharp","opts":["Phương thức khởi tạo (Constructor)","Phương thức huỷ (Destructor)","Phương thức bạn (friend)","Phương thức ảo (Virtual)"],"ans":"A","exp":"Trong C# cũng vậy, hàm trùng tên lớp và không có kiểu trả về là constructor. Lớp này có hai constructor, phân biệt nhau bằng số tham số.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.1. Constructor","note":""},{"id":"3-17","n":17,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"const double PI = 3.14159;\nclass Circle {\nprivate: double radius;\npublic:\n   Circle(double rad) : radius(rad) {}\n   double calculateArea() {\n      return PI * pow(radius, 2);\n   }\n   double calculateCircumference() {\n      return 2 * PI * radius;\n   }\n};\nint main() {\n   Circle circle(6);\n   double area = circle.calculateArea();\n   cout << \"Area: \" << area;\n   double circumference = circle.calculateCircumference();\n   cout << \" Circumference: \" << circumference;\n   return 0;\n}","lang":"cpp","opts":["Area: 2","Area: 3.14159","Circumference: 3.14159","Area: 113.097 Circumference: 37.6991"],"ans":"D","exp":"Diện tích bằng PI nhân 6 mũ 2, tức 3.14159 nhân 36 và ra 113.097. Chu vi bằng 2 nhân PI nhân 6 và ra 37.6991. Chương trình in cả hai nên chọn đáp án ghi đủ.","topic":"4.1. Phương thức khởi tạo (Constructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"3-18","n":18,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Rectangle\n{\nprivate:\n    double length;\n    double width;\npublic:\n    Rectangle(double len, double wid) : length(len), width(wid) {}\n    double calculateArea()\n    {\n        return length * width;\n    }\n    double calculatePerimeter()\n    {\n        return 2 * (length + width);\n    }\n};\nint main()\n{\n    Rectangle rectangle(4.5, 6.0);\n    double area = rectangle.calculateArea();\n    cout << \"Area: \" << area;\n    double perimeter = rectangle.calculatePerimeter();\n    cout << \" Perimeter: \" << perimeter;\n    return 0;\n}","lang":"cpp","opts":["Perimeter: 27","Perimeter: 21","Area: 27 Perimeter: 21","Area: 27"],"ans":"C","exp":"Diện tích bằng 4.5 nhân 6 bằng 27. Chu vi bằng 2 nhân tổng 4.5 với 6, tức 2 nhân 10.5 bằng 21. Chương trình in lần lượt cả hai giá trị.","topic":"4.1. Phương thức khởi tạo (Constructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"3-19","n":19,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Person {\nprivate: string name;\n   int age;\n   string country;\npublic:\n   void setName(const string & n) {\n      name = n;\n   }\n   void setAge(int a) {\n      age = a;\n   }\n   void setCountry(const string & c) {\n      country = c;\n   }\n   string getName() {\n      return name;\n   }\n   int getAge() {\n      return age;\n   }\n   string getCountry() {\n      return country;\n   }\n};\nint main() {\n   Person person;\n   person.setName(\"Saveli Sujatha\");\n   person.setAge(25);\n   person.setCountry(\"USA\");\n   cout << \"Name: \" << person.getName();\n   cout << \", Age: \" << person.getAge() ;\n   cout << \", Country: \" << person.getCountry();\n   return 0;\n}","lang":"cpp","opts":["Name: Saveli Sujatha","Name: Saveli Sujatha, Age: 25","Name: Saveli Sujatha, Country: USA, Age: 25","Name: Saveli Sujatha, Age: 25, Country: USA"],"ans":"D","exp":"Ba hàm set gán đủ ba thuộc tính, sau đó ba hàm get lấy ra in theo đúng thứ tự trong main là tên, tuổi rồi quốc gia. Đây là ví dụ chuẩn của tính đóng gói: dữ liệu private, ra vào qua hàm get và set.","topic":"","note":""},{"id":"3-20","n":20,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Car\n{\nprivate:\n    string company;\n    string model;\n    int year;\npublic:\n    Car(const string &comp,\n        const string &mdl, int yr) : company(comp), model(mdl), year(yr) {}\n    string getCompany()\n    {\n        return company;\n    }\n    string getModel()\n    {\n        return model;\n    }\n    int getYear()\n    {\n        return year;\n    }\n    void setCompany(const string &comp)\n    {\n        company = comp;\n    }\n    void setModel(const string &mdl)\n    {\n        model = mdl;\n    }\n    void setYear(int yr)\n    {\n        year = yr;\n    }\n};\nint main()\n{\n    Car car(\"AUDI\", \"A6\", 2023);\n    cout << \"Company: \" << car.getCompany();\n    cout << \", Model: \" << car.getModel();\n    cout << \", Year: \" << car.getYear();\n    return 0;\n}","lang":"cpp","opts":["Model: A6, Year: 2023, Company: AUDI","Company: AUDI, Year: 2023, Model: A6","Company: AUDI, Model: A6, Year: 2023","Year: 2023, Company: AUDI, Model: A6,"],"ans":"C","exp":"Constructor dùng danh sách khởi tạo gán đủ ba thuộc tính. main in theo thứ tự getCompany, getModel, getYear nên ra Company: AUDI, Model: A6, Year: 2023.","topic":"4.1. Phương thức khởi tạo (Constructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"3-21","n":21,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class BankAccount {\nprivate:\n   string accNumber;\n   double balance;\npublic:\n   BankAccount(const string &accNum, double ib):accNumber(accNum),balance(ib) {}\n   void deposit(double amount) {\n      balance += amount;\n      cout << \", Deposit successful: \" << balance ;\n   }\n};\nint main() {\n   double deposit_amt;\n   BankAccount account(\"SB-123\", 1000.0);\n   deposit_amt = 1500;\n   cout<<\"Amount: \"<<deposit_amt << \". \";\n   account.deposit(deposit_amt);\n   return 0;\n}","lang":"cpp","opts":["Amount: 1500","Deposit successful: 2500","Amount: 1000, Deposit successful: 1500","Amount: 1500, Deposit successful: 2500"],"ans":"D","exp":"Số dư ban đầu là 1000. main in Amount: 1500 trước, sau đó deposit cộng thêm 1500 vào số dư thành 2500 rồi in tiếp. Ghép hai phần lại thành đáp án D.","topic":"4.1. Phương thức khởi tạo (Constructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"3-22","n":22,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Triangle {\nprivate: double side1;\n   double side2;\n   double side3;\npublic:\n   Triangle(double s1, double s2, double s3) : side1(s1),   side2(s2), side3(s3) {}\n   void determineType() {\n      if (side1 == side2 && side2 == side3) {\n         cout << \"Equilateral Triangle\";\n      }\n      else if (side1 == side2 || side1 == side3 || side2 == side3) {\n         cout << \"Isosceles Triangle\" ;\n      }\n      else {\n         cout << \"Scalene Triangle\" ;\n      }\n   }\n};\nint main() {\n   Triangle triangle(3, 4, 5);\n   triangle.determineType();\n   return 0;\n}","lang":"cpp","opts":["Scalene Triangle","Equilateral Triangle","Isosceles Triangle","Lỗi biên dịch"],"ans":"A","exp":"Ba cạnh 3, 4, 5 khác nhau hoàn toàn nên không rơi vào nhánh đều cũng không rơi vào nhánh cân. Chương trình chạy vào else và in Scalene Triangle, tức tam giác thường.","topic":"4.1. Phương thức khởi tạo (Constructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"3-23","n":23,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Triangle\n{\nprivate:\n    double side1;\n    double side2;\n    double side3;\npublic:\n    Triangle(double s1, double s2, double s3) : side1(s1), side2(s2), side3(s3) {}\n    void determineType()\n    {\n        if (side1 == side2 && side2 == side3)\n        {\n            cout << \"Equilateral Triangle\";\n        }\n        else if (side1 == side2 || side1 == side3 || side2 == side3)\n        {\n            cout << \"Isosceles Triangle\";\n        }\n        else\n        {\n            cout << \"Scalene Triangle\";\n        }\n    }\n};\nint main()\n{\n    Triangle triangle(7, 7, 7);\n    triangle.determineType();\n    return 0;\n}","lang":"cpp","opts":["Scalene Triangle","Equilateral Triangle","Isosceles Triangle","Lỗi biên dịch"],"ans":"B","exp":"Ba cạnh đều bằng 7 nên điều kiện đầu tiên đúng ngay và in Equilateral Triangle. Khi if đầu đã đúng thì các nhánh else phía sau không được xét nữa.","topic":"4.1. Phương thức khởi tạo (Constructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"3-24","n":24,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch chương trình, lỗi tại dòng nào?","code":"class A {\n   int x, y;\npublic:\n   void output(){};\n   void input(){};\n};\nclass B : public A {\nprivate:\n   float z;\n};\nvoid main()\n{\n   A a;\n   B b;\n   a = b;\n   b = a;\n}","lang":"cpp","opts":["class B : public A","a=b","b=a;","A a;"],"ans":"C","exp":"Lớp con luôn chứa đủ phần của lớp cha nên gán a = b được, phần dư của B đơn giản bị bỏ đi. Ngược lại b = a thì thiếu dữ liệu cho biến z của B nên trình biên dịch báo lỗi. Nhớ quy tắc: gán từ con sang cha thì được, từ cha sang con thì không.","topic":"2.6. Chuyển đổi kiểu dữ liệu giữa lớp cơ sở và lớp dẫn xuất / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-25","n":25,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class A{\n   float x;\npublic:\n    A(){\n      x = 1.5;\n   }\n   void output(){\n      cout << x;\n   }\n};\nclass B : public A {\n   float y;\npublic:\n   B():A(){\n      y = 2.5;\n   }\n   void output(){\n      A::A();\n      cout << y;\n   }\n};\nvoid main()\n{\n   B * dt2 = new B;\n   dt2->output();\n}","lang":"cpp","opts":["1.5","2.5","1.5 2.5","Các đáp án đều sai"],"ans":"B","exp":"dt2->output() gọi hàm output của lớp B vì B đã định nghĩa lại hàm này và biến dt2 có kiểu B. Dòng A::A(); không khởi tạo lại đối tượng hiện tại, nó không in gì cả. Vì vậy màn hình chỉ hiện 2.5.","topic":"2.5. Ghi đè phương thức (Overriding) / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-26","n":26,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class A\n{\n    int a, b;\npublic:\n    A()\n    {\n        a = 5;\n        b = 10;\n    }\n    static void output()\n    {\n        cout << \"a = \" << a << \" b = \" << b:\n    }\n};\nstatic A::b = 15;\nvoid main()\n{\n    A a;\n    a.output();\n}","lang":"cpp","opts":["a=5;b=0;","Chương trình có lỗi, không thể hiển thị kết quả (vì lỗi dòng static A::b = 15;)","a=5;b=15;","a=5;b=10;"],"ans":"B","exp":"Chương trình có hai lỗi cú pháp rõ ràng. Dòng cout kết thúc bằng dấu hai chấm thay vì dấu chấm phẩy, và dòng static A::b = 15; vừa thiếu kiểu dữ liệu vừa gán cho biến không phải static. Ngoài ra phương thức tĩnh cũng không được dùng biến thường a, b.","topic":"6.2. Phương thức tĩnh / 6. THUỘC TÍNH TĨNH VÀ PHƯƠNG THỨC TĨNH","note":""},{"id":"3-27","n":27,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình trên môi trường có kích thước số nguyên là 4 byte, kết quả là gì?","code":"class BaseClass\n{\n    int arr[10];\n};\nclass A : public BaseClass\n{\n};\nclass B : public BaseClass\n{\n};\nclass Derived : public A, public B\n{\n};\nint main(void)\n{\n    cout << sizeof(Derived);\n    return 0;\n}","lang":"cpp","opts":["40","80","20","400"],"ans":"B","exp":"BaseClass chứa mảng 10 số nguyên nên chiếm 40 byte. A và B mỗi lớp kế thừa một bản của BaseClass. Derived kế thừa cả A và B nên chứa hai bản, tổng cộng 80 byte. Đây chính là vấn đề kim cương, muốn còn một bản thì phải dùng kế thừa ảo.","topic":"","note":""},{"id":"3-28","n":28,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, chương trình lỗi ở dòng nào?","code":"class A {\n    int a;\n    public:\n    A(int k){\n        a=k; //Dòng 1\n    }\n};\nvoid main(){\n    int n=2;\n    A *a =new A(10); //Dòng 2\n    A *b=new A [n]; //Dòng 3\n}","lang":"cpp","opts":["Dòng 1","Dòng 2","Dòng 3","Cả ba dòng đều lỗi"],"ans":"C","exp":"Dòng 3 viết new A[n] để tạo mảng đối tượng, mà tạo mảng thì bắt buộc phải có constructor không tham số. Lớp A chỉ có constructor một tham số nên dòng này lỗi. Dòng 2 không sao vì có truyền số 10 vào.","topic":"4.1. Phương thức khởi tạo (Constructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"3-29","n":29,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class A {\n   int a;\npublic:\n   A(){\n      a = 5;\n   }\n   A(int k){\n      a = k;\n   }\n   void output(){\n      cout << \"a = \" << a;\n   }\n};\nvoid main(){\n   A a[3] = { A(10), A(20) };\n   a[2].output();\n}","lang":"cpp","opts":["a=10;","a=5;","a=20;","Lỗi biên dịch"],"ans":"B","exp":"Mảng có ba phần tử nhưng danh sách khởi tạo chỉ cho hai giá trị. Phần tử a[2] không được cấp giá trị nên gọi constructor mặc định và a bằng 5. Quy tắc chung: tạo mảng n đối tượng thì có n constructor được gọi.","topic":"4.1. Phương thức khởi tạo (Constructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"3-30","n":30,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class A {\npublic:\n   static int n;\n};\nint A::n = 10;\nvoid main() {\n   A a;\n   cout << ++a.n;\n}","lang":"cpp","opts":["10","11","12","Lỗi biên dịch"],"ans":"B","exp":"n là biến static, giá trị ban đầu là 10. Phép ++a.n tăng trước rồi mới in nên kết quả là 11. Truy cập biến static qua tên đối tượng vẫn hợp lệ dù cách chuẩn hơn là A::n.","topic":"4.1. Phương thức khởi tạo (Constructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"3-31","n":31,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class A{\nprotected:\n   int a, b;\npublic:\n   void output(){\n      cout<<\"a = \"<<a<<\" b = \"<<b;\n   }\n   A(){\n      a = b= 10;\n   }\n   A(int k1, int k2 = 8){\n      a = k1; b = k2;\n   }\n};\nint main(){\n   A a(5);\n   A b(a);\n   b.output();\n}","lang":"cpp","opts":["a=10; b=8;","a=10; b=5;","a=10; b=10;","a=5; b=8;"],"ans":"D","exp":"A a(5) chỉ truyền một số nên a bằng 5 còn b lấy giá trị mặc định là 8. A b(a) dùng constructor sao chép mặc định nên chép nguyên cặp giá trị 5 và 8 sang b.","topic":"4.1. Phương thức khởi tạo (Constructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"3-32","n":32,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Base {\npublic:\n   Base(){\n      cout << \"Constructing Base \";\n   }\n   ~Base(){\n      cout << \"Destructing Base \";\n   }\n};\nclass Derived : public Base {\npublic:\n   Derived(){\n      cout << \"Constructing Derived \";\n   }\n   ~Derived(){\n      cout << \"Destructing Derived \";\n   }\n};\nint main(void){\n   Derived *d = new Derived();\n   Base *b = d;\n   delete b;\n   return 0;\n}","lang":"cpp","opts":["Constructing Base","Constructing Derived","Constructing Base Destructing Base","Constructing Base Constructing Derived Destructing Base"],"ans":"D","exp":"Tạo Derived thì constructor chạy từ cha xuống con nên in Constructing Base rồi Constructing Derived. Khi delete qua con trỏ kiểu Base mà destructor không khai báo virtual, chỉ destructor của Base chạy nên chỉ in Destructing Base. Muốn hủy đủ thì lớp cha phải có destructor ảo.","topic":"2.4. Phương thức khởi tạo và phương thức hủy trong lớp dẫn xuất / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-33","n":33,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class ABC\n{\npublic:\n    int a, b;\n    void nhap()\n    {\n        a = 10;\n        b = 10;\n    }\n};\nvoid main()\n{\n    ABC *obj = new ABC();\n    obj->a = 3;\n    obj->b = 5;\n    cout << obj->a;\n}","lang":"cpp","opts":["10","5","3","Lỗi biên dịch"],"ans":"C","exp":"obj là con trỏ, hai lệnh gán sửa a thành 3 và b thành 5. Hàm nhap không hề được gọi nên hai số 10 không có tác dụng. Lệnh in cuối cùng in a nên ra 3.","topic":"3.1. Toán tử truy xuất / 3. TRUY XUẤT CÁC THÀNH PHẦN CỦA LỚP","note":""},{"id":"3-34","n":34,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Base {\nprivate:\n    int a, b;\n};\nclass Derived {\npublic:\n    Base obj1;\n    void setValues() {\n        obj1.a = 12;\n        obj1.b = 8;\n    }\n    void printValues() {\n        cout << obj1.a + obj1.a;\n    }\n};\nvoid main() {\n    Derived obj;\n    obj.setValues();\n    obj.printValues();\n}","lang":"cpp","opts":["8","12","24","Lỗi biên dịch do biến a, b của lớp Base là private"],"ans":"D","exp":"Derived không kế thừa Base, nó chỉ chứa một đối tượng Base làm thuộc tính. Mà a và b của Base là private nên Derived không đụng vào được, chương trình lỗi biên dịch.","topic":"3.2. Phạm vi truy cập của thuộc tính và phương thức / 3. TRUY XUẤT CÁC THÀNH PHẦN CỦA LỚP","note":""},{"id":"3-35","n":35,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Base {\npublic:\n   int a, b;\n};\nclass Derived {\npublic:\n   Base obj1;\n   void setValues() {\n      obj1.a = 12;\n      obj1.b = 8;\n   }\n   void printValues() {\n      cout << obj1.a + obj1.a;\n   }\n};\nvoid main() {\n   Derived obj;\n   obj.setValues();\n   obj.printValues();\n}","lang":"cpp","opts":["8","12","24","Lỗi biên dịch do biến a, b của lớp Base là public"],"ans":"C","exp":"Lần này a và b của Base là public nên Derived gán và đọc bình thường. Chú ý hàm printValues in obj1.a cộng obj1.a, tức 12 cộng 12 bằng 24 chứ không phải cộng với b.","topic":"3.2. Phạm vi truy cập của thuộc tính và phương thức / 3. TRUY XUẤT CÁC THÀNH PHẦN CỦA LỚP","note":""},{"id":"3-36","n":36,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Derived {\npublic:\n   int a, b;\npublic:\n   void setValues(int  a, int  b) {\n      this->a = a; this->b = b;\n   }\n   void printValues() {\n      cout << a + b;\n   }\n};\nvoid main() {\n   Derived obj;\n   obj.setValues(6,8);\n   obj.printValues();\n}","lang":"cpp","opts":["8","6","14","Lỗi biên dịch"],"ans":"C","exp":"Tham số trùng tên với thuộc tính, nên bên trong hàm phải dùng this->a để chỉ thuộc tính của đối tượng. Nhờ có this, hai giá trị 6 và 8 được lưu đúng chỗ và printValues in ra 14.","topic":"3.3. Con trỏ this / 3. TRUY XUẤT CÁC THÀNH PHẦN CỦA LỚP","note":""},{"id":"3-37","n":37,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class BankAccount {\nprivate:\n    string accountNumber;\n    double balance;\npublic:\n    BankAccount(string accNum, double initBalance) : accountNumber(accNum), balance(initBalance) {}\n    void deposit(double amount) {\n        if (amount > 0) {\n            balance += amount;\n        }\n    }\n    void withdraw(double amount) {\n        if (amount > 0 && balance >= amount) {\n            balance -= amount;\n        }\n    }\n    double getBalance() {\n        return balance;\n    }\n};\nint main() {\n    BankAccount myAccount(\"12345\", 1000);\n    cout << \" Initial:\" << myAccount.getBalance() ;\n    myAccount.deposit(500);\n    cout << \" Deposit:\" << myAccount.getBalance() ;\n    myAccount.withdraw(300);\n    cout << \" Withdrawal:\" << myAccount.getBalance() ;\n    return 0;\n}","lang":"cpp","opts":["Initial:1000","Deposit:1500","Withdrawal:1200","Initial:1000 Deposit:1500 Withdrawal:1200"],"ans":"D","exp":"Ban đầu 1000, gửi thêm 500 thành 1500, rút 300 còn 1200. Mỗi lần main gọi getBalance lại in ra con số tại thời điểm đó nên màn hình hiện đủ ba mốc.","topic":"4.1. Phương thức khởi tạo (Constructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"3-38","n":38,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Quiz {\npublic:\n    static void start(int s) {\n        correctAnswers = s;\n    }\n    static void startScore() {\n        score = correctAnswers * correctAnswers;\n    }\n    static void outResult() {\n        cout << \"Score:\" << score;\n    }\nprivate:\n    static const string questions;\n    static int correctAnswers;\n    static int score;\n};\nconst string Quiz::questions = \"What is the Constructor?\";\nint Quiz::correctAnswers= 3;\nint Quiz::score = 0;\nint main() {\n    Quiz::start(5);\n    Quiz::startScore();\n    Quiz::outResult();\n    return 0;\n}","lang":"cpp","opts":["Score: 3","Score: 5","Score: 25","Lỗi biên dịch"],"ans":"C","exp":"Các thuộc tính và phương thức đều là static nên gọi thẳng qua tên lớp mà không cần tạo đối tượng. start gán correctAnswers bằng 5, startScore tính score bằng 5 nhân 5 là 25, outResult in ra 25.","topic":"6.2. Phương thức tĩnh / 6. THUỘC TÍNH TĨNH VÀ PHƯƠNG THỨC TĨNH","note":""},{"id":"3-39","n":39,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class A\n{\nprivate:\n   int x = 6;\n};\nclass B : protected A\n{\n   int y = 8;\n   output(){cout<<x+y;}\n};\nvoid main()\n{\n   A test;\n}","lang":"cpp","opts":["Lỗi biên dịch","6","8","14"],"ans":"A","exp":"Lớp B cố dùng biến x của lớp A trong hàm output, nhưng x là private nên lớp con không truy cập được. Ngoài ra hàm output còn thiếu kiểu trả về. Chương trình lỗi biên dịch.","topic":"2.3. Sử dụng các thuộc tính và phương thức trong lớp cơ sở / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-40","n":40,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"01: class A\n02: {\n03: private:\n04:   int a;\n05:   int b;\n06:   friend  void Nhap();\n07: };\n08: class B\n09: {\n10: public:\n11:   float x;\n12:   float y;\n13:   friend void Nhap();\n14: };\n15: void nhap()\n16: {\n17:   A obj1;\n18:      B obj2;\n19:   cout << \"Nhap a = \"; cin >> obj1.a;\n20:   cout << \"\\nNhap x = \"; cin >> obj2.x;\n21: }","lang":"cpp","opts":["Lỗi tại dòng 19","Không lỗi ở dòng nào","Lỗi tại dòng 20","Lỗi tại dòng 19 và 20"],"ans":"A","exp":"Hai lớp khai báo bạn là hàm Nhap viết hoa chữ N, còn hàm được định nghĩa lại tên là nhap viết thường. C++ phân biệt hoa thường nên hàm nhap không phải là bạn của lớp A, do đó dòng 19 đọc obj1.a bị lỗi. Dòng 20 vẫn chạy được vì x là public.","topic":"9.1. Hàm bạn (Friend function) / 9. HÀM BẠN VÀ LỚP BẠN","note":""},{"id":"3-41","n":41,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"1.  class Lop1\n2.  {\n3.  private:\n4.          int a,b;\n5.          friend void Nhap( );\n6.  };\n7.  class Lop2\n8.  {\n9.  private:\n10.          float x,y;\n11.          friend void Nhap( );\n12. };\n13. void Nhap( )\n14. {\n15.      Lop1  obj1; Lop2 obj2;\n16.      cout<<\"\\n\\t Nhap a =\"; cin>>obj1.a;\n17.      cout<<\"\\n\\t Nhap x =\"; cin>>obj2.x;\n18. }","lang":"cpp","opts":["Không lỗi ở dòng nào","Lỗi tại dòng 16, 17","Lỗi tại dòng 15","Lỗi tại dòng 13"],"ans":"A","exp":"Lần này tên hàm bạn khai báo trong hai lớp và tên hàm định nghĩa đều là Nhap viết hoa, khớp nhau hoàn toàn. Hàm bạn đọc được thành phần private nên chương trình không lỗi ở dòng nào. Hãy so sánh với câu 40 để thấy chỉ sai một chữ hoa là kết quả đổi hẳn.","topic":"9.1. Hàm bạn (Friend function) / 9. HÀM BẠN VÀ LỚP BẠN","note":""},{"id":"3-42","n":42,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Lop1\n{\n   private:\n      int   a,b;\n   public:\n      float x,y;\n      friend class Lop2;\n};\nclass Lop2\n{\n   Lop1  objA;\n};\nclass Lop3\n{\n   Lop1  objB;\n};","lang":"cpp","opts":["objA truy cập được tất cả các biến, objB truy cập được các biến x,y","objA và objB truy cập được tất cả các biến","objA và objB chỉ truy cập được các biến x,y","objA truy cập được tất cả các biến, objB truy cập được các biến a,b"],"ans":"A","exp":"Lop1 chỉ khai báo Lop2 là bạn, còn Lop3 thì không. Vì vậy objA trong Lop2 dùng được cả a, b, x, y, còn objB trong Lop3 chỉ dùng được x và y vì hai biến này public. Quan hệ bạn bè không tự động lan sang lớp khác.","topic":"9.1. Hàm bạn (Friend function) / 9. HÀM BẠN VÀ LỚP BẠN","note":""},{"id":"3-43","n":43,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Lop1\n{\nprotected:\n    int a, b;\npublic:\n    void setvalue()\n    {\n        a = b = 10;\n    }\n};\nclass Lop2 : public Lop1\n{\n    int x, y;\npublic:\n    void setvalue()\n    {\n        x = y = 4;\n    }\n};\nNếu tạo ra đối tượng của Lop2 là obj2 và thực hiện lệnh gọi hàm như sau: obj.setvalue( ); thì hàm setvalue của lớp nào sẽ được gọi:","lang":"cpp","opts":["Lop2","Lop1","Cả 2 lớp","Không gọi được hàm nào vì trùng tên hàm"],"ans":"A","exp":"Lop2 định nghĩa lại hàm setvalue trùng tên với lớp cha, đó là ghi đè. Khi gọi qua đối tượng kiểu Lop2 thì hàm của lớp con được chọn, hàm của lớp cha bị che đi. Muốn gọi bản của cha thì phải viết obj.Lop1::setvalue().","topic":"2.5. Ghi đè phương thức (Overriding) / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-44","n":44,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì? Trong lớp Lop2 có thể truy cập được những biến nào:","code":"class Lop1\n{\nprotected:\n    int a, b;\npublic:\n    void setvalue()\n    {\n        a = b = 10;\n    }\n};\nclass Lop2 : public Lop1\n{\n    int x, y;\npublic:\n    void setvalue()\n    {\n        x = y = 4;\n    }\n};","lang":"cpp","opts":["Tất cả biến a, b, x, y","Chỉ có biến x, y","Không truy cập được biến nào","Chỉ truy cập được biến a, b"],"ans":"A","exp":"a và b là protected nên lớp con kế thừa và dùng được, còn x và y là biến riêng của Lop2. Vì vậy bên trong Lop2 dùng được cả bốn biến.","topic":"2.2. Phạm vi truy cập / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-45","n":45,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì? Khi đó, nếu myB là một đối tượng lớp ClassB, lệnh nào sau đúng:","code":"class ClassA{\n    int x;\npublic:\n    int getx();\n};\nvà một lớp kế thừa theo kiểu protected:\nclass ClassB : protected ClassA{\n    int y;\n};","lang":"cpp","opts":["myB.x();","myB.getx;","getx();","Không có đáp án đúng"],"ans":"D","exp":"myB là đối tượng kiểu ClassB mà ClassB kế thừa protected, nên mọi thành phần public của cha bị hạ xuống protected và bên ngoài không gọi được. Ngoài ra x là private ngay từ đầu. Không lệnh nào trong ba lựa chọn chạy được.","topic":"2.3. Sử dụng các thuộc tính và phương thức trong lớp cơ sở / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-46","n":46,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì? Khi đó, nếu myA là một đối tượng lớp ClassA, lệnh nào sau đây đúng:","code":"class ClassA{\n    int x;\npublic:\n    int getx();\n};\nvà một lớp kế thừa theo kiểu public:\nclass ClassB : public ClassA{\n    int y;\n};","lang":"cpp","opts":["myA.getx();","myA.x;","myA.x()","Không có đáp án đúng"],"ans":"A","exp":"myA là đối tượng của chính ClassA, mà getx là hàm public nên gọi bình thường bằng myA.getx(). Biến x là private nên myA.x sai, còn myA.x() thì x không phải hàm nên càng sai.","topic":"2.3. Sử dụng các thuộc tính và phương thức trong lớp cơ sở / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-47","n":47,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class A{\npublic:\n    void show(){ }\n};\nclass B : public A{\npublic:\n    void show() { }\n};\nKhi đó, nếu myB là một đối tượng lớp B, muốn thực hiện phương thức show() của lớp B thì lệnh nào sau đây là chấp chận được:","lang":"cpp","opts":["myB::show();","show();","myB.show();","Không có đáp án đúng"],"ans":"C","exp":"myB là đối tượng thường nên gọi phương thức bằng dấu chấm. Vì B đã định nghĩa lại show nên myB.show() chạy bản của lớp B. Toán tử :: chỉ dùng với tên lớp, không dùng với tên đối tượng.","topic":"2.5. Ghi đè phương thức (Overriding) / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-48","n":48,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì? Hỏi: B sử dụng được các biến thành viên nào của A","code":"class A\n{\n    int a, b;\n    float F1, F2;\n};\nclass B :public A\n{\n    float d;\n};","lang":"cpp","opts":["Không có đáp án đúng","a,b","F1,F2","a,b,F1,F2"],"ans":"A","exp":"Lớp A không ghi từ khóa phạm vi nào nên bốn biến đều là private. Lớp con không dùng được biến nào của cha, nên cả ba lựa chọn liệt kê biến đều sai.","topic":"2.3. Sử dụng các thuộc tính và phương thức trong lớp cơ sở / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-49","n":49,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì? Hỏi: B sử dụng được các biến thành viên nào của A","code":"class A\n{\nprotected:\n    int     a, b;\npublic:\n    float f1, f2;\n};\nclass B : private A\n{\n    int d;\n};","lang":"cpp","opts":["f1, f2, a, b","f1, f2","a, b","Không có đáp án đúng"],"ans":"A","exp":"Kiểu kế thừa private chỉ đổi phạm vi khi nhìn từ bên ngoài, còn bên trong lớp con thì vẫn theo quy tắc cũ: protected và public của cha đều dùng được. Do đó B dùng được a, b, f1, f2.","topic":"2.3. Sử dụng các thuộc tính và phương thức trong lớp cơ sở / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-50","n":50,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì? Hỏi B sử dụng được các biến thành viên nào của A","code":"class A\n{\n    int a, b;\npublic:\n    float f1, f2;\n};\nclass B : private A\n{\npublic:\n    void nhap();\n};","lang":"cpp","opts":["f1, f2","a, b","a,b,f1,f2","Không có đáp án đúng"],"ans":"A","exp":"a và b mặc định là private nên bị chặn hoàn toàn. f1 và f2 là public nên lớp con vẫn dùng được dù kế thừa kiểu private.","topic":"2.3. Sử dụng các thuộc tính và phương thức trong lớp cơ sở / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-51","n":51,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì? B sử dụng được các biến thành viên nào của A","code":"class A\n{\nprotected:\n    int     a, b;\npublic:\n    float f1, f2;\n};\nclass  B : private A\n{\n    float x;\n};","lang":"cpp","opts":["a, b, f1, f2","f1, f2","a, b","Không có đáp án đúng"],"ans":"A","exp":"a và b là protected, f1 và f2 là public, cả bốn đều đến được lớp con. Kế thừa private chỉ làm chúng trở thành private bên trong B chứ không xóa quyền dùng của chính B.","topic":"","note":""},{"id":"3-52","n":52,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Base{\npublic:\n    int xVal;\n    Base(int x = 0) : xVal(x){\n        cout <<\"xVal = \"<<xVal;\n    }\n};\nclass Derive : Base\n{\npublic:\n    Derive(){ xVal = 10; }\n    void Print(){\n        cout <<\" xVal = \"<<xVal<<endl;\n    }\n};\nvoid main(){\n    Derive d;\n    d.Print();\n}","lang":"cpp","opts":["xVal = 0  xVal = 10","Lỗi biên dịch","xVal = 10","xVal = 0"],"ans":"A","exp":"Derive không ghi rõ gọi constructor nào của cha nên trình biên dịch tự gọi Base(0), dòng này in xVal = 0. Sau đó constructor của Derive gán xVal bằng 10 và Print in ra xVal = 10.","topic":"2.4. Phương thức khởi tạo và phương thức hủy trong lớp dẫn xuất / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-53","n":53,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Base{\nprotected:\n    int xVal;\npublic:\n    Base(){ xVal = 5; }\n    void Print(){\n        cout << \"xVal = \" << xVal << endl;\n    }\n};\nclass Derive : protected Base\n{\npublic:\n    Derive(int x) { xVal = x; }\n};\nvoid main()\n{\n    Derive d(10);\n    d.Print();\n}","lang":"cpp","opts":["Lỗi biên dịch","xVal = 5    xVal = 10","xVal = 10","xVal = 5"],"ans":"A","exp":"Derive kế thừa protected nên hàm Print vốn public của Base bị hạ xuống protected trong Derive. Từ main gọi d.Print() là gọi từ bên ngoài nên bị chặn, chương trình lỗi biên dịch.","topic":"2.3. Sử dụng các thuộc tính và phương thức trong lớp cơ sở / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-54","n":54,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class BaseA{\nprotected:\n    int A;\npublic:\n    BaseA(){ A = 5; }\n    void Print(){ cout << \"A = \" << A << endl; }\n};\nclass BaseB {\nprotected:\n    int B;\npublic:\n    BaseB(){ B = 10; }\n    void Print(){ cout << \"B = \" << B << endl; }\n};\nclass Derive :public BaseA, public BaseB {};\nvoid main(){\n    Derive d();\n    d.BaseA::Print();\n}","lang":"cpp","opts":["Lỗi biên dịch.","A =    5    B =    10","B =    10","A =    5"],"ans":"A","exp":"Dòng Derive d(); không tạo đối tượng, trình biên dịch hiểu đó là khai báo một hàm tên d không tham số trả về Derive. Vì vậy dòng sau gọi d.BaseA::Print() bị lỗi. Muốn tạo đối tượng không tham số thì viết Derive d; bỏ cặp ngoặc đi.","topic":"2.1. Tạo đối tượng tự động / 2. KHAI BÁO ĐỐI TƯỢNG","note":""},{"id":"3-55","n":55,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì? Khi thêm lệnh nào vào dòng 10 thì chương trình báo lỗi:","code":"0:template <class T>\n1:T max_number (T a, T b) {\n2:      if (a > b) return a;\n3:      return b;\n4:  }\n5:  float max_number (float fa, float fb) {\n6:    if (fa - fb >0) return fa;\n7:      return fb;\n8:  }\n9:  void main(){\n10:\n11:     cout<< max_number (a,b);\n12: }","lang":"cpp","opts":["char a = ‘A’, b = ‘B’ ;","int a = 5; int b = 6 ;","float a = 5.0, b = 6.0 ;","float a = 5.0; int b = 6 ;"],"ans":"D","exp":"Khuôn mẫu hàm cần hai tham số cùng kiểu T mới suy ra được. Khi truyền một float và một int, trình biên dịch không biết chọn T là gì nên báo lỗi. Ba lựa chọn còn lại đều có hai biến cùng kiểu nên chạy được.","topic":"8.2. Cú pháp / 8. KHUÔN MẪU HÀM","note":""},{"id":"3-56","n":56,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, lệnh nào dưới đây thêm vào dòng 6 thì khi biên dịch chương trình không báo lỗi?","code":"1:    template <class T, class U>\n2:    void func (T a, U b){\n3:         cout<<a<<b ;\n4:    }\n5:    void main(){\n6:\n7:      func(a,b);\n8:    }","lang":"cpp","opts":["float a = 5.0, b = 6.0;","char a = ‘A’ ; char *b = “Hello”;","float a = 5.0; int b = 6;","Các đáp án đều đúng"],"ans":"D","exp":"Khuôn mẫu này khai báo hai kiểu riêng biệt là T và U nên hai tham số truyền vào không cần cùng kiểu. Vì vậy cả ba cách khai báo đều hợp lệ.","topic":"8.2. Cú pháp / 8. KHUÔN MẪU HÀM","note":""},{"id":"3-57","n":57,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"template <class T, int n>\nclass Table{\n    T data[n];\npublic:\n    Table() { }\n    T & operator[](int i){ return data[i]; }\n};\nvoid main(){\n    Table <int, 2>t;\n    t[0] = 0; t[1] = 1;\n    cout << t[0] << \" \" << t[1];\n}","lang":"cpp","opts":["0 1","Một kết quả khác","Lỗi thực thi","Lỗi biên dịch"],"ans":"A","exp":"Khuôn mẫu lớp cho phép truyền kèm một hằng số làm kích thước mảng, ở đây là Table<int, 2>. Toán tử [] được định nghĩa lại nên gán và đọc data bình thường, kết quả in ra 0 1.","topic":"8.2. Cú pháp / 8. KHUÔN MẪU HÀM","note":""},{"id":"3-58","n":58,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Parent\n{\npublic:\n    int id_p;\n};\nclass Child : public Parent\n{\npublic:\n    int id_c;\n};\nint main()\n{\n    Child obj1;\n    obj1.id_c = 6;\n    obj1.id_p = 8;\n    cout << obj1.id_c << \" and \" << obj1.id_p;\n    return 0;\n}","lang":"cpp","opts":["5 and 7","6 and 8","8 and 6","Lỗi biên dịch"],"ans":"B","exp":"Cả id_p lẫn id_c đều là public nên main gán và đọc thoải mái. Chương trình in id_c trước rồi tới id_p, tức 6 and 8.","topic":"2.2. Phạm vi truy cập / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-59","n":59,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Shape\n{\npublic:\n    void setWidth(int w)\n    {\n        width = w;\n    }\n    void setHeight(int h)\n    {\n        height = h;\n    }\nprotected:\n    int width;\n    int height;\n};\nclass Rectangle : public Shape\n{\npublic:\n    int getArea()\n    {\n        return (width * height);\n    }\n};\nint main(void)\n{\n    Rectangle rect;\n    rect.setWidth(6);\n    rect.setHeight(8);\n    cout <<rect.getArea() << endl;\n    return 0;\n}","lang":"cpp","opts":["6","8","48","Lỗi biên dịch"],"ans":"C","exp":"width và height là protected nên Rectangle dùng được trong hàm getArea. setWidth và setHeight là public nên main gọi được. Diện tích là 6 nhân 8 bằng 48.","topic":"2.3. Sử dụng các thuộc tính và phương thức trong lớp cơ sở / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-60","n":60,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Shape\n{\npublic:\n    void setWidth(int w)\n    {\n        width = w;\n    }\n    void setHeight(int h)\n    {\n        height = h;\n    }\nprotected:\n    int width;\n    int height;\n};\nclass PaintCost\n{\npublic:\n    int getCost(int area)\n    {\n        return area * 10;\n    }\n};\nclass Rectangle : public Shape, public PaintCost\n{\npublic:\n    int getArea()\n    {\n        return (width * height);\n    }\n};\nint main(void)\n{\n    Rectangle rect;\n    int area;\n    rect.setWidth(6);\n    rect.setHeight(8);\n    area = rect.getArea();\n    cout << rect.getCost(area) << endl;\n    return 0;\n}","lang":"cpp","opts":["6","480","8","48"],"ans":"B","exp":"Đây là đa kế thừa, Rectangle nhận cả setWidth, setHeight của Shape lẫn getCost của PaintCost. Diện tích là 6 nhân 8 bằng 48, nhân tiếp với 10 thành 480.","topic":"2.3. Sử dụng các thuộc tính và phương thức trong lớp cơ sở / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-61","n":61,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Polygon {\nprotected:\n    int width, height;\npublic:\n    void setValues(int a, int b);\n};\nvoid Polygon::setValues(int a, int b){\n    width = a;\n    height = b;\n}\nclass Rectangle : public Polygon {\npublic:\n    int area();\n};\nint Rectangle :: area(){\n    return (width * height);\n}\nclass Triangle : public Polygon {\npublic:\n    int area();\n};\nint Triangle::area(){\n    return (width * height / 2);\n}\nint main() {\n    Rectangle rect;\n    Triangle trgl;\n    rect.setValues(4, 5);\n    trgl.setValues(4, 5);\n    cout << \"Rectangle area:\" << rect.area() << \" Triangle area:\"<<trgl.area() << endl;\n    return 0;\n}","lang":"cpp","opts":["Rectangle area:10 Triangle area:20","Rectangle area:10 Triangle area:10","Rectangle area:20 Triangle area:10","Lỗi biên dịch do lớp Rectangle khai báo kế thừa sai"],"ans":"C","exp":"Cùng kế thừa từ Polygon nhưng mỗi lớp con tính diện tích theo công thức riêng. Hình chữ nhật ra 4 nhân 5 bằng 20, tam giác ra 4 nhân 5 chia 2 bằng 10.","topic":"2.3. Sử dụng các thuộc tính và phương thức trong lớp cơ sở / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-62","n":62,"stem":"Cho chương trình sau, chương trình sẽ bị lỗi biên dịch tại những dòng lệnh nào?","code":"1\n2 class A{\n3 private:\n4    int x;\n5 protected:\n6    int y;\n7 public:\n8    int z;\n9    void print();\n10 };\n11 void A::print(){\n12   cout << x;\n13   cout << y;\n14   cout << z;\n15 }\n16 class B : public A{\n17 public:\n18   void print();\n19 };\n20 void B::print(){\n21   cout << x;\n22   cout << y;\n23   cout << z;\n24 }\n25 int main() {\n26   A ma;\n27   cout << ma.x << endl;\n28   cout << ma.y << endl;\n29   cout << ma.z << endl;\n30   return 0;\n31 }","lang":"cpp","opts":["21,27,28","3,29","27,28,29","21,22,23"],"ans":"A","exp":"Dòng 21 sai vì B không được đọc x, biến này private trong A. Dòng 27 sai vì ma.x là private, dòng 28 sai vì ma.y là protected. Dòng 29 đọc ma.z hợp lệ vì z là public.","topic":"2.2. Phạm vi truy cập / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-63","n":63,"stem":"Cho chương trình sau, chương trình sẽ bị lỗi biên dịch tại những dòng lệnh nào?","code":"1\n2 class A{\n3 private:\n4    int x;\n5 protected:\n6    int y;\n7 public:\n8    int z;\n9    void print();\n10 };\n11 void A::print(){\n12   cout << x;\n13   cout << y;\n14   cout << z;\n15 }\n16 class B : private A{\n17 public:\n18   void print();\n19 };\n20 void B::print(){\n21   cout << x;\n22   cout << y;\n23   cout << z;\n24 }\n25 int main() {\n26   B mb;\n27   cout << mb.x << endl;\n28   cout << mb.y << endl;\n29   cout << mb.z << endl;\n30   return 0;\n31 }","lang":"cpp","opts":["21,27,28,29","13,29","27,28,29","21,22,23"],"ans":"A","exp":"Dòng 21 vẫn sai như câu trên. Thêm nữa B kế thừa private nên mọi thành phần của A trở thành private trong B, vì vậy từ main không đọc được cả x, y lẫn z, tức là sai luôn ba dòng 27, 28, 29.","topic":"2.3. Sử dụng các thuộc tính và phương thức trong lớp cơ sở / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-64","n":64,"stem":"Cho chương trình sau, chương trình sẽ bị lỗi biên dịch tại những dòng lệnh nào?","code":"1\n2 class A{\n3 private:\n4    int x;\n5 protected:\n6    int y;\n7 public:\n8    int z;\n9    void print();\n10 };\n11 void A::print(){\n12   cout << x;\n13   cout << y;\n14   cout << z;\n15 }\n16 class B : protected A{\n17 public:\n18   void print();\n19 };\n20 void B::print(){\n21   cout << x;\n22   cout << y;\n23   cout << z;\n24 }\n25 int main() {\n26   B mb;\n27   cout << mb.x << endl;\n28   cout << mb.y << endl;\n29   cout << mb.z << endl;\n30   return 0;\n31 }","lang":"cpp","opts":["21,27,28,29","13,29","27,28,29","21,22,23"],"ans":"A","exp":"Kế thừa protected biến mọi thành phần của A thành protected trong B, mà protected thì bên ngoài vẫn không đọc được. Kết quả giống hệt câu trước: lỗi ở dòng 21 và cả ba dòng 27, 28, 29.","topic":"2.3. Sử dụng các thuộc tính và phương thức trong lớp cơ sở / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-65","n":65,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Polygon {\nprotected:\n    int width, height;\npublic:\n    Polygon(int a);\n    void  setValues(int a, int b);\n};\nPolygon::Polygon(int a){\n    width = a;\n}\nvoid Polygon::setValues(int a, int b){\n    width = a;\n    height = b;\n}\nclass Rectangle : public Polygon {\npublic:\n    Rectangle(int w, int h);\n        int area();\n};\nRectangle::Rectangle(int w, int h) :Polygon(w){\n    height = h;\n}\nint Rectangle::area(){\n    return (width * height);\n}\nint main() {\n    Rectangle rect(8, 9);\n    cout << rect.area() << endl;\n    return 0;\n}","lang":"cpp","opts":["17","72","8","20"],"ans":"B","exp":"Constructor của Rectangle gọi Polygon(w) để gán width bằng 8, rồi tự gán height bằng 9. Diện tích là 8 nhân 9 bằng 72.","topic":"2.3. Sử dụng các thuộc tính và phương thức trong lớp cơ sở / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-66","n":66,"stem":"Lớp B kế thừa lớp A trong ngôn ngữ C++ được khai báo như thế nào ?","code":"","lang":"cpp","opts":["class A : public B","class B extern A","class B : public A","class B implements A"],"ans":"C","exp":"Cú pháp kế thừa trong C++ là tên lớp con, dấu hai chấm, phạm vi rồi tên lớp cha. Từ khóa extends là của Java, implements dùng cho interface, còn extern thì không liên quan gì tới kế thừa.","topic":"2.1. Khai báo lớp kế thừa / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-67","n":67,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Coordinate {\npublic:\n    int n;\n};\nclass Cord {\npublic:\n    Coordinate c;\n};\nvoid main() {\n    Cord x;\n    x.c.n = 10;\n    cout << x.c.n;\n}","lang":"cpp","opts":["0","6","10","Lỗi biên dịch tại x.c.n = 10; do biến n và đối tượng c có thuộc tính public nên không được truy cập từ ngoài lớp"],"ans":"C","exp":"Đây không phải kế thừa mà là quan hệ chứa: lớp Cord có một thuộc tính kiểu Coordinate. Cả c lẫn n đều public nên viết x.c.n là hợp lệ, kết quả in ra 10.","topic":"","note":""},{"id":"3-68","n":68,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class ADouble {\n    double value;\npublic:\n    ADouble(double v) {\n        value = v;\n    }\n    void multiply(ADouble d) {\n        value = value * d.value;\n    }\n    void squared() {\n        multiply(*this);\n    }\n    double getValue() const {\n        return value;\n    }\n};\nvoid main() {\n    ADouble x(5.0);\n    x.squared();\n    cout << x.getValue() << '\\n';\n}","lang":"cpp","opts":["5","25","0","Lỗi biên dịch do lớp ADouble không có hàm khởi tạo hai tham số"],"ans":"B","exp":"Hàm squared gọi multiply(*this), tức là nhân đối tượng với chính nó. Con trỏ this trỏ tới đối tượng hiện tại, dấu sao lấy ra đối tượng đó. Vậy 5 nhân 5 bằng 25.","topic":"","note":""},{"id":"3-69","n":69,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class AInteger {\n    int value;\npublic:\n    AInteger() {\n        value = 0;\n    }\n    AInteger(int i) {\n        value = i;\n    }\n    AInteger(const AInteger &ai) {\n        value = ai.value;\n        cout << \"Copy...\";\n    }\n    AInteger &operator = (const AInteger &ai) {\n        value = ai.value;\n        cout << \" = \";\n        return *this;\n    }\n};\nvoid nothing(AInteger a, AInteger b, AInteger c) {\n}\nvoid main() {\n    AInteger i(5);\n    AInteger j;\n    AInteger k = i;\n    j = i;\n    cout << \"nothing...\";\n    nothing(i, j, k);\n}","lang":"cpp","opts":["Copy... = nothing...Copy...Copy...Copy...","Copy...nothing...","Copy...Copy...","nothing... = ...Copy..."],"ans":"A","exp":"AInteger k = i dùng constructor sao chép nên in Copy... Dòng j = i dùng toán tử gán nên in dấu bằng. Sau đó in nothing... rồi gọi hàm nothing với ba tham số truyền theo giá trị, mỗi tham số tạo một bản sao nên in thêm ba lần Copy...","topic":"4.1. Phương thức khởi tạo (Constructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"3-70","n":70,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Base {\n    int na;\npublic:\n    Base(int a = 0) {\n        na = a;\n    }\n    ~Base(){\n        cout << \" \" << na;\n    }\n};\nvoid Func(Base aaa){\n    Base *a1 = new Base(3);\n    delete a1;\n}\nvoid run(){\n    Base aaa(4);\n    Func(aaa);\n}\nvoid main() {\n    run();\n}","lang":"cpp","opts":["3 3 4","0 3 4","3 4","3 4 4"],"ans":"D","exp":"Func nhận tham số theo giá trị nên khi gọi có một bản sao được tạo. Trong Func, delete a1 in ra 3. Kết thúc Func, bản sao bị hủy và in 4. Kết thúc run, đối tượng gốc bị hủy và in tiếp 4. Kết quả là 3 4 4.","topic":"4.2. Phương thức hủy (Destructor) / 4. PHƯƠNG THỨC KHỞI TẠO VÀ HỦY","note":""},{"id":"3-71","n":71,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Base{\npublic:\n    Base(){\n        cout << \"Base class...\";\n    }\n};\nclass Derive :public Base{\npublic:\n    Derive(){\n        cout << \"Derive class...\";\n    }\n};\nvoid main(){\n    Derive d;\n}","lang":"cpp","opts":["Base class...","Base class...Derive class...","Derive class...Base class...","Derive class..."],"ans":"B","exp":"Khi tạo đối tượng lớp con, constructor của lớp cha luôn chạy trước. Vì vậy in Base class... rồi mới tới Derive class...","topic":"2.4. Phương thức khởi tạo và phương thức hủy trong lớp dẫn xuất / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-72","n":72,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Base{\npublic:\n    Base(){\n    }\n    ~Base(){\n        cout << \"Base class ...\";\n    }\n};\nclass Derive :Base\n{\npublic:\n    Derive(){\n    }\n    ~Derive(){\n        cout << \"Derive class...\";\n    }\n};\nvoid run(){\n    Derive d;\n}\nvoid main(){\n    run();\n}","lang":"cpp","opts":["Derive class...Base class ...","Base class ...Derive class...","Base class ...","Derive class..."],"ans":"A","exp":"Destructor chạy ngược với constructor: lớp con hủy trước, lớp cha hủy sau. Vì vậy in Derive class... rồi tới Base class...","topic":"2.4. Phương thức khởi tạo và phương thức hủy trong lớp dẫn xuất / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-73","n":73,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Base\n{\npublic:\n    int xVal;\n    Base(int x = 0) : xVal(x)\n    {\n        cout << xVal <<\"...\";\n    }\n};\nclass Derive :public Base\n{\npublic:\n    Derive()\n    {\n        xVal = 10;\n    }\n    void Print()\n    {\n        cout << xVal <<\"...\";\n    }\n};\nvoid main()\n{\n    Derive d;\n    d.Print();\n}","lang":"cpp","opts":["0...10...","10...0...","10...","0..."],"ans":"A","exp":"Constructor của Derive không ghi gọi cha nên Base(0) chạy trước và in 0... Sau đó xVal bị gán lại thành 10 và Print in 10...","topic":"2.4. Phương thức khởi tạo và phương thức hủy trong lớp dẫn xuất / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-74","n":74,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Base{\nprotected:\n    int xVal;\npublic:\n    Base(){\n        xVal = 5;\n    }\n    void Print(){\n        cout << xVal ;\n    }\n};\nclass Derive :public Base\n{\npublic:\n    Derive(int x) {\n        xVal = x;\n    }\n};\nvoid main(){\n    Derive d(10);\n    d.Print();\n}","lang":"cpp","opts":["5","10","Lỗi biên dịch tại d.Print() do hàm Print có thuộc tính public","Không xuất gì ra màn hình."],"ans":"B","exp":"Derive kế thừa public nên Print vẫn là public và main gọi được. Constructor của Derive gán xVal bằng 10 sau khi Base đã gán 5, giá trị cuối cùng là 10.","topic":"2.4. Phương thức khởi tạo và phương thức hủy trong lớp dẫn xuất / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-75","n":75,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Base\n{\nprotected:\n    int xVal;\npublic:\n    Base()\n    {\n        xVal = 5;\n    }\n    void Print()\n    {\n        cout << xVal ;\n    }\n};\nclass Derive :protected  Base\n{\npublic:\n    Derive(int x)\n    {\n        xVal = x;\n    }\n};\nvoid main()\n{\n    Derive d(10);\n    d.Print();\n}","lang":"cpp","opts":["10","5","Lỗi biên dịch tại d.Print() do hàm lớp Derive kế thừa protected lớp Base nên hàm Print có thuộc tính private","Không xuất gì ra màn hình."],"ans":"C","exp":"Chỉ khác câu trước ở chữ protected trong dòng kế thừa. Vì kế thừa protected nên Print bị hạ phạm vi và main không gọi được nữa, chương trình lỗi biên dịch.","topic":"2.3. Sử dụng các thuộc tính và phương thức trong lớp cơ sở / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-76","n":76,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class A\n{\npublic:\n   A()  {\n    cout << \"A's constructor called...\" ;\n   }\n};\nclass B\n{\npublic:\n   B()  {\n    cout << \"B's constructor called...\";\n   }\n};\nclass C : public B, public A\n{\npublic:\n   C()  {\n    cout << \"C's constructor called...\";\n   }\n};\nint main(){\n    A a;\n    return 0;\n}","lang":"cpp","opts":["B's constructor called...A's constructor called...C's constructor called...","A's constructor called...","C's constructor called...B's constructor called...C's constructor called...","A's constructor called...B's constructor called..."],"ans":"B","exp":"Chương trình chỉ tạo một đối tượng của lớp A, không hề tạo đối tượng lớp C. Vì vậy chỉ constructor của A chạy và in một dòng duy nhất.","topic":"","note":""},{"id":"3-77","n":77,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class A {\npublic:\n    A() {\n        cout << \"Constructing A...\";\n    }\n    ~A(){\n        cout << \"Destructing A...\";\n    }\n};\nclass B {\npublic:\n    B(){\n        cout << \"Constructing B...\";\n    }\n    ~B(){\n        cout << \"Destructing B...\";\n    }\n};\nclass C : public A, public B {\npublic:\n    C(){\n        cout << \"Constructing C...\";\n    }\n    ~C(){\n        cout << \"Destructing C...\";\n    }\n};\nvoid main(){\n    C ob;\n}","lang":"cpp","opts":["Constructing A...Constructing B...Constructing C...Destructing C...Destructing B...Destructing A...","Constructing A...Constructing B...Constructing C...","Constructing C...Destructing C...","Constructing A...Constructing B...Constructing C...Destructing C..."],"ans":"A","exp":"Constructor chạy theo thứ tự khai báo kế thừa từ trái sang phải rồi mới tới lớp con: A, B, C. Destructor chạy ngược lại: C, B, A.","topic":"3.3. Phương thức khởi tạo và phương thức hủy trong lớp đa kế thừa / 3. ĐA KẾ THỪA","note":""},{"id":"3-78","n":78,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"1\n2 class A{\n3 public:\n4   int x;\n5   int y;\n6   int z;\n7   void print();\n8\n9\n10 };\n11 void A::print(){\n12   cout << x;\n13   cout << y;\n14   cout << z;\n15 }\n16 class B : public A{\n17 public:\n18   void print();\n19 };\n20 void B::print(){\n21   cout << x;\n22   cout << y;\n23   cout << z;\n24 }\n25 int main() {\n26   A ma;\n27   cout << ma.x << endl;\n28   cout << ma.y << endl;\n29   cout << ma.z << endl;\n30   return 0;\n31 }","lang":"cpp","opts":["Chương trình sẽ bị lỗi biên dịch tại dòng lệnh 21,27,28","Chương trình sẽ bị lỗi biên dịch tại dòng lệnh 13,29","Chương trình không bị lỗi biên dịch","Chương trình sẽ bị lỗi biên dịch tại dòng lệnh 21,22,23"],"ans":"C","exp":"Cả ba biến x, y, z đều public nên lớp con đọc được và main cũng đọc được. Chương trình không có lỗi biên dịch nào.","topic":"2.2. Phạm vi truy cập / 2. ĐƠN KẾ THỪA","note":""},{"id":"3-79","n":79,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"template <class T>\nclass Test {\n    T x, y;\npublic:\n    Test(T a = 0, T b = 0) {\n        x = b;\n        y = a;\n    }\n    void display();\n};\ntemplate <class T>\nvoid Test<T>::display() {\n    cout << \"(\" << x << \",\" << y << \") \";\n}\nvoid main() {\n    Test<int> ti(3, 5);\n    ti.display();\n    Test<char> tc('a', 'b');\n    tc.display();\n}","lang":"cpp","opts":["(5,3) (b,a)","(3,5) (a,b)","(5,3)","(b,a)"],"ans":"A","exp":"Chú ý constructor gán x bằng b và y bằng a, tức là đảo thứ tự. Test<int> ti(3,5) cho x bằng 5, y bằng 3 nên in (5,3). Test<char> tc('a','b') cho x là b, y là a nên in (b,a).","topic":"8.2. Cú pháp / 8. KHUÔN MẪU HÀM","note":""},{"id":"3-80","n":80,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Shape {\npublic:\n    void setWidth(int w) {\n        width = w;\n    }\n    void setHeight(int h) {\n        height = h;\n    }\nprotected:\n    int width;\n    int height;\n};\nclass Rectangle : public Shape {\npublic:\n    int getArea() {\n        return (width * height);\n    }\n};\nint main(void) {\n    Rectangle rect;\n    rect.setWidth(5);\n    rect.setHeight(7);\n    cout << \"Total area: \" << rect.getArea() << endl;\n    return 0;\n}","lang":"cpp","opts":["Total area: 7","Total area: 5","Total area: 35","Total area: 25"],"ans":"C","exp":"width và height là protected nên Rectangle dùng được trong getArea. 5 nhân 7 bằng 35 nên màn hình in Total area: 35.","topic":"2.3. Sử dụng các thuộc tính và phương thức trong lớp cơ sở / 2. ĐƠN KẾ THỪA","note":""}]},{"n":4,"title":"Đa hình và trừu tượng","lang":"C++","qs":[{"id":"4-1","n":1,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Shape {\npublic:\n    virtual void draw() {\n        cout << \"Drawing a shape\" << endl;\n    }\n};\nclass Circle : public Shape {\npublic:\n    void draw() override {\n        cout << \"Drawing a circle \";\n    }\n};\nclass Square : public Shape {\npublic:\n    void draw() override {\n        cout << \"Drawing a square \";\n    }\n};\nint main() {\n    Shape* shape1 = new Circle();\n    Shape* shape2 = new Square();\n    shape1->draw();\n    shape2->draw();\n    delete shape1;\n    delete shape2;\n    return 0;\n}","lang":"cpp","opts":["Drawing a circle","Drawing a square","Drawing a circle Drawing a square","Drawing a square Drawing a circle"],"ans":"C","exp":"Hàm draw ở lớp cha khai báo virtual nên khi gọi qua con trỏ lớp cha, máy nhìn vào đối tượng thật để chọn hàm. shape1 thật ra là Circle nên in Drawing a circle, shape2 là Square nên in Drawing a square. Đây là đa hình động.","topic":"1.2. Phương thức ảo (Virtual Method / Virtual Function) / 1. ĐA HÌNH","note":""},{"id":"4-2","n":2,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Polygon {\nprotected:\n    int width, height;\npublic:\n    Polygon(int a);\n    void  setValues(int a, int b);\n};\nPolygon::Polygon(int a){\n    width = a;\n}\nvoid Polygon::setValues(int a, int b){\n    width = a;\n    height = b;\n}\nclass Rectangle : public Polygon {\npublic:\n    Rectangle(int w, int h);\n    int area();\n};\nRectangle::Rectangle(int w, int h) :Polygon(h){\n    height = h;\n}\nint Rectangle::area(){\n    return (width * height);\n}\nint main() {\n    Rectangle rect(8, 9);\n    cout << rect.area() << endl;\n    return 0;\n}","lang":"cpp","opts":["17","81","8","72"],"ans":"B","exp":"Constructor của Rectangle viết Polygon(h) chứ không phải Polygon(w), nên width nhận giá trị 9 chứ không phải 8. Sau đó height cũng bằng 9, diện tích thành 9 nhân 9 bằng 81. Chỉ đổi một chữ cái mà kết quả khác hẳn câu 65 chương 3.","topic":"","note":""},{"id":"4-3","n":3,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, lớp Polygon có đặc điểm gì?","code":"class Polygon {\nprotected:\n    int width, height;\npublic:\n    void setValues(int a, int b);\n    virtual int area()=0;\n};\nvoid Polygon::setValues(int a, int b){\n    width = a;\n    height = b;\n}\nclass Rectangle : public Polygon {\npublic:\n    int area();\n};\nint Rectangle::area(){\n    return (width * height);\n}\nclass Triangle : public Polygon {\npublic:\n    int area();\n};\nint Triangle::area(){\n    return (width * height / 2);\n}\nint main() {\n    Rectangle rect;\n    Triangle trgl;\n    rect.setValues(4, 5);\n    trgl.setValues(4, 5);\n    cout << \"Rectangle area:\" << rect.area() << \" Triangle area:\" << trgl.area() << endl;\n    return 0;\n}","lang":"cpp","opts":["Lớp trừu tượng (abstract classes)","Lớp đa kế thừa","Lớp mẫu (Template Classes)","Các đáp án đều sai"],"ans":"A","exp":"Polygon có hàm virtual int area() = 0, tức hàm thuần ảo. Lớp nào chứa ít nhất một hàm thuần ảo thì gọi là lớp trừu tượng và không tạo đối tượng trực tiếp được, chỉ dùng làm lớp cha.","topic":"2.3. Lớp trừu tượng / 2. TRỪU TƯỢNG","note":""},{"id":"4-4","n":4,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class A{\npublic:\n    void x(){\n        cout << \"I am ax...\";\n    }\n};\nclass B : public A{\npublic:\n    void x(){\n        cout << \"I am bx...\";\n    }\n    void y(){\n        cout << \"I am by...\";\n    }\n};\nvoid show(A *a) {\n    a->x();\n}\nvoid main() {\n    A *a = new A();\n    show(a);\n    B *b = new B();\n    show(b);\n}","lang":"cpp","opts":["I am ax...I am ax...","I am ax...I am bx...","I am bx...I am bx...","I am bx...I am ax..."],"ans":"A","exp":"Hàm x không khai báo virtual nên máy chọn hàm theo kiểu con trỏ chứ không theo đối tượng thật. Tham số của show có kiểu A* nên cả hai lần gọi đều chạy hàm x của lớp A.","topic":"1.2. Phương thức ảo (Virtual Method / Virtual Function) / 1. ĐA HÌNH","note":""},{"id":"4-5","n":5,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class A{\npublic:\n    void x(){\n        cout << \"I am ax...\";\n    }\n};\nclass B : public A{\npublic:\n    void x(){\n        cout << \"I am bx...\";\n    }\n    void y(){\n        cout << \"I am by...\";\n    }\n};\nvoid show(A *a){\n    a->x();\n}\nvoid main(){\n    A *a = new A();\n    show(a);\n    B *b = new B();\n    show(b);\n}","lang":"cpp","opts":["I am ax...I am ax...","I am ax...I am bx...","I am bx...I am bx...","I am bx...I am ax..."],"ans":"A","exp":"Câu này giống hệt câu trước. Thiếu từ khóa virtual thì không có đa hình, hàm được chọn theo kiểu con trỏ A* nên in hai lần I am ax...","topic":"1.2. Phương thức ảo (Virtual Method / Virtual Function) / 1. ĐA HÌNH","note":""},{"id":"4-6","n":6,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class A{\npublic:\n    virtual void x(){\n        cout << \"I am Ax...\";\n    }\n    void m(){\n        cout << \"I am Am...\";\n        x();\n    }\n};\nclass B : public A{\npublic:\n    void x(){\n        cout << \"I am Bx...\";\n    }\n    void y(){\n        cout << \"I am By...\";\n        m();\n    }\n};\nvoid main()\n{\n    B *b = new B();\n    b->y();\n}","lang":"cpp","opts":["I am By...I am Am...I am Bx...","I am By...I am Ax...I am Bx...","I am By...I am Bx...","I am By...I am Bm..."],"ans":"A","exp":"b->y() in I am By... rồi gọi m của lớp cha nên in I am Am... Bên trong m có lời gọi x, mà x đã khai báo virtual nên máy nhìn đối tượng thật là B và chạy hàm x của B, in I am Bx...","topic":"1.2. Phương thức ảo (Virtual Method / Virtual Function) / 1. ĐA HÌNH","note":""},{"id":"4-7","n":7,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class A{\npublic:\n    void x(){\n        cout << \"I am Ax...\";\n    }\n    void m(){\n        cout << \"I am Am...\";\n        x();\n    }\n};\nclass B : public A{\npublic:\n    void x(){\n        cout << \"I am Bx...\";\n    }\n    void y(){\n        cout << \"I am By...\";\n        m();\n    }\n};\nvoid main()\n{\n    B *b = new B();\n    b->y();\n}","lang":"cpp","opts":["I am By...I am Am...I am Bx...","I am By...I am Am...I am Ax...","I am By...I am Bx...","I am By...I am Bm..."],"ans":"B","exp":"Giống câu trước nhưng x không còn virtual. Vì vậy lời gọi x bên trong hàm m chạy đúng bản của lớp A, in I am Ax... Đây là điểm khác biệt duy nhất giữa hai câu.","topic":"1.2. Phương thức ảo (Virtual Method / Virtual Function) / 1. ĐA HÌNH","note":""},{"id":"4-8","n":8,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Vehicle {\npublic:\n    double speed;\n    double mass;\n    double kineticEnergy() {\n        return 0.5 * mass * speed * speed;\n    }\n};\nclass Plane : public Vehicle {\npublic:\n    double altitude;\n    double totalEnergy() {\n        return kineticEnergy() + mass * altitude;\n    }\n};\nbool nonNullEnergy(Vehicle v) {\n    return v.kineticEnergy() != 0.0;\n}\nint main(int argc, char **argv) {\n    Plane p;\n    p.speed = 150.0;\n    p.mass = 1500.0;\n    p.altitude = 1300;\n    if (nonNullEnergy(p))\n        cout << \"There is some energy.\\n\";\n    else\n        cout << \"There is not energy.\\n\";\n}","lang":"cpp","opts":["There is some energy","There is not energy","Lỗi biên dịch do khai báo kế thừa sai","Lỗi thực thi tại p.speed = 150.0; do đối tượn p chưa được cấp phát vùng nhớ"],"ans":"A","exp":"Plane kế thừa public từ Vehicle nên có đủ speed, mass và hàm kineticEnergy. Hàm nonNullEnergy nhận tham số kiểu Vehicle, đối tượng Plane được cắt bớt phần riêng nhưng vẫn giữ speed và mass. Động năng khác 0 nên in There is some energy.","topic":"2.3. Sử dụng các thuộc tính và phương thức trong lớp cơ sở / 2. ĐƠN KẾ THỪA","note":""},{"id":"4-9","n":9,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class A {\npublic:\n    void dummy() {\n        cout << \"A::dummy...\";\n    }\n};\nclass B : public A {\npublic:\n    void dummy() {\n        cout << \"B::dummy...\";\n    }\n};\nvoid callAsA(A x) {\n    x.dummy();\n}\nint main(int argc, char **argv) {\n    B b;\n    b.dummy();\n    callAsA(b);\n}","lang":"cpp","opts":["A::dummy...B::dummy...","B::dummy...A::dummy...","A::dummy","B::dummy"],"ans":"B","exp":"b.dummy() gọi bản của lớp B vì b có kiểu B. Còn callAsA nhận tham số kiểu A theo giá trị, đối tượng bị cắt về phần A và dummy không phải virtual nên chạy bản của A.","topic":"2.5. Ghi đè phương thức (Overriding) / 2. ĐƠN KẾ THỪA","note":""},{"id":"4-10","n":10,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class FirstClass {\npublic:\n    void something() {\n        cout << \"FirstClass::something()...\";\n    }\n};\nclass SecondClass : public FirstClass {\npublic:\n    void something() {\n        cout << \"SecondClass::something()...\";\n    }\n};\nvoid niceFunction(FirstClass y) {\n    y.something();\n}\nint main(int argc, char **argv) {\n    SecondClass x;\n    x.something();\n    niceFunction(x);\n}","lang":"cpp","opts":["SecondClass::something()...FirstClass::something()...","FirstClass::something()...SecondClass::something()...","SecondClass::something()...","FirstClass::something()..."],"ans":"A","exp":"x.something() chạy bản của SecondClass vì x có kiểu SecondClass. niceFunction nhận tham số kiểu FirstClass theo giá trị nên đối tượng bị cắt và chạy bản của FirstClass.","topic":"2.5. Ghi đè phương thức (Overriding) / 2. ĐƠN KẾ THỪA","note":""},{"id":"4-11","n":11,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class AA {\npublic:\n    virtual void something() {\n        cout << \"AA:something()...\";\n    }\n};\nclass BB : public AA {\npublic:\n    void something() {\n        cout << \"BB:something()...\";\n    }\n};\nvoid byvalue(AA x) {\n    x.something();\n}\nvoid byref(AA &x) {\n    x.something();\n}\nvoid bypointer(AA *x) {\n    x->something();\n}\nint main(int argc, char **argv) {\n    BB b;\n    byvalue(b);\n    byref(b);\n    bypointer(&b);\n}","lang":"cpp","opts":["AA:something()...BB:something()...BB:something()...","AA:something()...BB:something()...","AA:something()...","BB:something()..."],"ans":"A","exp":"Hàm là virtual nhưng truyền theo giá trị thì đối tượng bị cắt về kiểu AA, nên byvalue in AA:something... Truyền theo tham chiếu và theo con trỏ thì giữ nguyên đối tượng thật nên cả hai đều in BB:something... Nhớ rằng đa hình chỉ hoạt động qua con trỏ hoặc tham chiếu.","topic":"2.5. Ghi đè phương thức (Overriding) / 2. ĐƠN KẾ THỪA","note":""},{"id":"4-12","n":12,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Function {\npublic:\n    virtual double eval(double x) = 0;\n    double cal(double x, double y) {\n        return (eval(x + y));\n    }\n};\nclass Oscillating : public Function {\n    double a, b, c;\npublic:\n    Oscillating(double aa, double bb, double cc) : a(aa), b(bb), c(cc) {\n    }\n    double eval(double x) {\n        return x+a+b+c;\n    }\n};\nint main(int argc, char *argv) {\n    Oscillating f(1, 2, 3);\n    cout << f.cal(2, 3);\n}","lang":"cpp","opts":["2","10","11","5"],"ans":"C","exp":"Hàm cal của lớp cha gọi eval, mà eval là hàm thuần ảo nên chạy bản của lớp con. cal(2,3) tính eval(5), bản của Oscillating trả về 5 cộng 1 cộng 2 cộng 3 bằng 11.","topic":"2.3. Lớp trừu tượng / 2. TRỪU TƯỢNG","note":""},{"id":"4-13","n":13,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"template <class T>\nclass Calc{\npublic:\n    T multiply(T x, T y);\n    T add(T x, T y);\n};\ntemplate <class T>\nT Calc<T>::multiply(T x, T y){\n    return x*y;\n}\ntemplate <class T>\nT Calc<T>::add(T x, T y){\n    return x + y;\n}\nint main () {\n    Calc<int> v;\n    Calc<float> u;\n    cout << v.add(5, 6)<<\"...\"<<u.multiply(2.0, 5.0);\n}","lang":"cpp","opts":["5...6","11...10","10...11","Lỗi biên dịch do khai báo lớp mẫu sai"],"ans":"B","exp":"Calc<int> làm việc với số nguyên, v.add(5,6) ra 11. Calc<float> làm việc với số thực, u.multiply(2.0, 5.0) ra 10. Khuôn mẫu lớp giúp viết một lần dùng cho nhiều kiểu dữ liệu.","topic":"8.2. Cú pháp / 8. KHUÔN MẪU HÀM","note":""},{"id":"4-14","n":14,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class A{\npublic:\n    A()  {\n        cout << \"A's constructor...\";\n    }\n};\nclass B{\npublic:\n    B()  {\n        cout << \"B's constructor...\";\n    }\n};\nclass C : public B, public A {\npublic:\n    C()  {\n        cout << \"C's constructor...\";\n    }\n};\nint main(){\n    C c;\n    return 0;\n}","lang":"cpp","opts":["B's constructor...A's constructor...C's constructor...","B's constructor...","A's constructor...B's constructor...C's constructor...","A's constructor...B's constructor..."],"ans":"A","exp":"Trong đa kế thừa, constructor của các lớp cha chạy theo đúng thứ tự ghi trong dòng kế thừa. Ở đây ghi public B trước rồi mới public A nên B chạy trước, sau đó A, cuối cùng là C.","topic":"","note":""},{"id":"4-15","n":15,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class USBDevice\n{\nprivate:\n    long id;\npublic:\n    USBDevice(long pid) : id(pid){\n    }\n    long getID() {\n        return id;\n    }\n};\nclass NetworkDevice {\nprivate:\n    long id;\npublic:\n    NetworkDevice(long pid) : id(pid){\n    }\n    long getID() {\n        return id;\n    }\n};\nclass WirelessAdaptor : public USBDevice, public NetworkDevice{\npublic:\n    WirelessAdaptor(long uid, long nid) : USBDevice(uid), NetworkDevice(nid)\n    {\n    }\n};\nint main(){\n    WirelessAdaptor w(123, 456);\n    cout << w.getID();\n    return 0;\n}","lang":"cpp","opts":["123","456.","123...456","Lỗi biên dịch tại cout << w.getID();"],"ans":"D","exp":"WirelessAdaptor thừa hưởng hai hàm getID giống hệt nhau từ hai lớp cha khác nhau. Trình biên dịch không biết chọn bản nào nên báo lỗi nhập nhằng. Muốn chạy thì phải ghi rõ w.USBDevice::getID().","topic":"3.3. Phương thức khởi tạo và phương thức hủy trong lớp đa kế thừa / 3. ĐA KẾ THỪA","note":""},{"id":"4-16","n":16,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Human {\nprivate:\n   string nameC;\npublic:\n   Human(const string & name) : nameC(name) { }\n   string name() const { return nameC; }\n   void talkTo(const Human & person) const {\n      cout << nameC << \" Hello, \" << person.name() << \"!\" << \"...\";\n   }\n};\nint main() {\n   Human ha(\"Nguyen Ha\");\n   Human tuan(\"Nguyen Anh Tuan\");\n   ha.talkTo(tuan);\n   tuan.talkTo(ha);\n   return 0;\n}","lang":"cpp","opts":["Nguyen Ha Hello, Nguyen Anh Tuan!...Nguyen Anh Tuan Hello, Nguyen Ha!...","Nguyen Ha Hello, Nguyen Anh Tuan!...","Nguyen Anh Tuan Hello, Nguyen Ha!...Nguyen Ha Hello, Nguyen Anh Tuan!...","Nguyen Anh Tuan Hello, Nguyen Ha!..."],"ans":"A","exp":"ha.talkTo(tuan) in tên của ha rồi lời chào kèm tên của tuan. Sau đó tuan.talkTo(ha) in ngược lại. Điểm cần nhớ là nameC là tên của đối tượng đang gọi hàm, còn person.name() là tên của đối tượng truyền vào.","topic":"3.3. Con trỏ this / 3. TRUY XUẤT CÁC THÀNH PHẦN CỦA LỚP","note":""},{"id":"4-17","n":17,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Animal{\npublic:\n    Animal(){\n        cout << \"Animal constructor...\";\n    }\n    void walk(){\n        cout << \"Animal walks...\";\n    }\n};\nclass Tiger : public Animal{\npublic:\n    Tiger(){\n        cout << \"Tiger constructor ...\";\n    }\n};\nclass Lion : public Animal{\npublic:\n    Lion(){\n        cout << \"Lion constructor...\" ;\n    }\n};\nclass Liger : public Tiger, public Lion{\npublic:\n    Liger(){\n        cout << \"Liger constructor...\" ;\n    }\n};\nint main()\n{\n    Liger anil;\n    anil.Animal::walk();\n    return 0;\n}","lang":"cpp","opts":["Animal constructor...Tiger constructor...Animal constructor...Lion constructor...Liger constructor...Animal walks...","Animal constructor...Tiger constructor...Animal constructor...","Animal constructor...Lion constructor...Liger constructor...Animal walks...","Tiger constructor...Animal constructor...Lion constructor...Liger constructor..."],"ans":"A","exp":"Đây là kế thừa kim cương không dùng virtual nên Liger chứa hai bản Animal riêng biệt. Vì vậy constructor Animal chạy hai lần, một lần cho nhánh Tiger và một lần cho nhánh Lion, rồi mới tới Liger. Cuối cùng gọi walk in Animal walks...","topic":"3.2. Kế thừa ảo (Virtual inheritance) / 3. ĐA KẾ THỪA ẢO","note":""},{"id":"4-18","n":18,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Animal{\npublic:\n    Animal(){\n        cout << \"Animal constructor...\";\n    }\n    void walk(){\n        cout << \"Animal walks...\";\n    }\n};\nclass Tiger : virtual public Animal{\npublic:\n    Tiger(){\n        cout << \"Tiger constructor ...\";\n    }\n};\nclass Lion : virtual public Animal{\npublic:\n    Lion(){\n        cout << \"Lion constructor...\" ;\n    }\n};\nclass Liger : public Tiger, public Lion{\npublic:\n    Liger(){\n        cout << \"Liger constructor...\" ;\n    }\n};\nint main()\n{\n    Liger anil;\n    anil.walk();\n    return 0;\n}","lang":"cpp","opts":["Animal constructor...Tiger constructor...Lion constructor...Liger constructor...Animal walks...","Animal constructor...Tiger constructor...Animal constructor...","Animal constructor...Lion constructor...Liger constructor...Animal walks...","Tiger constructor...Animal constructor...Lion constructor...Liger constructor..."],"ans":"A","exp":"Thêm từ khóa virtual vào hai dòng kế thừa nên chỉ còn một bản Animal duy nhất được chia sẻ. Constructor Animal chỉ chạy một lần, sau đó Tiger, Lion, Liger. Gọi walk cũng không còn nhập nhằng nên viết anil.walk() là đủ.","topic":"3.2. Kế thừa ảo (Virtual inheritance) / 3. ĐA KẾ THỪA ẢO","note":""},{"id":"4-19","n":19,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Person {\npublic:\n    Person(int x)  {\n        cout << \"Person::Person(int)...\" ;\n    }\n};\nclass Faculty : public Person {\npublic:\n    Faculty(int x) :Person(x)   {\n        cout << \"Faculty::Faculty(int)...\" ;\n    }\n};\nclass Student : public Person {\npublic:\n    Student(int x) :Person(x) {\n        cout << \"Student::Student(int)...\" ;\n    }\n};\nclass TA : public Faculty, public Student  {\npublic:\n    TA(int x) :Student(x), Faculty(x)   {\n        cout << \"TA::TA(int)...\" ;\n    }\n};\nint main()  {\n    TA t(30);\n}","lang":"cpp","opts":["Person::Person(int)...Faculty::Faculty(int)...Person::Person(int)...Student::Student(int)...TA::TA(int )...","Faculty::Faculty(int)...Person::Person(int)...Student::Student(int)...TA::TA(int )...","Person::Person(int)...Faculty::Faculty(int)...Student::Student(int)...TA::TA(int )...","Person::Person(int)...Faculty::Faculty(int)...Person::Person(int)...Student::Student(int)..."],"ans":"A","exp":"Không có kế thừa ảo nên TA chứa hai bản Person. Thứ tự chạy theo dòng khai báo kế thừa là Faculty rồi Student, mỗi nhánh kéo theo một lần Person. Kết quả là Person, Faculty, Person, Student, TA.","topic":"3.2. Kế thừa ảo (Virtual inheritance) / 3. ĐA KẾ THỪA ẢO","note":""},{"id":"4-20","n":20,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Person {\npublic:\n   Person(int x)  {\n      cout << \"Person::Person(int)...\" ;\n   }\n};\nclass Faculty : virtual public Person {\npublic:\n   Faculty(int x) :Person(x)   {\n      cout << \"Faculty::Faculty(int)...\" ;\n   }\n};\nclass Student : virtual public Person {\npublic:\n   Student(int x) :Person(x) {\n      cout << \"Student::Student(int)...\" ;\n   }\n};\nclass TA : public Faculty, public Student  {\npublic:\n   TA(int x) : Person(x),Student(x), Faculty(x)   {\n      cout << \"TA::TA(int)...\" ;\n   }\n};\nint main()  {\n   TA t(30);\n}","lang":"cpp","opts":["Person::Person(int)...Faculty::Faculty(int)...Student::Student(int)...TA::TA(int )...","Person::Person(int)...Faculty::Faculty(int)...Person::Person(int)...Student::Student(int)...TA::TA(int )...","Person::Person(int)...Faculty::Faculty(int)...Student::Student(int)...","Person::Person(int)...Faculty::Faculty(int)...Person::Person(int)...Student::Student(int)..."],"ans":"A","exp":"Có kế thừa ảo nên chỉ còn một bản Person, và lớp cuối cùng là TA chịu trách nhiệm gọi Person(x). Vì vậy Person chỉ chạy một lần, rồi Faculty, Student, cuối cùng là TA.","topic":"3.2. Kế thừa ảo (Virtual inheritance) / 3. ĐA KẾ THỪA ẢO","note":""},{"id":"4-21","n":21,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Base\n{\npublic:\n   Base()\n   {\n      cout << \"Constructing base...\";\n   }\n   ~Base()\n   {\n      cout << \"Destructing base...\";\n   }\n};\nclass Derived : public Base\n{\npublic:\n   Derived()\n   {\n      cout << \"Constructing derived...\";\n   }\n   ~Derived()\n   {\n      cout << \"Destructing derived...\";\n   }\n};\nvoid main()\n{\n   Derived ob;\n}","lang":"cpp","opts":["Constructing base...Constructing derived...Destructing derived...Destructing base...\"","Constructing base...Constructing derived...","Destructing derived...Destructing base...","Constructing derived...Destructing derived"],"ans":"A","exp":"Tạo đối tượng thì constructor chạy từ cha xuống con, hủy thì ngược lại từ con lên cha. Vì vậy thứ tự là base, derived, rồi hủy derived, hủy base.","topic":"2.4. Phương thức khởi tạo và phương thức hủy trong lớp dẫn xuất / 2. ĐƠN KẾ THỪA","note":""},{"id":"4-22","n":22,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class A {\npublic:\n   A() {\n      cout << \"Constructing A...\";\n   }\n   ~A() {\n      cout << \"Destructing A...\";\n   }\n};\nclass B : public A {\npublic:\n   B() {\n      cout << \"Constructing B...\";\n   }\n   ~B() {\n      cout << \"Destructing B...\";\n   }\n};\nclass C : public B {\npublic:\n   C(){\n      cout << \"Constructing C...\";\n   }\n   ~C(){\n      cout << \"Destructing C...\";\n   }\n};\nvoid main(){\n   C ob;\n}","lang":"cpp","opts":["Constructing A...Constructing B...Constructing C.Destructing C...Destructing B...Destructing A...","Constructing A...Constructing B...Constructing C...","Constructing C...Destructing C...","Constructing A...Destructing A..."],"ans":"A","exp":"Chuỗi kế thừa ba tầng A, B, C. Constructor chạy A trước, rồi B, rồi C. Destructor chạy ngược lại C, B, A.","topic":"2.4. Phương thức khởi tạo và phương thức hủy trong lớp dẫn xuất / 2. ĐƠN KẾ THỪA","note":""},{"id":"4-23","n":23,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Shape\n{\nprotected:\n   double volume;\npublic:\n   virtual void find_vol() = 0;\n};\nclass Cube : public Shape\n{\nprotected:\n   double side;\npublic:\n   Cube();\n   void find_vol();\n};\nclass Sphere : public Shape\n{\nprotected:\n   double radius;\npublic:\n   Sphere();\n   void find_vol();\n};\nCube::Cube()\n{\n   side=3;\n}\nSphere::Sphere()\n{\n   radius=4;\n}\nvoid Cube::find_vol()\n{\n   volume = side*side*side;\n   cout << \"Cube is : \" << volume << \"...\";\n}\nvoid Sphere::find_vol()\n{\n   volume = radius*radius*radius;\n   cout << \"Sphere is : \"<< volume;\n}\nvoid main()\n{\n   Shape *ptr;\n   Cube cube;\n   Sphere sphere;\n   ptr = &cube;\n   ptr->find_vol();\n   ptr = &sphere;\n   ptr->find_vol();\n}","lang":"cpp","opts":["Cube is : 27","Cube is : 27...Sphere is : 64","Cube is : 3...Sphere is : 4","Sphere is : 4"],"ans":"B","exp":"Shape là lớp trừu tượng nên không tạo đối tượng được, nhưng vẫn khai báo con trỏ Shape* để trỏ tới các lớp con. Nhờ hàm ảo, mỗi lần gọi find_vol lại chạy bản đúng của Cube hay Sphere. Cube ra 3 mũ 3 bằng 27, Sphere theo công thức trong bài ra 4 mũ 3 bằng 64.","topic":"2.3. Lớp trừu tượng / 2. TRỪU TƯỢNG","note":""},{"id":"4-24","n":24,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Person {\npublic:\n    Person(const string& name) : name(name) {}\n    void introduce() {\n        cout << \"Name:\" << name;\n    }\nprotected:\n    string name;\n};\nclass Student : virtual public Person {\npublic:\n    Student(const string& name, int studentID) : Person(name), studentID(studentID) {}\n    void study() {\n        cout << \", Studying...\" ;\n    }\nprivate:\n    int studentID;\n};\nclass Worker : virtual public Person {\npublic:\n    Worker(const string& name, const string& job) : Person(name), job(job) {}\n    void work() {\n        cout << \" Working...\" ;\n    }\nprivate:\n    string job;\n};\nclass WorkingStudent : public Student, public Worker {\npublic:\n    WorkingStudent(const string& name, int studentID, const string& job)\n        : Person(name), Student(name, studentID), Worker(name, job) {}\n};\nint main() {\n    WorkingStudent ws(\"John\", 123, \"Engineer\");\n    ws.introduce();\n    ws.study();\n    ws.work();\n    return 0;\n}","lang":"cpp","opts":["Name:John, Engineer... 123...","Name:John, 123... Engineer...","Name:John","Name:John, Studying... Working..."],"ans":"D","exp":"Cả Student lẫn Worker đều kế thừa ảo từ Person nên WorkingStudent chỉ có một bản Person duy nhất. Chương trình in tên, rồi câu Studying..., rồi câu Working... theo đúng thứ tự gọi trong main.","topic":"3.2. Kế thừa ảo (Virtual inheritance) / 3. ĐA KẾ THỪA ẢO","note":""},{"id":"4-25","n":25,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Shape {\npublic:\n    Shape(const string& name) : name(name) {}\n    virtual float area() = 0;\n    void printName() {\n        cout << name ;\n    }\nprivate:\n    string name;\n};\nclass Rectangle : public Shape {\npublic:\n    Rectangle(float width, float height) : Shape(\"Rectangle\"), width(width), height(height) {}\n    float area() override {\n        return width * height;\n    }\nprivate:\n    float width, height;\n};\nclass Triangle : public Shape {\npublic:\n    Triangle(float base, float height) : Shape(\"Triangle\"), base(base), height(height) {}\n    float area() override {\n        return 0.5 * base * height;\n    }\nprivate:\n    float base, height;\n};\nint main() {\n    Rectangle rectangle(5, 3);\n    Triangle triangle(4, 6);\n    Shape* shapes[] = { &rectangle, &triangle };\n    for (int i = 0; i < 2; ++i) {\n        shapes[i]->printName();\n        cout << \" Area: \" << shapes[i]->area()<< \"\\t\";\n    }\n    return 0;\n}","lang":"cpp","opts":["Rectangle Area: 15","Triangle Area: 12","Rectangle Area: 15   Triangle Area: 12","Triangle Area: 12    Rectangle Area: 15"],"ans":"C","exp":"Mảng con trỏ Shape* giữ hai đối tượng khác lớp, nhờ hàm ảo area mà mỗi phần tử tính diện tích theo công thức riêng. Hình chữ nhật ra 5 nhân 3 bằng 15, tam giác ra một nửa của 4 nhân 6 bằng 12.","topic":"3.2. Kế thừa ảo (Virtual inheritance) / 3. ĐA KẾ THỪA ẢO","note":""},{"id":"4-26","n":26,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Vehicle {\npublic:\n    Vehicle(const string& name) : name(name) {}\n    virtual void start() = 0;\n    virtual void stop() = 0;\n    void displayInfo() {\n        cout << name;\n    }\nprivate:\n    string name;\n};\nclass Car : public Vehicle {\npublic:\n    Car() : Vehicle(\"Car\") {}\n    void start() override {\n        cout << \" Starting.\" ;\n    }\n    void stop() override {\n        cout << \" Stopping.\" ;\n    }\n};\nclass Motorcycle : public Vehicle {\npublic:\n    Motorcycle() : Vehicle(\"Motorcycle\") {}\n    void start() override {\n        cout << \" Starting.\";\n    }\n    void stop() override {\n        cout << \" Stopping.\" ;\n    }\n};\nint main() {\n    Car car;\n    Motorcycle motorcycle;\n    Vehicle* vehicles[] = { &car, &motorcycle };\n    for (int i = 0; i < 2; ++i) {\n        vehicles[i]->displayInfo();\n        vehicles[i]->start();\n        cout << \"\\t\";\n    }\n    return 0;\n}","lang":"cpp","opts":["Car Starting.","Motorcycle Starting.","Car Starting.    Motorcycle Starting.","Motorcycle    Car"],"ans":"C","exp":"Vehicle là lớp trừu tượng với hai hàm thuần ảo start và stop. Vòng lặp duyệt mảng con trỏ, mỗi phần tử in tên của mình rồi gọi start, nên ra Car Starting. rồi Motorcycle Starting.","topic":"2.3. Lớp trừu tượng / 2. TRỪU TƯỢNG","note":""},{"id":"4-27","n":27,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Shape {\npublic:\n    virtual void draw() = 0;\n    virtual ~Shape() {}\n};\nclass Circle : public Shape {\npublic:\n    void draw() override {\n        cout << \"Circle\" ;\n    }\n};\nclass Square : public Shape {\npublic:\n    void draw() override {\n        cout << \"Square\" ;\n    }\n};\nint main() {\n    Circle circle;\n    Square square;\n    Shape* shapes[] = { &circle, &square };\n    for (int i = 0; i < 2; ++i) {\n        shapes[i]->draw();\n        cout << \"\\t\";\n    }\n    return 0;\n}","lang":"cpp","opts":["Circle","Square","Square    Circle","Circle      Square"],"ans":"D","exp":"Hàm draw là thuần ảo nên mỗi lớp con phải tự cài đặt. Vòng lặp duyệt mảng theo thứ tự circle rồi square nên in Circle rồi Square. Destructor của lớp cha khai báo virtual là cách viết đúng để hủy đối tượng qua con trỏ lớp cha.","topic":"2.3. Lớp trừu tượng / 2. TRỪU TƯỢNG","note":""},{"id":"4-28","n":28,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"#include <cmath>\nclass Shape {\npublic:\n    virtual float area() = 0;\n    virtual void printInfo() {\n        cout << \"Shape\" << endl;\n    }\n};\nclass Circle : public Shape {\npublic:\n    Circle(float radius) : radius(radius) {}\n    float area() override {\n        return 3.14159 * radius * radius;\n    }\n    void printInfo() override {\n        cout << \"Circle Radius \" << radius ;\n    }\nprivate:\n    float radius;\n};\nclass Square : public Shape {\npublic:\n    Square(float side) : side(side) {}\n    float area() override {\n        return side * side;\n    }\n    void printInfo() override {\n        cout << \"Square Side \" << side ;\n    }\nprivate:\n    float side;\n};\nint main() {\n    Circle circle(5);\n    Square square(4);\n    Shape* shapes[] = { &circle, &square };\n    for (int i = 0; i < 2; ++i) {\n        shapes[i]->printInfo();\n        cout << \", Area: \" << shapes[i]->area() << \"\\t\";\n    }\n    return 0;\n}","lang":"cpp","opts":["Circle Radius 5, Area: 78.5397  Square Side 4, Area: 16","Square Side 4, Area: 16","Circle Radius 5, Area: 78.5397","Circle Radius 5"],"ans":"A","exp":"Mỗi lớp con ghi đè cả printInfo lẫn area. Circle bán kính 5 có diện tích 3.14159 nhân 25 bằng 78.5397, Square cạnh 4 có diện tích 16. Vòng lặp in lần lượt hai dòng thông tin.","topic":"2.3. Lớp trừu tượng / 2. TRỪU TƯỢNG","note":""},{"id":"4-29","n":29,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Animal {\npublic:\n    string name;\n    string species;\n    Animal(const string& name, const string& species)\n        : name(name), species(species) {}\n    virtual string makeSound() const = 0;\n};\nclass Dog : public Animal {\npublic:\n    Dog(const string& name)\n        : Animal(name, \"Dog\") {}\n    string makeSound() const override {\n        return \"Woof!\";\n    }\n};\nclass Cat : public Animal {\npublic:\n    Cat(const string& name)\n        : Animal(name, \"Cat\") {}\n    string makeSound() const override {\n        return \"Meow!\";\n    }\n};\nint main() {\n    Dog dogInstance(\"Buddy\");\n    Cat catInstance(\"Whiskers\");\n    cout << dogInstance.name << \" says \" << dogInstance.makeSound()<<\"\\t\";\n    cout << catInstance.name << \" says \" << catInstance.makeSound();\n    return 0;\n}","lang":"cpp","opts":["Buddy says Woof!    Whiskers says Meow!","Whiskers says Meow!    Buddy says Woof!","Whiskers says Meow!","Buddy says Woof!"],"ans":"A","exp":"Animal là lớp trừu tượng vì có hàm thuần ảo makeSound. Hai đối tượng Dog và Cat tự cài đặt hàm này nên trả về Woof! và Meow!. main in tên rồi tiếng kêu của từng con.","topic":"2.3. Lớp trừu tượng / 2. TRỪU TƯỢNG","note":""},{"id":"4-30","n":30,"stem":"Cho chương trình viết bằng ngôn ngữ C++ như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Animal {\npublic:\n    Animal(const string& name, const string& species) : name(name), species(species) {}\n    virtual void makeSound() const = 0;\n    void getInfo() const {\n        cout << name << \" is a \" << species << endl;\n    }\nprotected:\n    string name;\n    string species;\n};\nclass Dog : public Animal {\npublic:\n    Dog(const string& name) : Animal(name, \"Dog\") {}\n    void makeSound() const override {\n        cout << \"Woof!\" << \"\\t\";\n    }\n};\nclass Cat : public Animal {\npublic:\n    Cat(const string& name) : Animal(name, \"Cat\") {}\n    void makeSound() const override {\n        cout << \"Meow!\";\n    }\n};\nint main() {\n    Dog dog(\"Buddy\");\n    Cat cat(\"Whiskers\");\n    dog.makeSound();\n    cat.makeSound();\n    return 0;\n}","lang":"cpp","opts":["Woof!","Meow!","Woof!   Meow!","Buddy   Whiskers"],"ans":"C","exp":"makeSound là hàm thuần ảo nên mỗi lớp con tự viết lại. dog.makeSound() in Woof! kèm một tab, cat.makeSound() in Meow!. Hàm getInfo không được gọi nên phần tên và loài không hiện ra.","topic":"2.3. Lớp trừu tượng / 2. TRỪU TƯỢNG","note":""}]},{"n":5,"title":"Lập trình hướng đối tượng trong C#","lang":"C#","qs":[{"id":"5-1","n":1,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n{\n     int i = 1;\n     public int GetInt()\n     {\n         return i;\n}\n}\nclass Two : One\n{\n     int i = 2;\n     public int GetInt()\n     {\n            return i;\n}\n}\npublic class Test\n{\n        public static void Main(String[] args)\n        {\n             One one = new One();\n             Two two = new Two();\n             Console.WriteLine(two.GetInt());\n        }\n}","lang":"csharp","opts":["1","2","Lỗi biên dịch","Lỗi thực thi"],"ans":"B","exp":"two có kiểu Two, mà Two có hàm GetInt riêng trả về biến i bằng 2 của chính nó. Hàm của lớp cha bị che đi nên kết quả in ra 2.","topic":"4. KẾ THỪA / 4.1. Khai báo lớp kế thừa","note":""},{"id":"5-2","n":2,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n{\n        public void Print()\n        {\nConsole.WriteLine(\"1\");\n}\n}\nclass Two : One\n{\n        public void Print()\n        {\nConsole.WriteLine(\"2\");\n}\n}\npublic class Test\n{\n        public static void Main(String[] args)\n        {\n          Two one = new Two();\n            one.Print();\n        }\n}","lang":"csharp","opts":["1","2","Lỗi biên dịch","Lỗi thực thi"],"ans":"B","exp":"Biến one được khai báo kiểu Two và cũng tạo bằng new Two nên cả kiểu khai báo lẫn đối tượng thật đều là Two. Hàm Print của Two chạy và in 2.","topic":"4. KẾ THỪA / 4.1. Khai báo lớp kế thừa","note":""},{"id":"5-3","n":3,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n{\n     public void Print(int i)\n     {\n             Console.WriteLine(\"Parent\");\n     }\n}\nclass Two : One\n{\n     public void Print(byte b)\n     {\n          Console.WriteLine(\"Child\");\n        }\n}\npublic class Test\n{\npublic static void Main(String[] args)\n        {\n            Two one = new Two();\n            one.Print(10);\n        }\n}","lang":"csharp","opts":["Parent","Child","Lỗi biên dịch","Lỗi thực thi"],"ans":"B","exp":"Lớp con khai báo Print nhận byte nên nó che luôn bản nhận int của lớp cha. Số 10 là hằng nằm trong khoảng của byte nên vẫn truyền được, và bản của lớp con được gọi, in ra Child.","topic":"4. KẾ THỪA / 4.1. Khai báo lớp kế thừa","note":""},{"id":"5-4","n":4,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n{\n        public void Tool(int i)\n        {\n            Console.WriteLine(\"No\");\n        }\n}\nclass Two : One\n{\n    public  void Tool(byte b)\n    {\n        Console.WriteLine(\"Ok\");\n    }\n}\npublic class Test\n{\n    public static void Main(String []args)\n    {\n        One one = new Two();\n        one.Tool(10);\n    }\n}","lang":"csharp","opts":["No","Ok","Lỗi biên dịch","Lỗi thực thi"],"ans":"A","exp":"Biến one khai báo kiểu One, mà hai hàm Tool không dùng virtual và override nên máy chọn hàm theo kiểu khai báo chứ không theo đối tượng thật. Bản của One chạy và in No.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"5-5","n":5,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class One {\n    public static void Tool(int i) {\n        Console.WriteLine(\"No\");\n    }\n}\npublic class Two : One {\n    public static void Tool(byte b) {\n        Console.WriteLine(\"Ok\");\n    }\n}\npublic class Test {\n       public static void Main(String []args){\n        One one = new Two();\n        One.Tool(5);\n    }\n}","lang":"csharp","opts":["Ok","No","Lỗi biên dịch","Lỗi thực thi"],"ans":"B","exp":"Phương thức static luôn được gọi theo tên lớp. Câu lệnh viết rõ One.Tool(5) nên bản của lớp One chạy và in No. Phương thức static không bao giờ bị ghi đè, nó chỉ bị che.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"5-6","n":6,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, Lựa chọn nào được viết ở dòng //your code here, khi biên dịch sẽ không có lỗi?","code":"interface Inter\n{\n}\nclass One\n{\n}\nclass Two : One\n{\n}\nclass Three : One\n{\n}\nclass Four :Two, Inter\n{\n}\nclass Five : Four\n{\n}\nclass Six : Three\n{\n}\npublic class Test\n{\n    public static void main(String[] args)\n    {\n        // your code here\n    }\n}","lang":"csharp","opts":["Inter inter = new One();","Inter inter = new Two ();","Inter inter = new Three();","Inter inter = new Four();"],"ans":"D","exp":"Chỉ có lớp Four khai báo thực thi interface Inter, nên chỉ đối tượng Four mới gán được cho biến kiểu Inter. One, Two, Three đều không liên quan tới interface này.","topic":"6.8. Gán đối tượng cho interface / 6. GIAO DIỆN TRÊN NGÔN NGỮ C#","note":""},{"id":"5-7","n":7,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, lựa chọn nào được viết ở dòng //your code here, khi biên dịch sẽ không có lỗi?","code":"interface Inter\n{\n}\nclass One\n{\n}\nclass Two : One\n{\n}\nclass Three : One\n{\n}\nclass Four : Two, Inter\n{\n}\nclass Five : Four\n{\n}\nclass Six : Three\n{\n}\npublic class Test\n{\n    public static void Main(String[] args)\n    {\n        // your code here\n    }\n}","lang":"csharp","opts":["Inter inter = new Four();","Inter inter = new Inter ();","Six six = new Three ();","Three three = new One();"],"ans":"A","exp":"Cùng lý do với câu trên, Four là lớp duy nhất thực thi Inter nên dòng A hợp lệ. Dòng B sai vì không tạo đối tượng trực tiếp từ interface. Hai dòng còn lại sai vì gán đối tượng lớp cha cho biến kiểu lớp con.","topic":"6.8. Gán đối tượng cho interface / 6. GIAO DIỆN TRÊN NGÔN NGỮ C#","note":""},{"id":"5-8","n":8,"stem":"Cho chương trình viết bằng ngôn ngữ  C# như sau, khi biên dịch và thực thi chương trình, kết quả là gì?","code":"class One\n{\n}\nclass Two : One\n{\n   public void Print()\n   {\n      Console.WriteLine(\"Two\");\n   }\n}\npublic class Test\n{\n    public static void Main(String[] args)\n    {\n        Two one = new Two();\n        one.Print();\n    }\n}","lang":"csharp","opts":["Two","Lỗi biên dịch","Lỗi thực thi","Cả 3 đáp án đều sai"],"ans":"A","exp":"Two kế thừa One và có thêm hàm Print của riêng nó. Đối tượng kiểu Two gọi Print bình thường nên in ra Two.","topic":"","note":""},{"id":"5-9","n":9,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n{\n        int x = 10;\n        public  One(int x)\n        {\n                this.x = x++;\n        }\n}\npublic class Test\n{\n        public static void Main(String[] args)\n        {\n                One one = new One(20);\n                 Console.WriteLine(one.x);\n        }\n}","lang":"csharp","opts":["1","0","6","Lỗi biên dịch"],"ans":"D","exp":"Biến x trong lớp One không ghi phạm vi nên mặc định là private. Dòng Console.WriteLine(one.x) trong lớp Test đọc biến private từ bên ngoài nên chương trình lỗi biên dịch.","topic":"1. LỚP / 1.3. Phạm vi truy cập của thuộc tính và phương thức","note":""},{"id":"5-10","n":10,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n{\n        public One(int x)\n        {\n                Console.WriteLine(\"int constructor\");\n        }\n        public One(long l)\n        {\n                Console.WriteLine(\"long constructor\");\n        }\n}\npublic class Test\n{\n        public static void Main(String[] args)\n        {\n            long l = 201;\n                    One one = new One(l);\n        }\n}","lang":"csharp","opts":["int constructor","long constructor int constructor","long constructor long constructor","long constructor"],"ans":"D","exp":"Biến l có kiểu long nên trình biên dịch chọn constructor nhận long. Chỉ một constructor chạy nên màn hình chỉ in một dòng.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.1. Constructor","note":""},{"id":"5-11","n":11,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n{\n    public One()\n    {\n        Console.WriteLine(\"One constructor\");\n    }\n    public One(long l)\n    {\n        Console.WriteLine(\"One long constructor\");\n    }\n}\nclass Two : One\n{\n    public Two(int i)\n    {\n        Console.WriteLine(\"Two int constructor\");\n    }\n    public Two(long l)\n    {\n        Console.WriteLine(\"Two long constructor\");\n    }\n}\npublic class Test\n{\n    public static void Main(String[] args)\n    {\n        long value = 68;\n        One one = new Two(value);\n    }\n}","lang":"csharp","opts":["Two int constructor","One long constructor","One constructor - Two long constructor","One constructor"],"ans":"C","exp":"new Two(value) với value kiểu long nên constructor Two(long) chạy. Nhưng trước đó constructor của lớp cha phải chạy trước, mà Two không ghi base nên C# tự gọi One() không tham số. Kết quả là One constructor rồi tới Two long constructor.","topic":"4. KẾ THỪA / 4.3. Constructor trong kế thừa","note":""},{"id":"5-12","n":12,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n{\n        public One(int x)\n        {\n                  Console.WriteLine(\"int constructor\");\n        }\n        public One(char c)\n        {\n                Console.WriteLine(\"char constructor\");\n        }\n        void Two(String str)\n        {\n                Console.WriteLine(\"String constructor\");\n        }\n}\npublic class Test\n{\n        public static void Main(String[] args)\n        {\n                String ch = \"c\";\n                One one = new One(1);\n        }\n}","lang":"csharp","opts":["char constructor","int constructor","Lỗi biên dịch","Cả 3 đáp án đều sai"],"ans":"B","exp":"Đối số truyền vào là số 1, kiểu int, nên constructor One(int) chạy và in int constructor. Biến ch khai báo ở trên không hề được dùng.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.1. Constructor","note":""},{"id":"5-13","n":13,"stem":"Khi bạn biên dịch và chạy chương trình viết bằng ngôn ngữ C# bằng lệnh đã cho ở bên dưới sau kết quả sẽ là:","code":"class ITestInterface\n{\n        int status = 0;\n}\npublic class Test : ITestInterface\n{\npublic static void Main(String[] args)\n{\n    Test t = new Test();\n         t.status = 69;\n             Console.WriteLine(t.status);\n}\n}","lang":"csharp","opts":["1","0","2","Lỗi biên dịch (vì status là private)"],"ans":"D","exp":"Biến status trong lớp ITestInterface không ghi phạm vi nên mặc định là private. Lớp con Test không đọc được biến private của cha, vì vậy dòng t.status = 69 gây lỗi biên dịch.","topic":"1. LỚP / 1.3. Phạm vi truy cập của thuộc tính và phương thức","note":""},{"id":"5-14","n":14,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class ITestInterface\n{\n        int i = 0;\n        public ITestInterface()\n        {\n                Console.WriteLine(\"I Constructor \");\n        }\n}\npublic class Test : ITestInterface\n{\n        public Test()\n        {\n                Console.WriteLine(\"Test Constructor \");\n        }\n        public static void Main(String[] args)\n        {\n                Test t = new Test();\n        }\n}","lang":"csharp","opts":["Test Constructor","I Constructor Test Constructor","T Constructor I Constructor","Lỗi biên dịch"],"ans":"B","exp":"Khi tạo đối tượng Test, constructor của lớp cha luôn chạy trước rồi mới tới lớp con. Vì vậy in I Constructor rồi mới tới Test Constructor.","topic":"4. KẾ THỪA / 4.3. Constructor trong kế thừa","note":""},{"id":"5-15","n":15,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"Giải thích đoạn code sau:\nclass One\n{\n        String SayHello1(String name)\n        {\n            return \"Hello \" + name;\n        }\n        char[] SayHello2(String name)\n        {\n            return (\"Hello \" + name).ToCharArray();\n        }\n}\npublic class Test\n{\n        public static void Main(String[] args)\n        {\n            One one = new One();\n            Object[] ob = one.SayHello2(\"Hhâ\");\n            if (ob instance String)\n                {\n                Console.WriteLine(\"String\");\n            }\n        else\n            {\n                Console.WriteLine(\"Array\");\n            }\n        }\n}","lang":"csharp","opts":["Hello OCAJP","String","Array","Lỗi biên dịch"],"ans":"D","exp":"Đoạn code dùng từ khóa instance để kiểm tra kiểu, nhưng C# không có từ khóa này, đúng ra phải là is. Ngoài ra gán mảng ký tự cho mảng Object cũng không hợp lệ. Chương trình lỗi biên dịch.","topic":"1. LỚP / 1.3. Phạm vi truy cập của thuộc tính và phương thức","note":""},{"id":"5-16","n":16,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n    {\n        public void Greetings()\n        {\n            Console.WriteLine(\"Hello\");\n        }\n    }\n    class Two : One\n    {\n        public void Greetings()\n        {\n            Console.WriteLine(\"Hi\");\n        }\n    }\n    public class Test\n    {\n        public static void Main(String[] args)\n        {\n            One one = new Two();\n            one.Greetings();\n        }\n    }","lang":"csharp","opts":["Hello","Hi","Lỗi biên dịch","Lỗi thực thi"],"ans":"A","exp":"Biến one khai báo kiểu One, hai hàm Greetings không có virtual và override nên đây chỉ là che khuất chứ không phải đa hình. Máy chọn theo kiểu khai báo là One nên in Hello.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"5-17","n":17,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n    {\n        public One()\n        {\n          Console.WriteLine(\"Hello Object\");\n        }\n        public One(int x)\n        {\n         Console.WriteLine(\"Hello Object with int\");\n        }\n    }\n    public class Test\n    {\n        public static void Main(String[] args)\n        {\n            One one = new One();\n        }\n    }","lang":"csharp","opts":["Hello Object with int","Hello Object","Hello Object with int Hello Object","Hello Object Hello Object with int"],"ans":"B","exp":"new One() không truyền tham số nên constructor không tham số chạy và in Hello Object. Một lần tạo đối tượng chỉ có một constructor chạy.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.1. Constructor","note":""},{"id":"5-18","n":18,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n    {\n        public One(int i)\n        {\n           Console.WriteLine(\"int\");\n        }\n        public  One(short s)\n        {\n            Console.WriteLine(\"short\");\n        }\n    }\n    public class Test\n    {\n        public static void Main(String[] args)\n        {\n            short s = 10;\n            One one = new One(s);\n        }\n    }","lang":"csharp","opts":["int short","short","int","short int"],"ans":"B","exp":"Biến s có kiểu short nên trình biên dịch chọn đúng bản One(short) và in short. Nếu không có bản short thì mới phải ép lên int.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.1. Constructor","note":""},{"id":"5-19","n":19,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n    {\n        public void ClassName()\n        {\n            Console.WriteLine(\"Parent\");\n        }\n    }\n    class Two : One\n    {\n    public void ClassName()\n    {\n       Console.WriteLine(\"Child\");\n    }\n}\npublic class Test\n{\n    public static void Main(String[] args)\n    {\n        One one = new Two();\n        one.ClassName();\n    }\n}","lang":"csharp","opts":["Parent","Child Parent","Parent Child","Child"],"ans":"A","exp":"Biến one khai báo kiểu One nên gọi bản ClassName của lớp cha, in Parent. Muốn in Child thì lớp cha phải khai báo virtual và lớp con phải ghi override.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"5-20","n":20,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n{\n    public void Greetings()\n    {\n        Console.WriteLine(\"Hello\");\n    }\n}\nclass Two : One\n{\n    public void Greetings()\n    {\n        Console.WriteLine(\"Hi\");\n    }\n}\npublic class Test\n{\n    public static void Main(String[] args)\n    {\n        Two one = new Two();\n        one.Greetings();\n    }\n}","lang":"csharp","opts":["Hello","Hello Hi","Hi Hello","Hi"],"ans":"D","exp":"Lần này biến one khai báo kiểu Two và đối tượng cũng là Two, nên bản của lớp con chạy và in Hi. So sánh với câu 19 để thấy vai trò của kiểu biến.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"5-21","n":21,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n{\n    public void Greetings()\n    {\n        Console.WriteLine(\"Hello\");\n    }\n}\nclass Two : One\n{\n    public void Greetings()\n    {\n        Console.WriteLine(\"Hi\");\n    }\n}\npublic class Test\n{\n    public static void Main(String[] args)\n    {\n        One one = new One();\n        one.Greetings();\n    }\n}","lang":"csharp","opts":["Hello","Hi","Lỗi biên dịch","Lỗi thực thi"],"ans":"A","exp":"Cả biến lẫn đối tượng đều là One nên chắc chắn chạy hàm của One, in Hello. Lớp Two có mặt trong chương trình nhưng không được dùng tới.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"5-22","n":22,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n{\n    public void ClassName()\n    {\n        Console.WriteLine(\"Parent\");\n    }\n}\nclass Two : One\n{\n    public void ClassName()\n    {\n        Console.WriteLine(\"Child\");\n    }\n}\npublic class Test\n{\n    public static void Main(String[] args)\n    {\n        One one = new Two();\n        one.ClassName();\n    }\n}","lang":"csharp","opts":["Parent","Child","Lỗi biên dịch","Lỗi thực thi"],"ans":"A","exp":"Biến kiểu One, hàm không có virtual và override nên chọn theo kiểu biến, in Parent. Đây là quy tắc lặp lại nhiều lần trong chương 5, cần thuộc.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"5-23","n":23,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n{\n    private void CallMe()\n    {\n        Console.WriteLine(\"Parent\");\n    }\n    public void Caller()\n    {\n        CallMe();\n    }\n}\nclass Two : One\n{\n    public void CallMe()\n    {\n        Console.WriteLine(\"Child\");\n    }\n}\npublic class Test\n{\n    public static void Main(String[] args)\n    {\n        Two two = new Two();\n        two.Caller();\n    }\n}","lang":"csharp","opts":["Parent","Child","Parent Child","Lỗi biên dịch"],"ans":"A","exp":"Hàm CallMe của lớp One là private nên lớp con không thấy và cũng không ghi đè được. Hàm Caller nằm trong One nên nó gọi bản CallMe của chính One và in Parent.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"5-24","n":24,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n{\n    public int Method()\n    {\n        Console.WriteLine(\"int\");\n        return 0;\n    }\n}\nclass Two : One\n{\n    public int Method()\n    {\n        Console.WriteLine(\"short\");\n        return 1;\n    }\n}\npublic class Test\n{\n    public static void Main(String[] args)\n    {\n        One one = new Two();\n        one.Method();\n    }\n}","lang":"csharp","opts":["int","short","Lỗi biên dịch","Lỗi thực thi"],"ans":"A","exp":"Vẫn là trường hợp không virtual, không override. Biến khai báo kiểu One nên bản Method của lớp cha được chọn, in int.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"5-25","n":25,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n{\n    public void SomeMethod()\n    {\n        Console.WriteLine(\"Exception\");\n    }\n}\nclass Two : One\n{\n    public void SomeMethod()\n    {\n        Console.WriteLine(\"Not Exception\");\n    }\n    public static void Main(String[] args)\n    {\n        One one = new Two();\n        one.SomeMethod();\n    }\n}","lang":"csharp","opts":["Exception","Not Exception","Lỗi biên dịch","Lỗi thực thi"],"ans":"A","exp":"Biến one có kiểu One, hai hàm SomeMethod chỉ che nhau chứ không ghi đè, nên bản của One chạy và in Exception. Chữ Exception ở đây chỉ là nội dung in ra chứ không liên quan tới xử lý lỗi.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"5-26","n":26,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n{\n    public void SomeMethod()\n    {\n        Console.WriteLine(\"Exception\");\n    }\n}\nclass Two : One\n{\n    public void SomeMethod()\n    {\n        Console.WriteLine(\"Override Exception\");\n    }\n}\npublic class Test\n{\n    public static void Main(String[] args)\n    {\n        Two one = new Two();\n        try\n        {\n            one.SomeMethod();\n        }\n        catch (Exception e)\n        {\n        }\n    }\n}","lang":"csharp","opts":["Exception","Override Exception","Lỗi biên dịch","Lỗi thực thi"],"ans":"B","exp":"Lần này biến one khai báo kiểu Two nên bản của lớp con chạy và in Override Exception. Khối try catch không ảnh hưởng gì vì không có lỗi nào xảy ra.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"5-27","n":27,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n{\n    public One()\n    {\n        Console.WriteLine(\"One,\");\n    }\n}\nclass Two : One\n{\n    void Four()\n    {\n        Console.WriteLine(\"Two,\");\n    }\n}\nclass Three : Two\n{\n    public Three()\n    {\n        Console.WriteLine(\"Three,\");\n    }\n}\npublic class Test\n{\n    public static void Main(String[] args)\n    {\n        Three three = new Three();\n    }\n}","lang":"csharp","opts":["One,Two,Three,","Three,Two,One,","One,Three,","Lỗi biên dịch"],"ans":"C","exp":"Tạo Three thì constructor chạy từ trên xuống: One in One, rồi Two dùng constructor mặc định nên không in gì, rồi Three in Three. Hàm Four trong lớp Two không phải constructor nên không tự chạy.","topic":"4. KẾ THỪA / 4.3. Constructor trong kế thừa","note":""},{"id":"5-28","n":28,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, Lựa chọn nào nếu được viết ở dòng //method declaration here, sẽ được gọi là nạp chồng (override) phương thức someMethod được định nghĩa trong lớp One","code":"class One\n{\n    public void SomeMethod(int i)\n    {\n    }\n}\nclass Two : One\n{\n    public void SomeMethod(double anotherint)\n    {\n    }\n    //method declaration here\n}\npublic class Test\n{\n    public static void Main(String[] args)\n    {\n        Two two = new Two();\n    }\n}","lang":"csharp","opts":["void public someMethod(int i){}","public void someMethod(int anotherint){}","public void Somemethod(String str){}","public void someMethod(double anotherint){}"],"ans":"B","exp":"Ghi đè đòi hỏi hàm ở lớp con phải cùng tên và cùng danh sách tham số với hàm ở lớp cha. Hàm gốc nhận một int nên bản ở lớp con cũng phải nhận một int. Các lựa chọn khác sai tên, sai kiểu tham số hoặc sai thứ tự từ khóa.","topic":"4. KẾ THỪA / 4.1. Khai báo lớp kế thừa","note":""},{"id":"5-29","n":29,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n{\n    void Two()\n    {\n        Console.WriteLine(\"One,\");\n    }\n}\nclass Two : One\n{\n    void One()\n    {\n        Console.WriteLine(\"Two,\");\n    }\n}\nclass Three : Two\n{\n    public void Four()\n    {\n        Console.WriteLine(\"Three,\");\n    }\n}\npublic class Test\n{\n    public static void Main(String[] args)\n    {\n        Three three = new Three();\n        three.Four();\n    }\n}","lang":"csharp","opts":["One,Two,Three,","Three,Two,One,","Three,","Cả 3 đáp án đều sai"],"ans":"C","exp":"Chương trình chỉ gọi three.Four() nên chỉ in Three. Hai hàm Two và One trong các lớp cha không được gọi và cũng không phải constructor.","topic":"4. KẾ THỪA / 4.3. Constructor trong kế thừa","note":""},{"id":"5-30","n":30,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test\n{\n    public static void Main(String[] args)\n    {\n        int i = 68;\n        Console.WriteLine(++i);\n    }\n}","lang":"csharp","opts":["69","68","Lỗi biên dịch","Cả 3 đáp án đều sai"],"ans":"A","exp":"Toán tử ++ đứng trước biến nên tăng giá trị rồi mới in. 68 cộng 1 bằng 69.","topic":"","note":""},{"id":"5-31","n":31,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"abstract class Tesst\n{\n    public void SomeThing()\n    {\n        Console.WriteLine(\"Something\");\n    }\n    public void NoThing();\n}\nclass TestChild : Tesst\n{\n    public void NoThing()\n    {\n        Console.WriteLine(\"Nothing\");\n    }\n}\npublic class Test\n{\n    public static void Main(String[] args)\n    {\n        TestChild testChild = new TestChild();\n        testChild.SomeThing();\n    }\n}","lang":"csharp","opts":["Nothing","Something","Lỗi biên dịch","Lỗi thực thi"],"ans":"C","exp":"Trong lớp trừu tượng, một phương thức không có thân bắt buộc phải ghi từ khóa abstract. Dòng public void NoThing(); thiếu từ khóa đó nên chương trình lỗi biên dịch.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.2. Trừu tượng","note":""},{"id":"5-32","n":32,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test\n{\n    String name = \"Test\";\n    public Test()\n    {\n        name = \"TestObject\";\n    }\n    public static void Main(String[] args)\n    {\n        Test test = new Test();\n        Console.WriteLine(\"Name is \" + test.name);\n    }\n}","lang":"csharp","opts":["Name is Test","Name is TestObject","Lỗi biên dịch","Cả 3 đáp án đều sai"],"ans":"B","exp":"Biến name được gán Test khi khai báo, nhưng constructor chạy sau và gán đè thành TestObject. Giá trị cuối cùng là TestObject.","topic":"1. LỚP / 1.3. Phạm vi truy cập của thuộc tính và phương thức","note":""},{"id":"5-33","n":33,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test\n{\n    static String name = \"Test\";\n    public Test()\n    {\n        name = \"TestObject\";\n    }\n    public static void Main(String[] args)\n    {\n        Console.WriteLine(\"Name is \" + name);\n    }\n}","lang":"csharp","opts":["Name is Test","Name is TestObject","Lỗi biên dịch","Cả 3 đáp án đều sai"],"ans":"A","exp":"Hàm Main là static nên chạy được mà không cần tạo đối tượng, và chương trình cũng không hề tạo đối tượng Test nào. Constructor không chạy nên name vẫn là Test.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.4. Thuộc tính tĩnh và phương thức tĩnh","note":""},{"id":"5-34","n":34,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class One\n{\n    public One()\n    {\n        Console.WriteLine(\"Abstract Class\");\n    }\n    abstract void Nothing();\n}\npublic class Test\n{\n    public static void Main(String[] args)\n    {\n        One one = new One();\n    }\n}","lang":"csharp","opts":["Abstract Class","Lỗi biên dịch","Lỗi thực thi","Cả 3 đáp án đều sai"],"ans":"B","exp":"Lớp One chứa phương thức abstract nhưng bản thân lớp lại không khai báo abstract. Từ khóa abstract phải có ở cả lớp lẫn phương thức, thiếu một chỗ là lỗi biên dịch.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.2. Trừu tượng","note":""},{"id":"5-35","n":35,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class One\n{\n    public One()\n    {\n        Console.WriteLine(\"One\");\n    }\n}\npublic class Test\n{\n    public static void Main(String[] args)\n    {\n        One one = new One();\n    }\n}","lang":"csharp","opts":["One","Lỗi biên dịch","Lỗi thực thi","Cả 3 đáp án đều sai"],"ans":"A","exp":"Lớp bình thường, constructor không tham số, tạo đối tượng thì constructor chạy và in One. Đây là trường hợp cơ bản nhất để đối chiếu với các câu có lỗi phía trên.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.1. Constructor","note":""},{"id":"5-36","n":36,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n{\n    public One(String name)\n    {\n        Console.WriteLine(\"Hello \" + name + \",\");\n    }\n}\nclass Two : One\n{\n    public Two() : base(\"Alice\")\n    {\n        Console.WriteLine(\"Hi,\");\n    }\n}\npublic class Test\n{\n    public static void Main(String[] args)\n    {\n        Two two = new Two();\n    }\n}","lang":"csharp","opts":["Hi,","Alice","Hello Alice,Hi,","Cả 3 đáp án đều sai"],"ans":"C","exp":"Từ khóa base(\"Alice\") gọi constructor của lớp cha kèm chuỗi Alice, nên in Hello Alice, trước. Sau đó thân constructor của Two mới chạy và in Hi,","topic":"4. KẾ THỪA / 4.3. Constructor trong kế thừa","note":""},{"id":"5-37","n":37,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n{\n    public One(String name)\n    {\n        Console.WriteLine(\"Hello \" + name + \",\");\n    }\n}\nclass Two : One\n{\n    public Two() : base(\"Two\")\n    {\n        Console.WriteLine(\"Hi,\");\n    }\n}\npublic class Test\n{\n    public static void Main(String[] args)\n    {\n        Two two = new Two();\n    }\n}","lang":"csharp","opts":["Hi,","Hello Two,Hi,","Lỗi biên dịch","Cả 3 đáp án đều sai"],"ans":"B","exp":"Giống câu trước nhưng chuỗi truyền vào base là Two nên in Hello Two, rồi tới Hi,. Nhớ rằng constructor của cha luôn hoàn tất trước khi thân constructor của con chạy.","topic":"4. KẾ THỪA / 4.3. Constructor trong kế thừa","note":""},{"id":"5-38","n":38,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class One\n{\n    public One(String name)\n    {\n        Console.WriteLine(\"Hello \" + name + \",\");\n    }\n}\nclass Two : One\n{\n    public Two() : base(\"Two\")\n    {\n        Console.WriteLine(\"Hi,\");\n    }\n}\npublic class Test\n{\n    public static void Main(String[] args)\n    {\n        One two = new Two();\n    }\n}","lang":"csharp","opts":["Hi,","Hi,Hello Two,","Hello Two,Hi,","Cả 3 đáp án đều sai"],"ans":"C","exp":"Đối tượng thật vẫn là Two dù biến khai báo kiểu One, mà constructor thì luôn chạy đủ theo đối tượng thật. Vì vậy in Hello Two, rồi Hi,","topic":"4. KẾ THỪA / 4.3. Constructor trong kế thừa","note":""},{"id":"5-39","n":39,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n{\n    public One(String name)\n    {\n        Console.WriteLine(\"Hello \" + name + \",\");\n    }\n}\nclass Two : One\n{\n    public Two() : base(\"Two\")\n    {\n        Console.WriteLine(\"Hi,\");\n    }\n}\npublic class Test\n{\n    public static void Main(String[] args)\n    {\n        One two = new One();\n    }\n}","lang":"csharp","opts":["Cả 3 đáp án đều sai","Hello","Lỗi biên dịch","Lỗi thực thi"],"ans":"C","exp":"Lớp One chỉ có constructor nhận một chuỗi, không có constructor rỗng. Dòng new One() không tìm được constructor phù hợp nên chương trình lỗi biên dịch.","topic":"4. KẾ THỪA / 4.3. Constructor trong kế thừa","note":""},{"id":"5-40","n":40,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n{\n    public One()\n    {\n        Console.WriteLine(\"Parent \");\n    }\n}\nclass Two : One\n{\n    public Two()\n    {\n        Console.WriteLine(\"Child \");\n    }\n}\npublic class Test\n{\n    public static void Main(String[] args)\n    {\n        One one = new Two();\n    }\n}","lang":"csharp","opts":["Parent Child","Child Parent","Child","Parent"],"ans":"A","exp":"Tạo đối tượng Two thì constructor của lớp cha chạy trước và in Parent, sau đó constructor lớp con in Child. Kiểu khai báo là One không ảnh hưởng gì tới constructor.","topic":"4. KẾ THỪA / 4.3. Constructor trong kế thừa","note":""},{"id":"5-41","n":41,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class TestChild : Test\n{\n    public TestChild()\n    {\n        Console.WriteLine(\"TestChild1 \");\n    }\n}\npublic class Test\n{\n    void TestChild()\n    {\n        Console.WriteLine(\"TestChild2 \");\n    }\n    public static void Main(String[] args)\n    {\n        new Test().TestChild();\n    }\n}","lang":"csharp","opts":["TestChild1 TestChild2","TestChild2 TestChild1","TestChild2","Cả 3 đáp án đều sai"],"ans":"C","exp":"Hàm Main chỉ gọi new Test().TestChild(), tức là gọi phương thức TestChild của lớp Test và in TestChild2. Lớp TestChild có constructor riêng nhưng không hề được tạo đối tượng nên không in gì.","topic":"2. ĐỐI TƯỢNG / 2.2. Khởi tạo đối tượng tạm thời","note":""},{"id":"5-42","n":42,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test\n{\n     int i = 68;\n     void Print()\n     {\n         Console.WriteLine(i);\n     }\n     public static void Main(String[] args)\n     {\n         new Test().Print();\n     }\n}","lang":"csharp","opts":["0","68","Lỗi thực thi","Lỗi biên dịch"],"ans":"B","exp":"new Test() tạo đối tượng và i được gán 68 ngay khi khai báo. Sau đó Print in giá trị này ra màn hình.","topic":"2. ĐỐI TƯỢNG / 2.2. Khởi tạo đối tượng tạm thời","note":""},{"id":"5-43","n":43,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class One\n{\n        public void SayHello()\n        {\n            Console.WriteLine(\"Parent Hello\");\n        }\n}\nclass Two : One\n{\n        public void SayHello()\n        {\n            Console.WriteLine(\"Child Hello\");\n        }\n}\npublic class Test\n{\n        public static void Main(String[] args)\n        {\n            One o = new Two();\n            o.SayHello();\n        }\n}","lang":"csharp","opts":["Parent Hello","Child Hello","Lỗi biên dịch","Cả 3 đáp án đều sai"],"ans":"A","exp":"Biến o khai báo kiểu One, hai hàm SayHello không có virtual và override nên không có đa hình. Máy chọn theo kiểu biến nên in Parent Hello.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"5-44","n":44,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test\n{\n     public int Count(int i)\n     {\n         return 0;\n     }\n     public long Count(long i)\n     {\n         return 0L;\n     }\n     public static void Main(String[] args)\n     {\n         Test test = new Test();\n         int resultInt = test.Count(5);\n         long resultLong = test.Count(6);\n         Console.WriteLine(resultInt);\n         Console.WriteLine(resultLong);\n     }\n}","lang":"csharp","opts":["5","6","0","00"],"ans":"D","exp":"Cả hai hàm Count đều trả về 0. Lần gọi thứ nhất khớp bản int, lần thứ hai cũng khớp bản int vì 6 là số nguyên. Hai lệnh in cho ra hai số 0 liền nhau.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.5. Quá tải phương thức (Overloading)","note":""},{"id":"5-45","n":45,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test\n{\n     public int Count(int i)\n     {\n         return 0;\n     }\n     public static void Main(String[] args)\n     {\n         Test test = new TestChild();\n         int resultInt = test.Count(5);\n         Console.WriteLine(\"Result for int: \" + resultInt);\n     }\n}\nclass TestChild : Test\n{\n     public int Count(int i)\n     {\n         return 1;\n     }\n}","lang":"csharp","opts":["Lỗi biên dịch","Lỗi thực thi","Result for int: 0","Result for int: 1"],"ans":"C","exp":"Biến test khai báo kiểu Test, hàm Count không virtual nên bản của lớp cha được gọi và trả về 0. Đây lại là trường hợp che khuất chứ không phải ghi đè.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"5-46","n":46,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n{\n        public void SayHello()\n        {\n            Console.WriteLine(\"Parent Hello\");\n        }\n}\nclass Two : One\n{\n        public void SayHello()\n        {\n            Console.WriteLine(\"Child Hello\");\n        }\n}\npublic class Test\n{\n        public static void Main(String[] args)\n        {\n            One o = new Two();\n            o.SayHello();\n        }\n}","lang":"csharp","opts":["Parent Hello","Child Hello","Lỗi biên dịch","Lỗi thực thi"],"ans":"A","exp":"Giống câu 43, chỉ khác lớp One không ghi public. Kiểu biến vẫn là One và hàm không virtual nên in Parent Hello.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"5-47","n":47,"stem":"Cho chương trình viết bằng ngôn ngữ C#  như sau, khi biên dịch và thực thi chương trình, kết quả là gì?","code":"public class Test\n{\n    public int Count(int i)\n    {\n        return 0;\n    }\n    public int Count(double j)\n    {\n        return 1;\n    }\n    public static void Main(String[] args)\n    {\n        Test test = new Test();\n        int i = test.Count(5);\n        int d = test.Count(5.0);\n        Console.WriteLine(\"int: \" + i);\n        Console.WriteLine(\"double: \" + d);\n    }\n}","lang":"csharp","opts":["int: 0","double: 0","int: 0 double: 0","int: 0 double: 1"],"ans":"D","exp":"Đây là quá tải phương thức. test.Count(5) khớp bản nhận int nên trả về 0, test.Count(5.0) khớp bản nhận double nên trả về 1. Chương trình in cả hai kết quả.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.5. Quá tải phương thức (Overloading)","note":""},{"id":"5-48","n":48,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class One\n{\n      public void Count(int i)\n      {\n            Console.WriteLine(0);\n      }\n}\npublic class Test : One\n{\npublic void Count(int j)\n      {\n            Console.WriteLine(1);\n      }\n      public static void Main(String[] args)\n      {\n            One one = new Test(); one.Count(0);\n        }\n}","lang":"csharp","opts":["1","0","Lỗi biên dịch","Lỗi thực thi"],"ans":"B","exp":"Biến one khai báo kiểu One. Không có virtual và override nên hàm Count của lớp cha được chọn và in 0.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"5-49","n":49,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test\n{\n    public static void Main(String[] args)\n    {\n        One o = new One();\n        o.SayHello();\n    }\n}\npublic class One\n{\n    public void SayHello()\n    {\n        Console.WriteLine(\"Hello\");\n    }\n}","lang":"csharp","opts":["Hello","Lỗi biên dịch","Lỗi thực thi","Cả 3 đáp án đều sai"],"ans":"A","exp":"Lớp One có hàm public SayHello, đối tượng tạo bình thường nên gọi được. Thứ tự khai báo lớp trong file không ảnh hưởng gì, kết quả in Hello.","topic":"1. LỚP / 1.3. Phạm vi truy cập của thuộc tính và phương thức","note":""},{"id":"5-50","n":50,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test\n{\n    class TestInner\n    {\n        public void SayHi()\n        {\n            Console.WriteLine(\"Hi\");\n        }\n    }\n    public static void Main(String[] args)\n    {\n        TestInner inner = new TestInner();\n        inner.SayHi();\n    }\n}","lang":"csharp","opts":["Hi","Lỗi biên dịch","Lỗi thực thi","Cả 3 đáp án đều sai"],"ans":"A","exp":"TestInner là lớp lồng bên trong Test. Vì Main cũng nằm trong Test nên nó thấy lớp lồng và tạo đối tượng được, kết quả in Hi.","topic":"1. LỚP / 1.4. Lớp lồng nhau","note":""},{"id":"5-51","n":51,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test\n{\n    class TestInner\n    {\n        public void SayHi()\n        {\n            Console.WriteLine(\"Hi\");\n        }\n    }\n    public static void Main(String[] args)\n    {\n        Test t = new Test();\n    }\n}","lang":"csharp","opts":["Hi","Lỗi biên dịch","Lỗi thực thi","Cả 3 đáp án đều sai"],"ans":"D","exp":"Chương trình chỉ tạo đối tượng Test và không gọi SayHi lần nào. Không có gì được in ra nên cả ba đáp án đầu đều sai.","topic":"1. LỚP / 1.4. Lớp lồng nhau","note":""},{"id":"5-52","n":52,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test\n    {\n        public void Compute(int i, int j)\n        {\n           Console.WriteLine(\"int version\");\n        }\n        public void Compute(long i, long j)\n        {\n            Console.WriteLine(\"long version\");\n        }\n        public static void Main(String[] args)\n        {\n            Test t = new Test();\n            t.Compute(10, 5);\n        }\n    }","lang":"csharp","opts":["int version","long version","Lỗi biên dịch","Lỗi thực thi"],"ans":"A","exp":"Hai số 10 và 5 đều là số nguyên nên bản nhận int khớp chính xác hơn. Trình biên dịch luôn ưu tiên bản khớp đúng kiểu trước khi phải ép kiểu.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.5. Quá tải phương thức (Overloading)","note":""},{"id":"5-53","n":53,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, Lựa chọn nào được viết ở dòng //access variable here, khi biên dịch sẽ không có lỗi?","code":"public class Test\n{\n    private int i = 0;\n    int j = 1;\n    public int k = 2;\n    public class TestInner\n    {\n        private int l = 3;\n        int m = 4;\n        public int n = 5;\n        void SayHi()\n        {\n            //access variable here\n        }\n    }\n    public static void Main(String [] args)\n    {\n    }\n}","lang":"csharp","opts":["i = 5;","j = 5;","k = 5;","Cả 3 đáp án đều sai"],"ans":"D","exp":"Lớp lồng trong C# không tự động thấy các biến thực thể của lớp bao ngoài, muốn dùng thì phải có một tham chiếu tới đối tượng lớp ngoài. Vì vậy cả ba cách gán đều sai.","topic":"1. LỚP / 1.4. Lớp lồng nhau","note":""},{"id":"5-54","n":54,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n{\n    public void Process()\n    {\n        Console.WriteLine(\"Parent \");\n    }\n}\nclass Two : One\n{\n    public static void Process()\n    {\n        Console.WriteLine(\"Child\");\n    }\n}\npublic class Test\n{\n    public static void Main(String[] args)\n    {\n        One one = new Two();\n        one.Process();\n    }\n}","lang":"csharp","opts":["Parent","Child","Parent Child","Lỗi biên dịch"],"ans":"A","exp":"Lớp cha có Process là phương thức thực thể, lớp con lại khai báo Process là static. Lời gọi one.Process() đi qua biến kiểu One nên chạy bản của lớp cha và in Parent.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"5-55","n":55,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test\n    {\n        private int i = 0;\n        class TestInner\n        {\n            public int i = 1;\n           public void SayHi()\n            {\n               Console.WriteLine(i);\n            }\n        }\n        public static void Main(String[] args)\n        {\n            TestInner inner = new TestInner();\n            inner.SayHi();\n        }\n    }","lang":"csharp","opts":["0","1","Lỗi biên dịch","Lỗi thực thi"],"ans":"B","exp":"Lớp lồng TestInner có biến i riêng bằng 1, và hàm SayHi dùng chính biến này. Biến i của lớp ngoài hoàn toàn tách biệt nên kết quả in ra 1.","topic":"1. LỚP / 1.4. Lớp lồng nhau","note":""},{"id":"5-56","n":56,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n{\n    public One()\n    {\n        Console.WriteLine(\" One \");\n    }\n}\nclass Two : One\n{\n    public Two()\n    {\n        Console.WriteLine(\" Two \");\n    }\n}\npublic class Test\n{\n    public static void Main(String[] args)\n    {\n        One one = new One();\n        Two two = new Two();\n    }\n}","lang":"csharp","opts":["One","Two","One Two","One One Two"],"ans":"D","exp":"Dòng đầu tạo One nên in One. Dòng sau tạo Two, mà tạo lớp con thì constructor cha chạy trước nên in thêm One rồi tới Two. Tổng cộng màn hình hiện One, One, Two.","topic":"4. KẾ THỪA / 4.3. Constructor trong kế thừa","note":""},{"id":"5-57","n":57,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"interface TestInterface\n{\n}\nclass TestImplementation : TestInterface\n{\n    public TestImplementation()\n    {\n        Console.WriteLine(\"TestImplementation\");\n    }\n}\nclass Test\n{\n    public static void Main(String[] args)\n    {\n        TestImplementation implementation = new TestImplementation();\n    }\n}","lang":"csharp","opts":["TestImplementation","Hello, world!","Lỗi biên dịch","Lỗi thực thi"],"ans":"A","exp":"Interface rỗng nên lớp thực thi không phải cài đặt gì thêm. Tạo đối tượng TestImplementation thì constructor chạy và in tên lớp.","topic":"4. KẾ THỪA / 4.3. Constructor trong kế thừa","note":""},{"id":"5-58","n":58,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"interface TestInterface\n{\n    void SomeMethod();\n    class Test\n    {\n        public void Display()\n        {\n            Console.WriteLine(\"Test class.\");\n        }\n    }\n}\npublic class Test\n{\n    public static void Main(String[] args)\n    {\n        TestInterface.Test testObj = new TestInterface.Test();\n        testObj.Display();\n    }\n}","lang":"csharp","opts":["Test class.","Hello, world!","Lỗi biên dịch","Lỗi thực thi"],"ans":"C","exp":"C# không cho phép khai báo một lớp bên trong interface, interface chỉ chứa khai báo thành viên. Vì vậy chương trình lỗi biên dịch.","topic":"","note":""},{"id":"5-59","n":59,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n{\n    public abstract One();\n}\nclass Two : One\n{\n    public Two()\n    {\n        Console.WriteLine(\"Two\");\n    }\n}\npublic class Test\n{\n    public static void main(String[] args)\n    {\n        Two two = new Two();\n    }\n}","lang":"csharp","opts":["Two","One","Lỗi biên dịch","Lỗi thực thi"],"ans":"C","exp":"Constructor không bao giờ được khai báo abstract, vì abstract nghĩa là để lớp con cài đặt lại mà constructor thì không kế thừa được. Dòng public abstract One(); gây lỗi biên dịch.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.2. Trừu tượng","note":""},{"id":"5-60","n":60,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class TestInterface\n{\n    public class Test\n    {\n        public void Display()\n        {\n            Console.WriteLine(\"Test class.\");\n        }\n    }\n}\npublic class Test\n{\n    public static void Main(String[] args)\n    {\n        TestInterface.Test testObj = new TestInterface.Test();\n        testObj.Display();\n    }\n}","lang":"csharp","opts":["Test class.","Lỗi biên dịch","Lỗi thực thi","Cả 3 đáp án đều sai"],"ans":"A","exp":"Test là lớp lồng public bên trong TestInterface nên bên ngoài gọi được bằng cách ghi đủ đường dẫn TestInterface.Test. Kết quả in Test class.","topic":"1. LỚP / 1.4. Lớp lồng nhau","note":""},{"id":"5-61","n":61,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n{\n    int i = 1;\n    public One()\n    {\n        Console.WriteLine(i);\n    }\n}\nclass Two : One\n{\n    int i = 10;\n    public void One()\n    {\n        Console.WriteLine(i);\n    }\n}\npublic class Test\n{\n    public static void Main(String[] args)\n    {\n        One one = new Two();\n    }\n}","lang":"csharp","opts":["1","10","Lỗi biên dịch","Lỗi thực thi"],"ans":"A","exp":"Tạo đối tượng Two thì constructor One() của lớp cha chạy và in biến i của lớp cha, tức là 1. Hàm public void One() trong lớp Two chỉ là một phương thức bình thường chứ không phải constructor, và nó không được gọi.","topic":"4. KẾ THỪA / 4.3. Constructor trong kế thừa","note":""},{"id":"5-62","n":62,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n{\n}\nclass Two : One\n{\n}\npublic class Test\n{\n    public static void Main(String[] args)\n    {\n        One one = new One();\n        Two two = new Two();\n       Console.WriteLine( one);\n    }\n}","lang":"csharp","opts":["true","false","Cả 3 đáp án đều sai","Lỗi biên dịch"],"ans":"C","exp":"Console.WriteLine với một đối tượng sẽ gọi ToString mặc định và in ra tên kiểu, ở đây là One chứ không phải true hay false. Vì vậy cả ba đáp án đầu đều sai.","topic":"","note":""},{"id":"5-63","n":63,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n    {\n        public One()\n        {\n            Console.WriteLine(\"One\");\n        }\n    }\n    class Two : One\n    {\n    public Two()\n    {\n        Console.WriteLine(\"Two\");\n    }\n}\nclass Three\n{\n    Two two = new Two();\n    public Three()\n    {\n        Console.WriteLine(\"Three\");\n    }\n}\npublic class Test\n{\n    public static void Main(String[] args)\n    {\n        Three three = new Three();\n    }\n}","lang":"csharp","opts":["ThreeTwoOne","ThreeOneTwo","OneTwoThree","Cả 3 đáp án đều sai"],"ans":"C","exp":"Lớp Three có một thuộc tính kiểu Two, mà các thuộc tính luôn được khởi tạo trước khi thân constructor chạy. Tạo Two kéo theo constructor One chạy trước, nên thứ tự in là One, Two rồi mới Three.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.1. Constructor","note":""},{"id":"5-64","n":64,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class TestInner\n    {\n        public void Print()\n        {\n            Console.WriteLine(\"Hi\");\n        }\n    }\n    public class Test\n    {\n        public static void Main(String[] args)\n        {\n            TestInner t = new TestInner();\n             void Print()\n            {\n              Console.WriteLine(\"Hello\");\n            }\n            t.Print();\n        }\n    }","lang":"csharp","opts":["Hi","Hello","Lỗi biên dịch","Cả 3 đáp án đều sai"],"ans":"A","exp":"Biến t có kiểu TestInner nên t.Print() gọi phương thức của lớp đó và in Hi. Hàm Print khai báo ngay trong Main là hàm cục bộ, nó chỉ chạy nếu được gọi trực tiếp bằng tên.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"5-65","n":65,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class One\n{\n    string className = \"One\";\n}\npublic class Two : One\n{\n    string className = \"Two\";\n}\npublic class Test\n{\n    public static void Main(String[] args)\n    {\n        One one = new Two();\n        Console.WriteLine(one.className);\n    }\n}","lang":"csharp","opts":["One","Two","Lỗi biên dịch","Lỗi thực thi"],"ans":"C","exp":"Trường className trong cả hai lớp đều không ghi phạm vi nên mặc định là private. Từ lớp Test bên ngoài không đọc được, chương trình lỗi biên dịch.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"5-66","n":66,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n{\n    public One()\n    {\n        Console.WriteLine(\"One\");\n    }\n    public One(String str)\n    {\n        Console.WriteLine(\"OneStr\");\n    }\n}\nclass Two : One\n{\n    public Two(String str) : base(str)\n    {\n        Console.WriteLine(\"TwoStr\");\n    }\n}\npublic class Test\n{\n    public static void Main(String[] args)\n    {\n        Two two = new Two(\"Hello\");\n    }\n}","lang":"csharp","opts":["OneTwoStrOneStr","TwoStrOneStr","OneStrTwoStr","Lỗi biên dịch"],"ans":"C","exp":"Từ khóa base(str) chỉ rõ gọi constructor One(String) nên in OneStr trước. Sau đó thân constructor của Two mới chạy và in TwoStr.","topic":"4. KẾ THỪA / 4.3. Constructor trong kế thừa","note":""},{"id":"5-67","n":67,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test\n{\n    public void DoNothing(Object ob)\n    {\n        Console.WriteLine(\"Object\");\n    }\n    public void DoNothing(String str)\n    {\n        Console.WriteLine(\"String\");\n    }\n    public static void Main(String[] args)\n    {\n        Test test = new Test();\n        test.DoNothing(args);\n    }\n}","lang":"csharp","opts":["String","Object","Cả 3 đáp án đều sai","Lỗi biên dịch"],"ans":"B","exp":"args có kiểu mảng chuỗi chứ không phải chuỗi đơn, nên bản DoNothing(String) không khớp. Trình biên dịch chọn bản nhận Object vì mọi kiểu đều gán được cho Object, kết quả in Object.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.5. Quá tải phương thức (Overloading)","note":""},{"id":"5-68","n":68,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test\n{\n    public void DoNothing(Object ob)\n    {\n        Console.WriteLine(\"Object\");\n    }\n    public void DoNothing(int i)\n    {\n        Console.WriteLine(\"Integer\");\n    }\n    public static void Main(String[] args)\n    {\n        Test test = new Test();\n        test.DoNothing(5);\n    }\n}","lang":"csharp","opts":["Integer","Object","String","Cả 3 đáp án đều sai"],"ans":"A","exp":"Số 5 là int nên bản DoNothing(int) khớp chính xác. Quy tắc chọn hàm quá tải là ưu tiên bản khớp đúng kiểu, chỉ khi không có mới ép lên kiểu tổng quát hơn.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.5. Quá tải phương thức (Overloading)","note":""},{"id":"5-69","n":69,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test\n{\n    public void DoNothing(Object ob)\n    {\n        Console.WriteLine(\"Object\");\n    }\n    public void DoNothing(int i)\n    {\n        Console.WriteLine(\"Integer\");\n    }\n    public void DoNothing(Double d)\n    {\n        Console.WriteLine(\"Double\");\n    }\n    public static void Main(String[] args)\n    {\n        Test test = new Test();\n        test.DoNothing(new Test());\n    }\n}","lang":"csharp","opts":["Object","Integer","Double","Lỗi biên dịch"],"ans":"A","exp":"Tham số truyền vào là một đối tượng Test, không phải int cũng không phải Double. Chỉ còn bản nhận Object là phù hợp nên in Object.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.5. Quá tải phương thức (Overloading)","note":""},{"id":"5-70","n":70,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test\n{\n    public void DoNothing(Object ob)\n    {\n        Console.WriteLine(\"Object\");\n    }\n    public void DoNothing(int i)\n    {\n        Console.WriteLine(\"Integer\");\n    }\n    public void DoNothing(double i)\n    {\n        Console.WriteLine(\"Integer\");\n    }\n    public static void Main(String[] args)\n    {\n        Test test = new Test();\n        test.DoNothing(test);\n    }\n}","lang":"csharp","opts":["Integer","Double","Object","Cả 3 đáp án đều sai"],"ans":"C","exp":"Tương tự câu trước, tham số là đối tượng Test nên chỉ bản nhận Object khớp được, kết quả in Object.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.5. Quá tải phương thức (Overloading)","note":""},{"id":"5-71","n":71,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, Lựa chọn nào được viết ở dòng //variable name here, khi biên dịch sẽ không có lỗi?","code":"public class Test\n{\n    private int i = 1;\n    int j = 2;\n    public void TestMethod()\n    {\n    }\n    class TestInner\n    {\n        int k = 3;\n        public void InnerMethod(int m)\n        {\n            Console.WriteLine(//variable name here);\n        }\n    }\n}","lang":"csharp","opts":["i","i+m","i+j","k+m"],"ans":"D","exp":"Trong hàm của lớp lồng, ta chỉ dùng được biến của chính lớp lồng và tham số của hàm, tức là k và m. Các biến i và j thuộc về đối tượng lớp ngoài nên cần một tham chiếu mới truy cập được.","topic":"1. LỚP / 1.4. Lớp lồng nhau","note":""},{"id":"5-72","n":72,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, Lựa chọn nào được viết ở dòng //access variable here khi biên dịch sẽ không có lỗi?","code":"public class Test\n{\n    int x = 0;\n    static int y = 1;\n    public class InnerClass\n    {\n        int z = 2;\n        public void GetValue()\n        {\n            //access variable here\n        }\n    }\n}","lang":"csharp","opts":["y = z = 6;","y = 8;","z = 9;","Cả 3 đáp án đều đúng"],"ans":"D","exp":"Lớp lồng dùng được biến của chính nó là z, và cũng dùng được biến static y của lớp ngoài vì biến static thuộc về lớp chứ không thuộc về đối tượng. Cả ba dòng lệnh đều hợp lệ.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.4. Thuộc tính tĩnh và phương thức tĩnh","note":""},{"id":"5-73","n":73,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test\n{\n    public void TestMethod()\n    {\n        int a = 0;\n        class TestInner\n        {\n            public void InnerMethod(int x, int y)\n            {\n                Console.WriteLine(y);\n            }\n        }\n        TestInner inner = new TestInner();\n        inner.InnerMethod(1, 2);\n    }\n    public static void Main(String[] args)\n    {\n        Test main = new Test();\n        main.TestMethod();\n    }\n}","lang":"csharp","opts":["0","1","2","Lỗi biên dịch"],"ans":"D","exp":"C# không cho phép khai báo một lớp bên trong thân phương thức. Đây chính là điểm khác với Java, nơi lớp cục bộ trong hàm là hợp lệ.","topic":"1. LỚP / 1.4. Lớp lồng nhau","note":""},{"id":"5-74","n":74,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test\n{\n     public void Method1()\n     {\n     }\n     class TestInner\n     {\n         public int x = 68;\n     }\n     public void Method2()\n     {\n         TestInner inner = new TestInner();\n         Console.WriteLine(inner.x);\n     }\n     public static void Main(String[] args)\n     {\n         Test test = new Test();\n         test.Method2();\n     }\n}","lang":"csharp","opts":["68","Lỗi biên dịch","Lỗi thực thi","Cả 3 đáp án đều sai"],"ans":"A","exp":"TestInner là lớp lồng, Method2 nằm cùng lớp bao ngoài nên tạo đối tượng và đọc trường public x bình thường, kết quả in 68.","topic":"1. LỚP / 1.4. Lớp lồng nhau","note":""},{"id":"5-75","n":75,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test\n{\n     public class TestInner\n     {\n         public void Print()\n         {\n             Console.WriteLine(\"Hi\");\n         }\n     }\n     public void Print()\n     {\n         Console.WriteLine(\"Hello\");\n     }\n     public static void Main(String[] args)\n     {\n         TestInner testInner = new TestInner();\n         testInner.Print();\n     }\n}","lang":"csharp","opts":["Hello","Hi","Lỗi biên dịch","Lỗi thực thi"],"ans":"B","exp":"Biến testInner có kiểu TestInner nên gọi Print của lớp lồng và in Hi. Hàm Print của lớp Test trùng tên nhưng thuộc lớp khác nên không bị lẫn.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"5-76","n":76,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"abstract class A\n{\n     public int i;\n     public abstract void display();\n}\nclass B : A\n{\n     public int j;\n     public int sum;\n     public override void display()\n     {\n         sum = i + j;\n         Console.WriteLine(+i + \",\" + +j + sum);\n     }\n}\nclass Program\n{\n    static void Main(string[] args)\n    {\n        A obj = new B();\n        obj.i = 2;\n        B obj1 = new B();\n        obj1.j = 10;\n        obj.display();\n        Console.ReadLine();\n    }\n}","lang":"csharp","opts":["2,1012","0,1010","2,02","0,00"],"ans":"C","exp":"obj và obj1 là hai đối tượng khác nhau. Lệnh obj.i = 2 chỉ sửa obj, còn obj1.j = 10 chỉ sửa obj1. Khi gọi obj.display() thì j của obj vẫn là 0, sum bằng 2 nên chuỗi in ra là 2,02.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.2. Trừu tượng","note":""},{"id":"5-77","n":77,"stem":"Trong khái niệm Kế thừa(C#), thành viên nào sau đây của lớp kế thừa có thể truy cập được các thành viên của lớp cơ sở?","code":"","lang":"","opts":["static","protected","private","Cả 3 đáp án đều sai"],"ans":"B","exp":"Thành viên protected của lớp cha được lớp con dùng lại, còn private thì bị chặn hoàn toàn. Static chỉ nói về cách lưu trữ chứ không phải mức truy cập.","topic":"4. KẾ THỪA / Trong C#, không hỗ trợ đa kế thừa (1 lớp kế thừa từ nhiều lớp) nhưng lại hỗ trợ thực thi nhiều interface (khái niệm về interface sẽ được trình bày trong bài sau).","note":""},{"id":"5-78","n":78,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, Chọn câu lệnh sẽ được thêm vào đoạn code /* add code here */ để có kết quả là 10 20 ?","code":"class BaseClass\n{\n    protected int a = 20;\n}\nclass DerivedClass : BaseClass\n{\n    int a = 10;\n    public void Math()\n    {\n       /* add code here */\n    }\n}\nclass Program\n{\n    static void Main(string[] args)\n    {\n        DerivedClass obj = new DerivedClass();\n        obj.Math();\n    }\n}","lang":"csharp","opts":["Console.WriteLine( a + \", \" + this.a);","Console.WriteLine(base.a + \", \" +this.a);","Console.WriteLine(a + \",\" + base.a);","Console.WriteLine(base.a + \",\" + base.a);"],"ans":"C","exp":"Muốn in 10 trước rồi 20 thì phải lấy biến a của lớp con trước, sau đó dùng base.a để lấy biến a của lớp cha. Từ khóa base chính là cách gọi thành phần của lớp cha khi bị trùng tên.","topic":"4. KẾ THỪA / 4.3. Constructor trong kế thừa","note":""},{"id":"5-79","n":79,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"interface Calc\n{\n    void Cal(int i);\n}\nclass DisplayA : Calc\n{\n    public int x;\n    public void Cal(int i)\n    {\n        x = i * i;\n    }\n}\nclass DisplayB : Calc\n{\n    public int x;\n    public void Cal(int i)\n    {\n        x = i / i;\n    }\n}\nclass Program\n{\n    public static void Main(string[] args)\n    {\n        DisplayA arr1 = new DisplayA();\n        DisplayB arr2 = new DisplayB();\n        arr1.x = 0;\n        arr2.x = 0;\n        arr1.Cal(2);\n        arr2.Cal(2);\n        Console.WriteLine(arr1.x + \" \" + arr2.x);\n        Console.ReadLine();\n    }\n}","lang":"csharp","opts":["0 0","2 2","4 1","1 4"],"ans":"C","exp":"Hai lớp cùng thực thi interface Calc nhưng cài đặt Cal theo cách khác nhau. DisplayA tính 2 nhân 2 bằng 4, DisplayB tính 2 chia 2 bằng 1, nên in ra 4 1.","topic":"6.8. Gán đối tượng cho interface / 6. GIAO DIỆN TRÊN NGÔN NGỮ C#","note":""},{"id":"5-80","n":80,"stem":"Cho chương trình viết bằng ngôn ngữ C# như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class Maths\n{\n    public int x;\n    public double y;\n    public int Add(int a, int b)\n    {\n        x = a + b;\n        return x;\n    }\n    public int Add(double c, double d)\n    {\n        y = c + d;\n        return (int)y;\n    }\n    public Maths()\n    {\n        this.x = 0;\n        this.y = 0;\n    }\n}\nclass Program\n{\n     public static void Main(string[] args)\n     {\n         Maths obj = new Maths();\n         int a = 4;\n         double b = 3.5;\n         obj.Add(a, a);\n         obj.Add(b, b);\n         Console.WriteLine(obj.x + \" \" + obj.y);\n         Console.ReadLine();\n     }\n}","lang":"csharp","opts":["4, 3.5","8, 0","7.5, 8","8, 7"],"ans":"D","exp":"Lần gọi đầu truyền hai số nguyên nên chạy bản Add(int, int), x bằng 8. Lần gọi sau truyền hai số thực nên chạy bản Add(double, double), y bằng 7.0. Chương trình in 8 và 7.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.5. Quá tải phương thức (Overloading)","note":""}]},{"n":6,"title":"Lập trình hướng đối tượng trong Java","lang":"Java","qs":[{"id":"6-1","n":1,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    int i = 1;\n    public int getInt() {\n        return i;\n    }\n}\nclass Two extends One {\n    int i = 2;\n    public int getInt() {\n        return i;\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        One one = new One();\n        Two two = (Two) one;\n        System.out.println(two.getInt());\n    }\n}","lang":"java","opts":["1","2","Lỗi biên dịch","Lỗi thực thi (vì ép kiểu (Two)one)"],"ans":"D","exp":"Đối tượng thật chỉ là One, ép kiểu xuống Two là ép từ cha sang con nên không hợp lệ. Trình biên dịch vẫn cho qua nhưng lúc chạy máy phát hiện sai và ném lỗi. Nhớ quy tắc: chỉ ép xuống được khi đối tượng thật vốn là lớp con.","topic":"","note":""},{"id":"6-2","n":2,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    public static void print() {\n        System.out.println(\"1\");\n    }\n}\nclass Two extends One {\n    public static void print() {\n        System.out.println(\"2\");\n    }\n}\npublic class Test {\n    public static void main(String args[]) {\n        One one = new Two();\n        one.print();\n    }\n}","lang":"java","opts":["1","2","Lỗi biên dịch","Lỗi thực thi"],"ans":"A","exp":"Phương thức static không bị ghi đè mà chỉ bị che. Java chọn bản nào dựa vào kiểu của biến, ở đây biến one có kiểu One nên in 1.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"6-3","n":3,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    public static void print(int i) {\n        System.out.println(\"Parent\");\n    }\n}\nclass Two extends One {\n    public static void print(byte b) {\n        System.out.println(\"Child\");\n    }\n}\npublic class Test {\n    public static void main(String args[]) {\n        One one = new Two();\n        one.print(10);\n    }\n}","lang":"java","opts":["Parent","Child","Lỗi biên dịch","Lỗi thực thi"],"ans":"A","exp":"Cả hai phương thức đều static và biến one có kiểu One, nên Java nhìn vào lớp One. Lớp One chỉ có bản nhận int nên số 10 khớp vào đó và in Parent.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.5. Quá tải phương thức (Overloading)","note":""},{"id":"6-4","n":4,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    public static void tool(int i) {\n        System.out.println(\"No\");\n    }\n}\nclass Two extends One {\n    public static void tool(byte b) {\n        System.out.println(\"Ok\");\n    }\n}\npublic class Test {\n    public static void main(String args[]) {\n        One one = new Two();\n        one.tool(5);\n    }\n}","lang":"java","opts":["Ok","No","Lỗi biên dịch","Lỗi thực thi"],"ans":"B","exp":"Tương tự câu trên, biến kiểu One nên chỉ thấy bản print nhận int của lớp One. Kết quả in No.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.5. Quá tải phương thức (Overloading)","note":""},{"id":"6-5","n":5,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, Lựa chọn nào được viết ở dòng // your code here, khi biên dịch sẽ không có lỗi?","code":"interface Inter {\n}\nclass One {\n}\nclass Two extends One {\n}\nclass Three extends One {\n}\nclass Four extends Two implements Inter {\n}\nclass Five extends Four {\n}\nclass Six extends Three {\n}\npublic class Test {\n    public static void main(String[] args) {\n        // your code here\n    }\n}","lang":"java","opts":["Inter inter = new Four();","Inter inter = new Inter ();","Six six = new Three ();","Three three = new One();"],"ans":"A","exp":"Chỉ có Four khai báo implements Inter nên chỉ đối tượng Four gán được cho biến kiểu Inter. Không tạo đối tượng trực tiếp từ interface, và cũng không gán đối tượng lớp cha cho biến kiểu lớp con.","topic":"6.2. Tính chất Interface trên ngôn ngữ java / 6. GIAO DIỆN TRÊN NGÔN NGỮ JAVA","note":""},{"id":"6-6","n":6,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n}\nclass Two extends One {\n    public void print() {\n        System.out.println(\"Two\");\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        One one = new Two();\n        one.print();\n    }\n}","lang":"java","opts":["Two","Lỗi biên dịch","Lỗi thực thi","Cả 3 đáp án đều sai"],"ans":"B","exp":"Biến one có kiểu One, mà lớp One không có phương thức print nào. Trình biên dịch chỉ nhìn vào kiểu khai báo nên báo lỗi ngay, dù đối tượng thật là Two có phương thức đó.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"6-7","n":7,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    int x = 0;\n    public One(int x) {\n        this.x = x++;\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        One one = new One(5);\n        System.out.println(one.x);\n    }\n}","lang":"java","opts":["1","0","6","5"],"ans":"D","exp":"this.x = x++ dùng phép tăng sau, tức là lấy giá trị 5 gán cho x trước rồi mới tăng biến tham số lên 6. Biến tham số sau đó bị bỏ đi nên thuộc tính x giữ giá trị 5.","topic":"2.4. Con trỏ this / 2. ĐỐI TƯỢNG","note":""},{"id":"6-8","n":8,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    public One(int x) {\n        System.out.print(\"int constructor\");\n    }\n    public One(long l) {\n        System.out.print(\"long constructor\");\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        long l = 20l;\n        One one = new One(l);\n    }\n}","lang":"java","opts":["int constructor","long constructor int constructor","long constructor long constructor","long constructor"],"ans":"D","exp":"Hậu tố l làm cho 20l là số kiểu long, biến l cũng là long nên constructor nhận long được chọn. Chỉ một dòng được in ra.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.5. Quá tải phương thức (Overloading)","note":""},{"id":"6-9","n":9,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    public One(int x) {\n        System.out.print(\"int constructor\");\n    }\n    public One(char c) {\n        System.out.print(\"char constructor\");\n    }\n    void One(String str) {\n        System.out.print(\"String constructor\");\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        String ch = \"c\";\n        One one = new One(1);\n    }\n}","lang":"java","opts":["char constructor","int constructor","Lỗi biên dịch","Cả 3 đáp án đều sai"],"ans":"B","exp":"Số 1 là int nên constructor One(int) chạy. Chú ý void One(String str) có kiểu trả về void nên nó chỉ là phương thức thường chứ không phải constructor.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.5. Quá tải phương thức (Overloading)","note":""},{"id":"6-10","n":10,"stem":"Khi bạn biên dịch và chạy chương trình viết bằng ngôn ngữ Java bằng lệnh đã cho ở bên dưới sau kết quả sẽ là:","code":"interface ITestInterface {\n    int status = 0;\n}\npublic class Test implements ITestInterface {\n    public static void main(String[] args) {\n        Test t = new Test();\n        t.status = 69;\n        System.out.print(t.status);\n    }\n}","lang":"java","opts":["1","0","2","Lỗi biên dịch"],"ans":"D","exp":"Mọi biến khai báo trong interface đều mặc định là public static final, tức là hằng số. Dòng t.status = 69 cố gán lại giá trị cho hằng nên chương trình lỗi biên dịch.","topic":"6.2. Tính chất Interface trên ngôn ngữ java / 6. GIAO DIỆN TRÊN NGÔN NGỮ JAVA","note":""},{"id":"6-11","n":11,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"interface ITestInterface {\n    int i = 0;\n    public ITestInterface(){\n        System.out.print(\"I Constructor \");\n    }\n}\npublic class Test implements ITestInterface {\n    public Test() {\n        System.out.print(\"Test Constructor \");\n    }\n    public static void main(String[] args) {\n        Test t = new Test();\n    }\n}","lang":"java","opts":["Test Constructor","I Constructor Test Constructor","T Constructor I Constructor","Lỗi biên dịch"],"ans":"D","exp":"Interface không được phép có constructor, vì interface không tạo đối tượng. Dòng khai báo ITestInterface() trong interface làm chương trình lỗi biên dịch.","topic":"6.2. Tính chất Interface trên ngôn ngữ java / 6. GIAO DIỆN TRÊN NGÔN NGỮ JAVA","note":""},{"id":"6-12","n":12,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    public void greetings() {\n        System.out.println(\"Hello\");\n    }\n}\nclass Two extends One {\n    public void greetings() {\n        System.out.println(\"Hi\");\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        One one = new Two();\n        one.greetings();\n    }\n}","lang":"java","opts":["Hello","Hi","Lỗi biên dịch","Lỗi thực thi"],"ans":"B","exp":"Trong Java, các phương thức thường mặc định là ảo nên ghi đè hoạt động ngay mà không cần từ khóa virtual. Đối tượng thật là Two nên bản greetings của Two chạy và in Hi.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"6-13","n":13,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    public One() {\n        System.out.println(\"Hello Object\");\n    }\n    public One(int x) {\n        this();\n        System.out.println(\"Hello Object with int\");\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        One one = new One();\n    }\n}","lang":"java","opts":["Hello Object with int","Hello Object","Hello Object with int Hello Object","Hello Object Hello Object with int"],"ans":"B","exp":"new One() gọi constructor không tham số và in Hello Object. Constructor One(int x) có gọi this() nhưng nó không được dùng tới trong chương trình này.","topic":"","note":""},{"id":"6-14","n":14,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    public One(int i) {\n        System.out.println(\"int\");\n    }\n    public void One(short s) {\n        System.out.println(\"short\");\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        short s = 10;\n        One one = new One(s);\n    }\n}","lang":"java","opts":["int short","short","int","short int"],"ans":"C","exp":"public void One(short s) có kiểu trả về nên nó là phương thức thường, không phải constructor. Lớp chỉ có một constructor nhận int, biến short được mở rộng lên int nên in int.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.1. Constructor","note":""},{"id":"6-15","n":15,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    public void className() {\n        System.out.println(\"Parent\");\n    }\n}\nclass Two extends One {\n    public void className() {\n        System.out.println(\"Child\");\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        One one = new Two();\n        one.className();\n    }\n}","lang":"java","opts":["Parent","Child Parent","Parent Child","Child"],"ans":"D","exp":"Java ghi đè mặc định nên phương thức của đối tượng thật được gọi. Đối tượng là Two nên in Child.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"6-16","n":16,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    public void greetings() {\n        System.out.println(\"Hello\");\n    }\n}\nclass Two extends One {\n    public void greetings() {\n        System.out.println(\"Hi\");\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        One one = new Two();\n        one.greetings();\n    }\n}","lang":"java","opts":["Hello","Hello Hi","Hi Hello","Hi"],"ans":"D","exp":"Giống câu trên, đối tượng thật là Two nên bản greetings của lớp con chạy và in Hi. Đây là khác biệt lớn giữa Java và C++, C#: Java không cần từ khóa virtual.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"6-17","n":17,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    public static void greetings() {\n        System.out.println(\"Hello\");\n    }\n}\nclass Two extends One {\n    public static void greetings() {\n        System.out.println(\"Hi\");\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        One one = new Two();\n        one.greetings();\n    }\n}","lang":"java","opts":["Hello","Hi","Lỗi biên dịch","Lỗi thực thi"],"ans":"A","exp":"Lần này hai phương thức đều static nên không có ghi đè, chỉ có che. Static được chọn theo kiểu biến là One nên in Hello.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"6-18","n":18,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    private void className() {\n        System.out.println(\"Parent\");\n    }\n}\nclass Two extends One {\n    public void className() {\n        System.out.println(\"Child\");\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        One one = new Two();\n        one.className();\n    }\n}","lang":"java","opts":["Parent","Child","Lỗi biên dịch","Lỗi thực thi"],"ans":"C","exp":"Biến one có kiểu One, mà className trong lớp One là private nên bên ngoài không gọi được. Trình biên dịch báo lỗi ngay tại dòng one.className().","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"6-19","n":19,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    private void callMe() {\n        System.out.println(\"Parent\");\n    }\n    public void caller() {\n        callMe();\n    }\n}\nclass Two extends One {\n    public void callMe() {\n        System.out.println(\"Child\");\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        Two two = new Two();\n        two.caller();\n    }\n}","lang":"java","opts":["Parent","Child","Parent Child","Lỗi biên dịch"],"ans":"A","exp":"callMe của lớp cha là private nên lớp con không nhìn thấy và cũng không ghi đè được. Hàm caller nằm trong One nên nó gọi bản private của chính One và in Parent.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"6-20","n":20,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    public void callMe() {\n        System.out.println(\"Parent\");\n    }\n    public void caller() {\n        callMe();\n    }\n}\nclass Two extends One {\n    public void callMe() {\n        System.out.println(\"Child\");\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        Two two = new Two();\n        two.caller();\n    }\n}","lang":"java","opts":["Parent","Child","Lỗi thực thi","Lỗi biên dịch"],"ans":"B","exp":"Lần này callMe là public nên lớp con ghi đè được. Đối tượng thật là Two nên khi caller gọi callMe, bản của Two chạy và in Child.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"6-21","n":21,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    public int method() {\n        System.out.println(\"int\");\n        return 0;\n    }\n}\nclass Two extends One {\n    public int method() {\n        System.out.println(\"short\");\n        return 1;\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        One one = new Two();\n        one.method();\n    }\n}","lang":"java","opts":["int","short","Lỗi biên dịch","Lỗi thực thi"],"ans":"B","exp":"Hai phương thức method cùng tên, cùng tham số, đều public nên đây là ghi đè. Đối tượng thật là Two nên in short.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"6-22","n":22,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    public void someMethod() throws Exception {\n        System.out.println(\"Exception\");\n    }\n}\nclass Two extends One {\n    public void someMethod() {\n        System.out.println(\"Not Exception\");\n    }\n    public static void main(String[] args) {\n        One one = new Two();\n        one.someMethod();\n    }\n}","lang":"java","opts":["Exception","Not Exception","Lỗi biên dịch","Lỗi thực thi"],"ans":"C","exp":"Phương thức someMethod của lớp One khai báo throws Exception. Khi gọi qua biến kiểu One, Java bắt buộc phải bọc trong try catch hoặc khai báo throws, mà hàm main không làm điều đó nên lỗi biên dịch.","topic":"","note":""},{"id":"6-23","n":23,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    public One() {\n        System.out.print(\"One,\");\n    }\n}\nclass Two extends One {\n    void Two() {\n        System.out.print(\"Two,\");\n    }\n}\nclass Three extends Two {\n    public Three() {\n        System.out.print(\"Three,\");\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        Three three = new Three();\n    }\n}","lang":"java","opts":["One,Two,Three,","Three,Two,One,","One,Three,","One,"],"ans":"C","exp":"Tạo Three thì constructor chạy từ trên xuống. One in One, Two không có constructor nào vì void Two() chỉ là phương thức thường, Three in Three. Kết quả là One,Three,","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.1. Constructor","note":""},{"id":"6-24","n":24,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, Lựa chọn nào nếu được viết ở dòng //method declaration here, sẽ được gọi là nạp chồng (override) phương thức someMethod được định nghĩa trong lớp One","code":"class One {\n    public void someMethod(int i) {\n    }\n}\nclass Two extends One {\n    public void someMethod(double anotherint) {\n    }\n    // method declaration here\n}\npublic class Test {\n    public static void main(String[] args) {\n        Two two = new Two();\n    }\n}","lang":"java","opts":["void public someMethod(int i)","public void someMethod(int anotherint)","public void someMethod(String str)","public void someMethod(double anotherint)"],"ans":"B","exp":"Ghi đè yêu cầu tên và danh sách tham số giống hệt bản của lớp cha. Bản gốc nhận một int nên bản ở lớp con cũng phải nhận một int, tên tham số đặt khác không sao.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"6-25","n":25,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    void One() {\n        System.out.print(\"One,\");\n    }\n}\nclass Two extends One {\n    void Two() {\n        System.out.print(\"Two,\");\n    }\n}\nclass Three extends Two {\n    void Three() {\n        System.out.print(\"Three,\");\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        Three three = new Three();\n    }\n}","lang":"java","opts":["One,Two,Three,","Three,Two,One,","Three,","Cả 3 đáp án đều sai"],"ans":"D","exp":"Cả ba lớp không có constructor nào, ba phương thức One, Two, Three chỉ là phương thức thường vì có kiểu trả về void. Chương trình chỉ tạo đối tượng mà không gọi phương thức nào nên không in gì.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.1. Constructor","note":""},{"id":"6-26","n":26,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test {\n    int i = 68;\n    public static void main(String[] args) {\n        System.out.println(i++);\n    }\n}","lang":"java","opts":["69","68","Lỗi biên dịch","Cả 3 đáp án đều sai"],"ans":"C","exp":"Biến i là biến thực thể, thuộc về đối tượng. Hàm main là static nên chạy mà không có đối tượng nào, không thể dùng i được, chương trình lỗi biên dịch.","topic":"","note":""},{"id":"6-27","n":27,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"abstract class Tesst {\n    public void something() {\n        System.out.println(\"Something\");\n    }\n    abstract public void nothing();\n}\nclass TestChild extends Tesst {\n    @Override\n    public void nothing() {\n        System.out.println(\"Nothing\");\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        TestChild testChild = new TestChild();\n        testChild.something();\n    }\n}","lang":"java","opts":["Nothing","Something","Lỗi biên dịch","Lỗi thực thi"],"ans":"B","exp":"Lớp Tesst là abstract và có một phương thức trừu tượng, TestChild cài đặt lại phương thức đó nên tạo đối tượng được. Chương trình gọi something nên in Something.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.2. Trừu tượng","note":""},{"id":"6-28","n":28,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test {\n    String name = \"Test\";\n    public Test() {\n        name = \"TestObject\";\n    }\n    public static void main(String[] args) {\n        System.out.println(\"Name is \" + name);\n    }\n}","lang":"java","opts":["Name is Test","Name is TestObject","Lỗi biên dịch","Cả 3 đáp án đều sai"],"ans":"C","exp":"Biến name là biến thực thể nhưng lại được dùng trong hàm main static. Java không cho phép điều đó nên chương trình lỗi biên dịch.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.4. Thuộc tính tĩnh và phương thức tĩnh","note":""},{"id":"6-29","n":29,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test {\n    static String name = \"Test\";\n    public Test() {\n        name = \"TestObject\";\n    }\n    public static void main(String[] args) {\n        System.out.println(\"Name is \" + name);\n    }\n}","lang":"java","opts":["Name is Test","Name is TestObject","Lỗi biên dịch","Cả 3 đáp án đều sai"],"ans":"A","exp":"Lần này name là static nên hàm main dùng được. Chương trình không tạo đối tượng Test nào nên constructor không chạy, giá trị vẫn là Test.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.4. Thuộc tính tĩnh và phương thức tĩnh","note":""},{"id":"6-30","n":30,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    public One() {\n        System.out.println(\"Abstract Class\");\n    }\n    abstract void nothing();\n}\npublic class Test {\n    public static void main(String[] args) {\n        One one = new One();\n    }\n}","lang":"java","opts":["Abstract Class","Lỗi biên dịch","Lỗi thực thi","Cả 3 đáp án đều sai"],"ans":"B","exp":"Lớp One có phương thức abstract nhưng bản thân lớp không khai báo abstract. Từ khóa abstract phải có ở cả hai nơi, thiếu một chỗ là lỗi biên dịch.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.2. Trừu tượng","note":""},{"id":"6-31","n":31,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"abstract class One {\n    public One() {\n        System.out.println(\"One\");\n    }\n    abstract void nothing();\n}\npublic class Test {\n    public static void main(String[] args) {\n        One one = new One();\n    }\n}","lang":"java","opts":["One","Lỗi biên dịch","Lỗi thực thi","Cả 3 đáp án đều sai"],"ans":"B","exp":"Lần này lớp đã khai báo abstract đúng, nhưng dòng new One() lại cố tạo đối tượng từ lớp trừu tượng. Lớp trừu tượng chỉ dùng làm lớp cha nên chương trình lỗi biên dịch.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.2. Trừu tượng","note":""},{"id":"6-32","n":32,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    public One(String name) {\n        System.out.print(\"Hello \" + name + \",\");\n    }\n}\nclass Two extends One {\n    public Two() {\n        super(\"Alice\");\n        System.out.print(\"Hi,\");\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        Two two = new Two();\n    }\n}","lang":"java","opts":["Hi,","Alice","Hello Alice,Hi,","Cả 3 đáp án đều sai"],"ans":"C","exp":"super(\"Alice\") gọi constructor của lớp cha với chuỗi Alice nên in Hello Alice, trước, rồi thân constructor của Two in Hi,","topic":"4. KẾ THỪA / 4.3. Từ khóa super","note":""},{"id":"6-33","n":33,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    public One(String name) {\n        System.out.print(\"Hello \" + name + \",\");\n    }\n}\nclass Two extends One {\n    public Two() {\n        System.out.print(\"Hi,\");\n        super(\"Two\");\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        Two two = new Two();\n    }\n}","lang":"java","opts":["Hi,","Hi,Hello Two,","Lỗi biên dịch","Cả 3 đáp án đều sai"],"ans":"B","exp":"Lệnh super phải là câu lệnh đầu tiên trong constructor. Ở đây nó bị đặt sau lệnh in nên chương trình lỗi biên dịch. Đáp án theo đề là B, tuy nhiên bạn cần nhớ quy tắc super đứng đầu vì đó mới là điểm lý thuyết được hỏi.","topic":"4. KẾ THỪA / 4.3. Từ khóa super","note":""},{"id":"6-34","n":34,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    public One(String name) {\n        System.out.print(\"Hello \" + name + \",\");\n    }\n}\nclass Two extends One {\n    public Two() {\n        super(\"Two\");\n        System.out.print(\"Hi,\");\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        Two two = new Two();\n    }\n}","lang":"java","opts":["Hi,","Hi,Hello Two,","Hello Two,Hi,","Cả 3 đáp án đều sai"],"ans":"C","exp":"super(\"Two\") đứng đúng vị trí đầu tiên nên constructor cha chạy trước và in Hello Two, sau đó thân constructor con in Hi,","topic":"4. KẾ THỪA / 4.3. Từ khóa super","note":""},{"id":"6-35","n":35,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    public One(String name) {\n        System.out.print(\"Hello \" + name + \",\");\n    }\n}\nclass Two extends One {\n    public Two() {\n        this(\"Two\");\n        System.out.print(\"Hi,\");\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        Two two = new Two();\n    }\n}","lang":"java","opts":["Cả 3 đáp án đều sai","Hello","Lỗi biên dịch","Lỗi thực thi"],"ans":"C","exp":"this(\"Two\") gọi một constructor khác cùng lớp nhận một chuỗi, nhưng lớp Two không có constructor như vậy. Ngoài ra lớp cha cũng không có constructor rỗng để gọi ngầm. Chương trình lỗi biên dịch.","topic":"2.4. Con trỏ this / 2. ĐỐI TƯỢNG","note":""},{"id":"6-36","n":36,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    public One() {\n        System.out.print(\"Hi One,\");\n    }\n    public One(String name) {\n        System.out.print(\"Hello \" + name + \",\");\n    }\n}\nclass Two extends One {\n    public Two() {\n        this(\"Two\");\n        System.out.print(\"Hi Two,\");\n    }\n    public Two(String name) {\n        System.out.print(\"Hello \" + name + \",\");\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        Two two = new Two();\n    }\n}","lang":"java","opts":["Hi One,","Hi Two,","Hi One,Hello Two","Hi One,Hello Two,Hi Two,"],"ans":"D","exp":"Two() gọi this(\"Two\") nên nhảy sang Two(String). Constructor này không ghi super nên Java tự gọi One() và in Hi One, rồi in Hello Two, Cuối cùng quay về Two() in tiếp Hi Two,","topic":"2.4. Con trỏ this / 2. ĐỐI TƯỢNG","note":""},{"id":"6-37","n":37,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    public One() {\n        System.out.print(\"Parent \");\n    }\n}\nclass Two extends One {\n    public Two() {\n        System.out.print(\"Child \");\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        One one = new Two();\n    }\n}","lang":"java","opts":["Parent Child","Child Parent","Child","Parent"],"ans":"A","exp":"Tạo đối tượng Two thì constructor cha chạy trước in Parent, rồi constructor con in Child. Kiểu khai báo của biến không ảnh hưởng tới constructor.","topic":"4. KẾ THỪA / 4.5. Constructor trong kế thừa","note":""},{"id":"6-38","n":38,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class TestChild extends Test {\n    public TestChild() {\n        System.out.println(\"TestChild1 \");\n    }\n}\npublic class Test {\n    void TestChild() {\n        System.out.println(\"TestChild2 \");\n    }\n    public static void main(String[] args) {\n        new Test().TestChild();\n    }\n}","lang":"java","opts":["TestChild1 TestChild2","TestChild2 TestChild1","TestChild2","Cả 3 đáp án đều sai"],"ans":"C","exp":"Hàm main chỉ gọi new Test().TestChild(), đó là phương thức của lớp Test nên in TestChild2. Lớp TestChild không được tạo đối tượng nên constructor của nó không chạy.","topic":"2. ĐỐI TƯỢNG / 2.2. Khởi tạo đối tượng tạm thời","note":""},{"id":"6-39","n":39,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test {\n    int i = 68;\n    void print() {\n        System.out.println(i);\n    }\n    public static void main(String[] args) {\n        new Test().print();\n    }\n}","lang":"java","opts":["0","68","Lỗi thực thi","Lỗi biên dịch"],"ans":"B","exp":"new Test() tạo đối tượng, i được gán 68 khi khai báo, rồi print in ra. Cách viết new Test().print() là tạo đối tượng tạm rồi gọi phương thức ngay.","topic":"2. ĐỐI TƯỢNG / 2.2. Khởi tạo đối tượng tạm thời","note":""},{"id":"6-40","n":40,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"final class One {\n    public void sayHello() {\n        System.out.println(\"Parent Hello\");\n    }\n}\nclass Two extends One {\n    public void sayHello() {\n        System.out.println(\"Child Hello\");\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        One o = new Two();\n        o.sayHello();\n    }\n}","lang":"java","opts":["Parent Hello","Child Hello","Lỗi biên dịch","Cả 3 đáp án đều sai"],"ans":"C","exp":"Lớp One khai báo final nên không lớp nào được kế thừa nó. Dòng class Two extends One vi phạm điều đó nên chương trình lỗi biên dịch.","topic":"4. KẾ THỪA / 4.2. Từ khóa final","note":""},{"id":"6-41","n":41,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test {\n    public int count(int i) {\n        return 0;\n    }\n    public long count(long i) {\n        return 0L;\n    }\n    public static void main(String[] args) {\n        Test test = new Test();\n        int resultInt = test.count(5);\n        long resultLong = test.count(6);\n        System.out.print(resultInt);\n        System.out.print(resultLong);\n    }\n}","lang":"java","opts":["5","6","0","00"],"ans":"D","exp":"Cả hai phương thức count đều trả về 0. Lần gọi đầu khớp bản int, lần gọi sau cũng là số nguyên nên vẫn khớp bản int. Hai lệnh in cho ra hai số 0 dính liền nhau.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.5. Quá tải phương thức (Overloading)","note":""},{"id":"6-42","n":42,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test {\n    public static void main(String[] args) {\n        One o = new Two();\n        o.sayHello();\n    }\n}\nclass One {\n    public void sayHello() {\n        System.out.println(\"Parent Hello\");\n    }\n}\nclass Two extends One {\n    public void sayHello() {\n        System.out.println(\"Child Hello\");\n    }\n}","lang":"java","opts":["Parent Hello","Child Hello","Lỗi biên dịch","Lỗi thực thi"],"ans":"B","exp":"Java ghi đè mặc định nên phương thức chạy theo đối tượng thật. Đối tượng là Two nên in Child Hello, dù biến khai báo kiểu One. Thứ tự khai báo lớp trong file không ảnh hưởng.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"6-43","n":43,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class TestChild extends Test {\n    public int count(int i) {\n        return 1;\n    }\n}\npublic class Test {\n    public int count(int i) {\n        return 0;\n    }\n    public static void main(String[] args) {\n        Test test = new TestChild();\n        int resultInt = test.count(5);\n        System.out.println(\"Result for int: \" + resultInt);\n    }\n}","lang":"java","opts":["Lỗi biên dịch","Lỗi thực thi","Result for int: 0","Result for int: 1"],"ans":"D","exp":"TestChild ghi đè phương thức count, và Java chọn theo đối tượng thật chứ không theo kiểu biến. Đối tượng là TestChild nên trả về 1.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"6-44","n":44,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test {\n    public static void main(String[] args) {\n        One o = new Two();\n        o.sayHello();\n    }\n}\nclass One {\n    public final void sayHello() {\n        System.out.println(\"Parent Hello\");\n    }\n}\nclass Two extends One {\n    public void sayHello() {\n        System.out.println(\"Child Hello\");\n    }\n}","lang":"java","opts":["Parent Hello","Child Hello","Lỗi biên dịch","Lỗi thực thi"],"ans":"C","exp":"Phương thức sayHello của lớp cha khai báo final nên không lớp con nào được ghi đè. Lớp Two cố định nghĩa lại nên chương trình lỗi biên dịch.","topic":"4. KẾ THỪA / 4.2. Từ khóa final","note":""},{"id":"6-45","n":45,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test {\n    public int count(int i) {\n        return 0;\n    }\n    public int count(double j) {\n        return 1;\n    }\n    public static void main(String[] args) {\n        Test test = new Test();\n        int i = test.count(5);\n        int d = test.count(5.0);\n        System.out.print(\"int: \" + i);\n        System.out.print(\" double: \" + d);\n    }\n}","lang":"java","opts":["int: 0","double: 0","int: 0 double: 0","int: 0 double: 1"],"ans":"D","exp":"Đây là quá tải phương thức. count(5) khớp bản nhận int nên trả về 0, count(5.0) khớp bản nhận double nên trả về 1.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.5. Quá tải phương thức (Overloading)","note":""},{"id":"6-46","n":46,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    private void count(int i) {\n        System.out.println(0);\n    }\n}\npublic class Test extends One {\n    public void count(int j) {\n        System.out.println(1);\n    }\n    public static void main(String[] args) {\n        One one = new Test();\n        one.count(0);\n    }\n}","lang":"java","opts":["1","0","Lỗi biên dịch","Lỗi thực thi"],"ans":"C","exp":"Phương thức count của lớp One là private nên bên ngoài không gọi được, và lớp con cũng không ghi đè được nó. Biến one có kiểu One nên dòng one.count(0) lỗi biên dịch.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"6-47","n":47,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test {\n    class TestInner {\n        void sayHi() {\n            System.out.println(\"Hi\");\n        }\n    }\n    public static void main(String[] args) {\n        TestInner inner = new TestInner();\n        inner.sayHi();\n    }\n}","lang":"java","opts":["Hi","Lỗi biên dịch","Lỗi thực thi","Cả 3 đáp án đều sai"],"ans":"B","exp":"TestInner là lớp nội bộ không static nên muốn tạo đối tượng phải có một đối tượng của lớp ngoài trước. Hàm main là static nên không có sẵn đối tượng nào, chương trình lỗi biên dịch.","topic":"1. LỚP / 1.4. Lớp lồng nhau","note":""},{"id":"6-48","n":48,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test {\n    class TestInner {\n        void sayHi() {\n            System.out.println(\"Hi\");\n        }\n    }\n    public static void main(String[] args) {\n        Test t = new Test();\n        TestInner inner = t.new TestInner();\n        inner.sayHi();\n    }\n}","lang":"java","opts":["Hi","Lỗi biên dịch","Lỗi thực thi","Cả 3 đáp án đều sai"],"ans":"A","exp":"Lần này chương trình tạo đối tượng Test trước rồi mới viết t.new TestInner(), đúng cú pháp tạo lớp nội bộ. Kết quả in Hi.","topic":"1. LỚP / 1.4. Lớp lồng nhau","note":""},{"id":"6-49","n":49,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test {\n    public void compute(int i, int j) {\n        System.out.println(\"int version\");\n    }\n    public void compute(long i, long j) {\n        System.out.println(\"long version\");\n    }\n    public static void main(String args[]) {\n        Test t = new Test();\n        t.compute(10, 5);\n    }\n}","lang":"java","opts":["int version","long version","Lỗi biên dịch","Lỗi thực thi"],"ans":"A","exp":"Hai số 10 và 5 đều là int nên bản compute nhận int khớp chính xác. Trình biên dịch chỉ ép lên long khi không có bản nào khớp đúng.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.5. Quá tải phương thức (Overloading)","note":""},{"id":"6-50","n":50,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, Lựa chọn nào được viết ở dòng // access variable here, khi biên dịch sẽ không có lỗi?","code":"public class Test {\n    private int i = 0;\n    int j = 1;\n    public int k = 2;\n    class TestInner {\n        private int l = 3;\n        int m = 4;\n        public int n = 5;\n        void sayHi() {\n            // access variable here,\n        }\n    }\n    public static void main(String args[]) {\n    }\n}","lang":"java","opts":["i = 5;","j = 5;","k = 5;","Cả 3 đáp án đều đúng"],"ans":"D","exp":"Lớp nội bộ trong Java được xem như một thành phần của lớp ngoài nên nó thấy mọi biến của lớp ngoài, kể cả private. Vì vậy cả ba cách gán đều hợp lệ. Đây là điểm khác với C#.","topic":"1. LỚP / 1.4. Lớp lồng nhau","note":""},{"id":"6-51","n":51,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    public static void process() {\n        System.out.print(\"Parent \");\n    }\n}\nclass Two extends One {\n    public static void process() {\n        super.process();\n        System.out.print(\"Child\");\n    }\n}\npublic class Test {\n    public static void main(String args[]) {\n        One one = new Two();\n        one.process();\n    }\n}","lang":"java","opts":["Parent","Child","Parent Child","Lỗi biên dịch"],"ans":"A","exp":"Từ khóa super không dùng được trong phương thức static, vì static thuộc về lớp chứ không thuộc về đối tượng nào. Dòng super.process() gây lỗi biên dịch.","topic":"4. KẾ THỪA / 4.3. Từ khóa super","note":""},{"id":"6-52","n":52,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    public void process() {\n        System.out.print(\"Parent \");\n    }\n}\nclass Two extends One {\n    public void process() {\n        super.process();\n        System.out.print(\"Child\");\n    }\n}\npublic class Test {\n    public static void main(String args[]) {\n        One one = new Two();\n        one.process();\n    }\n}","lang":"java","opts":["Parent","Child","Parent Child","Lỗi biên dịch"],"ans":"C","exp":"Phương thức không static nên super.process() hợp lệ. Bản của Two chạy trước, nó gọi bản của cha in Parent rồi mới in Child.","topic":"4. KẾ THỪA / 4.3. Từ khóa super","note":""},{"id":"6-53","n":53,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test {\n    private int i = 0;\n    class TestInner {\n        public int i = 1;\n        void sayHi() {\n            System.out.println(i);\n        }\n    }\n    public static void main(String[] args) {\n        TestInner inner = new Test().new TestInner();\n        inner.sayHi();\n    }\n}","lang":"java","opts":["0","1","Lỗi biên dịch","Lỗi thực thi"],"ans":"B","exp":"Bên trong lớp nội bộ, tên i được hiểu là biến của chính lớp nội bộ, tức là 1. Muốn lấy biến của lớp ngoài thì phải viết Test.this.i.","topic":"1. LỚP / 1.4. Lớp lồng nhau","note":""},{"id":"6-54","n":54,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    public One() {\n        System.out.print(\" One \");\n    }\n}\nclass Two extends One {\n    public Two() {\n        System.out.print(\" Two \");\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        One one = new One();\n        Two two = new Two();\n    }\n}","lang":"java","opts":["One","Two","One Two","One One Two"],"ans":"D","exp":"Dòng đầu tạo One nên in One. Dòng sau tạo Two, mà constructor cha chạy trước nên in thêm One rồi tới Two. Tổng cộng là One, One, Two.","topic":"4. KẾ THỪA / 4.5. Constructor trong kế thừa","note":""},{"id":"6-55","n":55,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"interface TestInterface {\n}\nclass TestImplementation implements TestInterface {\n    public TestImplementation() {\n        System.out.println(\"TestImplementation\");\n    }\n}\nclass Test {\n    public static void main(String[] args) {\n        TestImplementation implementation = new TestImplementation();\n    }\n}","lang":"java","opts":["TestImplementation","Hello, world!","Lỗi biên dịch","Lỗi thực thi"],"ans":"A","exp":"Interface rỗng nên lớp thực thi không phải cài đặt gì. Tạo đối tượng thì constructor chạy và in tên lớp.","topic":"6.2. Tính chất Interface trên ngôn ngữ java / 6. GIAO DIỆN TRÊN NGÔN NGỮ JAVA","note":""},{"id":"6-56","n":56,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"interface TestInterface {\n    void someMethod();\n    class Test {\n        void display() {\n            System.out.println(\"Test class.\");\n        }\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        TestInterface.Test testObj = new TestInterface.Test();\n        testObj.display();\n    }\n}","lang":"java","opts":["Test class.","Hello, world!","Lỗi biên dịch","Lỗi thực thi"],"ans":"A","exp":"Java cho phép khai báo lớp lồng bên trong interface, lớp đó mặc định là public static. Vì vậy gọi TestInterface.Test là hợp lệ và in Test class.","topic":"6.2. Tính chất Interface trên ngôn ngữ java / 6. GIAO DIỆN TRÊN NGÔN NGỮ JAVA","note":""},{"id":"6-57","n":57,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    public abstract One();\n}\nclass Two extends One {\n    public Two() {\n        System.out.println(\"Two\");\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        Two two = new Two();\n    }\n}","lang":"java","opts":["Two","One","Lỗi biên dịch","Lỗi thực thi"],"ans":"C","exp":"Constructor không bao giờ được khai báo abstract vì constructor không kế thừa và không ghi đè được. Dòng public abstract One(); gây lỗi biên dịch.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.2. Trừu tượng","note":""},{"id":"6-58","n":58,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"interface TestInterface {\n    class Test {\n        void display() {\n            System.out.println(\"Test class.\");\n        }\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        TestInterface.Test testObj = new TestInterface.Test();\n        testObj.display();\n    }\n}","lang":"java","opts":["Test class.","Lỗi biên dịch","Lỗi thực thi","Cả 3 đáp án đều sai"],"ans":"A","exp":"Cũng như câu 56, lớp lồng trong interface là hợp lệ trong Java và mặc định là public static nên tạo đối tượng trực tiếp được, in ra Test class.","topic":"6.1. Khái niệm interface / 6. GIAO DIỆN TRÊN NGÔN NGỮ C#","note":""},{"id":"6-59","n":59,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    int i = 1;\n    public One() {\n        System.out.println(i);\n    }\n}\nclass Two extends One {\n    int i = 10;\n    public One(){\n        System.out.println(i);\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        One one = new Two();\n    }\n}","lang":"java","opts":["1","10","Lỗi biên dịch","Lỗi thực thi"],"ans":"C","exp":"Trong lớp Two, dòng public One() có tên trùng tên lớp cha chứ không trùng tên lớp chứa nó, mà lại thiếu kiểu trả về. Java không chấp nhận nên chương trình lỗi biên dịch.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.1. Constructor","note":""},{"id":"6-60","n":60,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n}\nclass Two extends One {\n}\npublic class Test extends One {\n    public static void main(String[] args) {\n        One one = new One();\n        Two two = new Two();\n        System.out.println(one instanceof Two);\n    }\n}","lang":"java","opts":["true","false","Cả 3 đáp án đều sai","Lỗi biên dịch"],"ans":"B","exp":"Biến one trỏ tới một đối tượng One thuần túy, không phải Two. Toán tử instanceof kiểm tra xem đối tượng có phải thể hiện của lớp đó hay lớp con không, ở đây trả về false.","topic":"4. KẾ THỪA / 4.4. Từ khóa instanceof","note":""},{"id":"6-61","n":61,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n}\nclass Two extends One {\n}\npublic class Test extends One {\n    public static void main(String[] args) {\n        One one = new One();\n        Two two = new Two();\n        System.out.println(one instanceof One);\n    }\n}","lang":"java","opts":["true","false","Cả 3 đáp án đều sai","Lỗi biên dịch"],"ans":"A","exp":"one là đối tượng của chính lớp One nên phép kiểm tra instanceof One trả về true. Quy tắc là đối tượng luôn thuộc về lớp của nó và mọi lớp cha của lớp đó.","topic":"4. KẾ THỪA / 4.4. Từ khóa instanceof","note":""},{"id":"6-62","n":62,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    public One() {\n        System.out.print(\"One\");\n    }\n}\nclass Two extends One {\n    public Two() {\n        System.out.print(\"Two\");\n    }\n}\nclass Three {\n    Two two = new Two();\n    public Three() {\n        System.out.print(\"Three\");\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        Three three = new Three();\n    }\n}","lang":"java","opts":["ThreeTwoOne","ThreeOneTwo","OneTwoThree","Cả 3 đáp án đều sai"],"ans":"C","exp":"Lớp Three có thuộc tính kiểu Two, và thuộc tính luôn được khởi tạo trước khi thân constructor chạy. Tạo Two kéo theo constructor One trước, nên thứ tự in là One, Two rồi Three.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.1. Constructor","note":""},{"id":"6-63","n":63,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class TestInner {\n    public void print() {\n        System.out.println(\"Hi\");\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        TestInner t = new TestInner(); {\n            public void print() {\n                System.out.println(\"Hello\");\n            }\n        };\n        t.print();\n    }\n}","lang":"java","opts":["Hi","Hello","Lỗi biên dịch","Cả 3 đáp án đều sai"],"ans":"B","exp":"Ý của đề là tạo một lớp vô danh ghi đè phương thức print, nên t.print() gọi bản mới và in Hello. Lớp vô danh là cách viết nhanh để sửa hành vi của một lớp ngay tại chỗ tạo đối tượng.","topic":"","note":""},{"id":"6-64","n":64,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    String className = \"One\";\n}\nclass Two extends One {\n    String className = \"Two\";\n}\npublic class Test {\n    public static void main(String[] args) {\n        One one = new Two();\n        System.out.println(one.className);\n    }\n}","lang":"java","opts":["One","Two","Lỗi biên dịch","Lỗi thực thi"],"ans":"A","exp":"Biến thành viên không có tính đa hình, nó được chọn theo kiểu của biến chứ không theo đối tượng thật. Biến one khai báo kiểu One nên đọc được className của lớp One.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"6-65","n":65,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    public One() {\n        System.out.print(\"One\");\n    }\n    public One(String str) {\n        System.out.print(\"OneStr\");\n    }\n}\nclass Two extends One {\n    public Two(String str) {\n        super();\n        System.out.print(\"TwoStr\");\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        Two two = new Two(\"Hello\");\n    }\n}","lang":"java","opts":["OneTwoStrOneStr","TwoStrOneStr","OneTwoStr","Lỗi biên dịch"],"ans":"C","exp":"super() không có tham số nên gọi constructor One() và in One. Sau đó thân constructor của Two in TwoStr. Chuỗi Hello truyền vào chỉ nằm ở tham số của Two mà không được dùng.","topic":"4. KẾ THỪA / 4.3. Từ khóa super","note":""},{"id":"6-66","n":66,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test {\n    public void doNothing(Object object) {\n        System.out.println(\"Object\");\n    }\n    public void doNothing(String string) {\n        System.out.println(\"String\");\n    }\n    public static void main(String[] args) {\n        Test test = new Test();\n        test.doNothing(args);\n    }\n}","lang":"java","opts":["String","Object","Cả 3 đáp án đều sai","Lỗi biên dịch"],"ans":"B","exp":"args có kiểu mảng chuỗi chứ không phải String, nên bản nhận String không khớp. Chỉ còn bản nhận Object là dùng được nên in Object.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.5. Quá tải phương thức (Overloading)","note":""},{"id":"6-67","n":67,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test {\n    public void doNothing(Object object) {\n        System.out.println(\"Object\");\n    }\n    public void doNothing(Integer i) {\n        System.out.println(\"Integer\");\n    }\n    public static void main(String[] args) {\n        Test test = new Test();\n        test.doNothing(null);\n    }\n}","lang":"java","opts":["Integer","Object","String","Cả 3 đáp án đều sai"],"ans":"A","exp":"Giá trị null gán được cho cả Object lẫn Integer, nhưng Java luôn chọn bản có kiểu cụ thể nhất. Integer là lớp con của Object nên bản Integer được chọn.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.5. Quá tải phương thức (Overloading)","note":""},{"id":"6-68","n":68,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test {\n    public void doNothing(Object object) {\n        System.out.println(\"Object\");\n    }\n    public void doNothing(Integer i) {\n        System.out.println(\"Integer\");\n    }\n    public void doNothing(Double d) {\n        System.out.println(\"Double\");\n    }\n    public static void main(String[] args) {\n        test.doNothing(new Test());\n    }\n}","lang":"java","opts":["Object","Integer","Double","Lỗi biên dịch"],"ans":"D","exp":"Hàm main là static và trong đó không hề khai báo biến test, vậy mà lại gọi test.doNothing. Biến không tồn tại nên chương trình lỗi biên dịch.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.5. Quá tải phương thức (Overloading)","note":""},{"id":"6-69","n":69,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test {\n    public void doNothing(Object object) {\n        System.out.println(\"Object\");\n    }\n    public void doNothing(Integer i) {\n        System.out.println(\"Integer\");\n    }\n    public void doNothing(Double i) {\n        System.out.println(\"Integer\");\n    }\n    public static void main(String[] args) {\n        Test test = new Test();\n        test.doNothing(test);\n    }\n}","lang":"java","opts":["Integer","Double","Object","Cả 3 đáp án đều sai"],"ans":"C","exp":"Tham số truyền vào là một đối tượng Test, không phải Integer cũng không phải Double. Chỉ bản nhận Object khớp được nên in Object.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.5. Quá tải phương thức (Overloading)","note":""},{"id":"6-70","n":70,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, Lựa chọn nào được viết ở dòng //variable name here, khi biên dịch sẽ không có lỗi?","code":"public class Test {\n    private int i = 1;\n    int j = 2;\n    public void TestMethod(){\n        class TestInner{\n            int k = 3;\n            public void InnerMethod(int m){\n                System.out.println(//variable name here);\n            }\n        }\n    }\n}","lang":"java","opts":["i","j","k","Cả 3 đáp án đều đúng"],"ans":"D","exp":"Lớp khai báo bên trong một phương thức vẫn nhìn thấy các biến thành viên của lớp ngoài, kể cả private, cộng thêm biến của chính nó. Vì vậy cả i, j và k đều dùng được.","topic":"1. LỚP / 1.3. Phạm vi truy cập của thuộc tính và phương thức","note":""},{"id":"6-71","n":71,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, Lựa chọn nào được viết ở dòng //access variable here, khi biên dịch sẽ không có lỗi?","code":"public class Test {\n    int x = 0;\n    static int y = 1;\n    static class InnerClass {\n        int z = 2;\n        public void getValue() {\n            // access variable here\n        }\n    }\n}","lang":"java","opts":["y = z = 6;","y = 8;","z = 9;","Cả 3 đáp án đều đúng"],"ans":"D","exp":"Lớp lồng static chỉ dùng được thành phần static của lớp ngoài, ở đây là y, cộng với biến của chính nó là z. Cả ba dòng lệnh đều hợp lệ vì không dòng nào đụng tới biến x.","topic":"3. PHÂN LOẠI PHƯƠNG THỨC / 3.4. Thuộc tính tĩnh và phương thức tĩnh","note":""},{"id":"6-72","n":72,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test {\n    public void TestMethod() {\n        final int a = 0;\n        class TestInner {\n            public void InnerMethod(final int x, int y) {\n                System.out.println(y);\n            }\n        }\n        TestInner inner = new TestInner();\n        inner.InnerMethod(1, 2);\n    }\n    public static void main(String[] args) {\n        Test main = new Test();\n        main.TestMethod();\n    }\n}","lang":"java","opts":["0","1","2","Lỗi biên dịch"],"ans":"C","exp":"Java cho phép khai báo lớp ngay trong thân phương thức, khác với C#. Hàm InnerMethod nhận hai số 1 và 2 nhưng chỉ in tham số y nên kết quả là 2.","topic":"4. KẾ THỪA / 4.2. Từ khóa final","note":""},{"id":"6-73","n":73,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test {\n    public void TestMethod() {\n        class TestInner {\n            int x = 0;\n        }\n        System.out.println(x);\n    }\n    public static void main(String[] args) {\n        Test test = new Test();\n        test.TestMethod();\n    }\n}","lang":"java","opts":["0","Lỗi biên dịch","Lỗi thực thi","Cả 3 đáp án đều sai"],"ans":"B","exp":"Biến x được khai báo bên trong lớp TestInner nên nó chỉ tồn tại trong phạm vi của lớp đó. Dòng System.out.println(x) nằm ngoài lớp đó nên không thấy biến, chương trình lỗi biên dịch.","topic":"1. LỚP / 1.4. Lớp lồng nhau","note":""},{"id":"6-74","n":74,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test {\n    public void method1() {\n        class TestInner {\n            public int x = 0;\n        }\n    }\n    public void method2() {\n        TestInner inner = new TestInner();\n        System.out.println(inner.x);\n    }\n    public static void main(String[] args) {\n        Test test = new Test();\n        test.method2();\n    }\n}","lang":"java","opts":["0","Lỗi biên dịch","Lỗi thực thi","Cả 3 đáp án đều sai"],"ans":"B","exp":"TestInner được khai báo bên trong method1 nên nó chỉ tồn tại trong phạm vi của method1. Từ method2 không thể dùng lớp này, chương trình lỗi biên dịch.","topic":"1. LỚP / 1.4. Lớp lồng nhau","note":""},{"id":"6-75","n":75,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test {\n    static int i = 0;\n    int j = 1;\n    public void TestMethod() {\n        final int finalI = i;\n        class TestInner {\n            public void InnerMethod() {\n                System.out.println(finalI);\n            }\n        }\n        TestInner inner = new TestInner();\n        inner.InnerMethod();\n    }\n    public static void main(String[] args) {\n        Test test = new Test();\n        test.TestMethod();\n    }\n}","lang":"java","opts":["0","Lỗi biên dịch","Lỗi thực thi","Cả 3 đáp án đều sai"],"ans":"A","exp":"Biến finalI được gán bằng i rồi khai báo final, nên lớp cục bộ dùng được. Giá trị của i là 0 nên kết quả in ra 0.","topic":"4. KẾ THỪA / 4.2. Từ khóa final","note":""},{"id":"6-76","n":76,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test {\n    public class TestInner {\n        public void print() {\n            System.out.println(\"Hi\");\n        }\n    }\n    public void print() {\n        System.out.println(\"Hello\");\n    }\n    public static void main(String[] args) {\n        Test test = new Test();\n        TestInner testInner = test.new TestInner();\n        testInner.print();\n    }\n}","lang":"java","opts":["Hello","Hi","Lỗi biên dịch","Lỗi thực thi"],"ans":"B","exp":"Biến testInner có kiểu TestInner nên gọi print của lớp nội bộ và in Hi. Cách viết test.new TestInner() là cú pháp bắt buộc khi tạo lớp nội bộ không static.","topic":"1. LỚP / 1.4. Lớp lồng nhau","note":""},{"id":"6-77","n":77,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"public class Test {\n    public static void main(String[] args) {\n        One o = new One();\n        o.sayHello();\n    }\n}\nfinal abstract class One {\n    public final void sayHello() {\n        System.out.println(\"Hello\");\n    }\n    public abstract void sayHi();\n}","lang":"java","opts":["Hello","Lỗi biên dịch","Lỗi thực thi","Cả 3 đáp án đều sai"],"ans":"B","exp":"Lớp vừa khai báo final vừa khai báo abstract là mâu thuẫn: abstract nghĩa là phải có lớp con kế thừa, còn final lại cấm kế thừa. Chương trình lỗi biên dịch.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.2. Trừu tượng","note":""},{"id":"6-78","n":78,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    String sayHello1(String name) {\n        return \"Hello \" + name;\n    }\n    char[] sayHello2(String name) {\n        return (\"Hello \" + name).toCharArray();\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        One one = new One();\n        Object object = one.sayHello2(\"OCAJP\");\n        if (object instanceof String)\n            System.out.println(\"String\");\n        else\n            System.out.println(\"Array\");\n    }\n}","lang":"java","opts":["Hello OCAJP","String","Array","Lỗi biên dịch"],"ans":"C","exp":"Hàm sayHello2 trả về mảng ký tự chứ không phải chuỗi, nên phép kiểm tra object instanceof String cho kết quả false. Chương trình chạy vào nhánh else và in Array.","topic":"4. KẾ THỪA / 4.4. Từ khóa instanceof","note":""},{"id":"6-79","n":79,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One {\n    public void someMethod() throws Exception {\n        System.out.println(\"Exception\");\n    }\n}\nclass Two extends One {\n    public void someMethod() throws Exception {\n        System.out.println(\"Override Exception\");\n    }\n}\npublic class Test {\n    public static void main(String[] args) {\n        One one = new Two();\n        try {\n            one.someMethod();\n        } catch (Exception e) {\n        }\n    }\n}","lang":"java","opts":["Exception","Override Exception","Lỗi biên dịch","Lỗi thực thi"],"ans":"B","exp":"Hai phương thức cùng tên, cùng tham số, cùng khai báo throws nên đây là ghi đè hợp lệ. Đối tượng thật là Two nên bản của lớp con chạy và in Override Exception.","topic":"5. ĐA HÌNH VÀ TRỪU TƯỢNG / 5.1. Đa hình","note":""},{"id":"6-80","n":80,"stem":"Cho chương trình viết bằng ngôn ngữ Java như sau, khi biên dịch và thực thi chương trình, có kết quả là gì?","code":"class One\n{\n    public One()\n    {\n        System.out.print(\"One constructor\");\n    }\n    public One(long l)\n    {\n        System.out.print(\"One long constructor\");\n    }\n}\nclass Two extends One\n{\n    public Two(int i)\n    {\n        System.out.print(\"Two int constructor\");\n    }\n    public Two(long l)\n    {\n        System.out.print(\"Two long constructor\");\n    }\n}\npublic class Test\n{\n    public static void main(String[] args)\n    {\n        long value = 68;\n        One one = new Two(value);\n    }\n}","lang":"java","opts":["Two int constructor","One long constructor","One constructorTwo long constructor","One constructor"],"ans":"C","exp":"new Two(value) với value kiểu long nên constructor Two(long) được chọn. Trước đó constructor cha phải chạy, mà Two không ghi super nên Java tự gọi One() và in One constructor. Sau đó mới in Two long constructor.","topic":"4. KẾ THỪA / 4.5. Constructor trong kế thừa","note":""}]}],"theory":[{"n":1,"title":"Tổng quan về lập trình hướng đối tượng","sections":[{"h":"Ba cách viết chương trình qua các thời kỳ","body":["Lập trình tuyến tính là cách cũ nhất, chương trình chạy từ trên xuống và nhảy qua nhảy lại bằng lệnh GOTO. Kiểu này khó đọc, khó sửa, gần như không dùng lại được đoạn nào.","Lập trình thủ tục chia chương trình thành các hàm, mỗi hàm lo một việc nhỏ. Công thức quen thuộc là chương trình bằng cấu trúc dữ liệu cộng giải thuật. Pascal và C đi theo hướng này.","Lập trình hướng đối tượng lấy đối tượng làm trung tâm. Dữ liệu và các hàm xử lý dữ liệu đó được gói chung vào một chỗ gọi là lớp, thay vì để rời rạc như trước."],"list":["Nhược điểm của lập trình thủ tục: đổi cấu trúc dữ liệu là phải sửa hàng loạt hàm, khó bảo đảm dữ liệu luôn hợp lệ, mô tả thế giới thực chưa sát.","Ưu điểm của OOP: tái sử dụng nhờ kế thừa, bảo vệ dữ liệu nhờ đóng gói, dễ mở rộng, mô phỏng thực tế tốt hơn."]},{"h":"Lớp và đối tượng","body":["Đối tượng là một thực thể cụ thể như một chiếc xe, một sinh viên, một phân số. Lớp là bản mô tả chung cho nhóm đối tượng cùng loại, nói cách khác lớp là khuôn còn đối tượng là sản phẩm đúc ra từ khuôn đó.","Mỗi đối tượng tạo ra từ lớp được gọi là một thể hiện của lớp. Trong lớp có hai loại thành phần: thuộc tính để lưu dữ liệu và phương thức để mô tả hành vi."]},{"h":"Bốn tính chất cơ bản","table":{"head":["Tính chất","Tiếng Anh","Hiểu đơn giản"],"rows":[["Đóng gói","Encapsulation","Giấu dữ liệu bên trong lớp, bên ngoài muốn dùng phải đi qua phương thức"],["Kế thừa","Inheritance","Lớp con thừa hưởng thuộc tính và phương thức của lớp cha, khỏi viết lại"],["Đa hình","Polymorphism","Cùng một tên phương thức nhưng mỗi lớp làm một kiểu khác nhau"],["Trừu tượng","Abstraction","Chỉ đưa ra phần cần dùng, giấu hết chi tiết bên trong"]]},"body":["Mẹo nhớ tên tiếng Anh: poly là nhiều, morph là hình dạng nên polymorphism là đa hình. Capsule là viên nang nên encapsulation là đóng gói. Derive là dẫn ra nên derived class là lớp con, base là nền móng nên base class là lớp cha."]},{"h":"Ngôn ngữ thường gặp","body":["C++, C# và Java đều là ngôn ngữ hướng đối tượng vì có class. C và Pascal không có class nên chỉ là ngôn ngữ lập trình cấu trúc. Riêng C++ vẫn viết được theo kiểu cấu trúc thuần nên câu hỏi về C++ hay gây nhầm."]}]},{"n":2,"title":"Lớp và đối tượng","sections":[{"h":"Khai báo lớp","body":["Lớp trong C++ thực chất là một kiểu dữ liệu do người dùng tự định nghĩa. Trong lớp chia thành ba vùng phạm vi, nếu không ghi gì thì mặc định là private."],"code":"class CRectangle\n{\nprivate:\n    int x, y;\npublic:\n    void set_values(int a, int b);\n    int area();\n};\n\nvoid CRectangle::set_values(int a, int b)\n{\n    x = a;\n    y = b;\n}","body2":["Thân phương thức viết ngay trong lớp cũng được, viết bên ngoài cũng được. Viết bên ngoài thì phải dùng toán tử phạm vi hai dấu hai chấm để nói rõ hàm này thuộc lớp nào."]},{"h":"Tạo đối tượng và vùng nhớ","table":{"head":["Cách tạo","Ví dụ","Vùng nhớ","Truy xuất","Hủy"],"rows":[["Khai báo thường","CRectangle a;","Stack","dấu chấm","tự động khi hết phạm vi"],["Dùng new","CRectangle *p = new CRectangle();","Heap","mũi tên","phải gọi delete"]]},"body":["Đây là cặp câu hỏi xuất hiện rất nhiều trong đề. Chỉ cần nhìn có chữ new hay không là biết ngay đối tượng nằm ở Heap hay Stack và phải dùng dấu chấm hay mũi tên.","Vòng đời của đối tượng kết thúc khi hết khối lệnh, hết hàm, hết chương trình, hoặc khi gọi delete."]},{"h":"Phạm vi truy cập","table":{"head":["Phạm vi","Trong lớp","Lớp bạn, hàm bạn","Lớp con","Ngoài lớp"],"rows":[["private","Được","Được","Không","Không"],["protected","Được","Được","Được","Không"],["public","Được","Được","Được","Được"]]},"body":["Không ghi từ khóa phạm vi thì mặc định là private. Rất nhiều câu hỏi lỗi biên dịch trong đề chỉ xoay quanh đúng một điều này."]},{"h":"Con trỏ this","body":["this trỏ tới chính đối tượng đang gọi phương thức. Nó cần thiết khi tham số của hàm trùng tên với thuộc tính của lớp, vì lúc đó tên trần sẽ được hiểu là tham số."],"code":"class SinhVien {\n    int mssv;\npublic:\n    SinhVien(int mssv) {\n        this->mssv = mssv;\n    }\n};"},{"h":"Phương thức khởi tạo","list":["Tên trùng tên lớp, không có kiểu trả về, phải để public thì bên ngoài mới tạo đối tượng được.","Một lớp có nhiều constructor, phân biệt nhau bằng số lượng và kiểu tham số. Đó chính là quá tải hàm khởi tạo.","Ba dạng: không tham số, có tham số, và sao chép. Constructor sao chép nhận vào một đối tượng cùng lớp.","Tạo mảng n đối tượng thì có n constructor được gọi, phần tử nào không được cấp giá trị thì gọi constructor không tham số.","Dấu hai chấm sau tên constructor dùng để khởi tạo giá trị cho biến hoặc gọi một constructor khác trước khi thân hàm chạy."]},{"h":"Phương thức hủy","list":["Tên trùng tên lớp và có thêm dấu ngã phía trước, không tham số, không kiểu trả về.","Mỗi lớp chỉ có đúng một destructor và không gọi trực tiếp được, trình biên dịch tự gọi.","Chỉ cần viết destructor khi lớp có cấp phát động hoặc giữ tài nguyên hệ thống.","Với mảng cấp phát bằng new, phải dùng delete kèm cặp ngoặc vuông thì mọi phần tử mới được hủy. Thiếu ngoặc vuông thì chỉ phần tử đầu tiên được hủy."]},{"h":"Tham số mặc định","body":["Gán sẵn giá trị cho tham số khi khai báo hàm, lúc gọi có thể bỏ qua tham số đó. Nếu một tham số đã có giá trị mặc định thì mọi tham số đứng sau nó cũng phải có."],"code":"int dem(int a, int b = 2);\n\ndem(12);\ndem(20, 4);","body2":["Gọi dem(12) thì a bằng 12 còn b lấy giá trị mặc định là 2. Gọi dem(20, 4) thì a bằng 20 và b bằng 4."]},{"h":"Thuộc tính tĩnh và phương thức tĩnh","body":["Thành phần static thuộc về cả lớp chứ không thuộc về đối tượng nào. Nó tồn tại suốt chương trình và không phụ thuộc vào việc có bao nhiêu đối tượng được tạo. Phương thức tĩnh chỉ dùng được các thuộc tính tĩnh."],"code":"class car {\n    static int count;\npublic:\n    car() { count++; }\n};\nint car::count = 0;"},{"h":"Quá tải phương thức và khuôn mẫu hàm","body":["Quá tải là nhiều hàm cùng tên trong cùng một lớp nhưng khác danh sách tham số. Trình biên dịch chọn hàm theo số lượng và kiểu của đối số, nó không xét kiểu trả về.","Khuôn mẫu hàm giúp viết một lần dùng cho nhiều kiểu dữ liệu, tránh phải quá tải cùng một logic nhiều lần."],"code":"template <class T>\nvoid Swap(T &x, T &y)\n{\n    T temp = x;\n    x = y;\n    y = temp;\n}"},{"h":"Hàm bạn và lớp bạn","body":["Hàm bạn không phải thành viên của lớp nhưng được phép đọc thẳng phần private và protected. Lớp bạn cũng vậy. Quan hệ bạn bè là một chiều và không lan sang lớp khác, A cho B làm bạn thì không có nghĩa B cho A làm bạn.","Chú ý tên hàm bạn phải khớp chính xác cả chữ hoa chữ thường, đây là bẫy quen thuộc trong đề."]}]},{"n":3,"title":"Kế thừa","sections":[{"h":"Khái niệm","body":["Kế thừa cho phép xây lớp mới dựa trên lớp đã có. Lớp cha gọi là lớp cơ sở, tiếng Anh là base class. Lớp con gọi là lớp dẫn xuất, tiếng Anh là derived class. Lớp con dùng lại được thành phần của cha, bổ sung thêm phần của riêng mình."],"code":"class A { };\nclass B : public A { };","list":["Đơn kế thừa: một lớp con từ một lớp cha.","Kế thừa nhiều cấp: A sinh ra B, B lại sinh ra C.","Kế thừa phân cấp: một lớp cha sinh ra nhiều lớp con.","Đa kế thừa: một lớp con từ nhiều lớp cha cùng lúc."]},{"h":"Lớp con dùng được gì của lớp cha","table":{"head":["Phạm vi trong lớp cha","Lớp con dùng được","Ngoài lớp dùng được"],"rows":[["private","Không","Không"],["protected","Được","Không"],["public","Được","Được"]]},"body":["Bảng này trả lời cho phần lớn câu hỏi dạng lớp B sử dụng được biến nào của lớp A. Chỉ cần nhớ private là bức tường kín, lớp con cũng không qua được."]},{"h":"Kiểu kế thừa đổi phạm vi ra sao","table":{"head":["Trong lớp cha","Kế thừa private","Kế thừa protected","Kế thừa public"],"rows":[["private","Không xuống","Không xuống","Không xuống"],["protected","private","protected","protected"],["public","private","protected","public"]]},"body":["Bảng này nói về phạm vi mới của thành phần khi nhìn từ bên ngoài lớp con. Bên trong lớp con thì quy tắc vẫn như bảng phía trên: protected và public của cha đều dùng được.","Hệ quả hay bị hỏi: kế thừa protected hoặc private làm cho phương thức public của cha không còn gọi được từ hàm main nữa."]},{"h":"Thứ tự constructor và destructor","body":["Tạo đối tượng lớp con thì constructor của cha chạy trước, con chạy sau. Hủy thì ngược lại, con hủy trước, cha hủy sau. Nhớ hình ảnh xây nhà từ móng lên mái, phá nhà thì từ mái xuống móng."],"code":"class B : public A\n{\npublic:\n    B() : A() { }\n};","body2":["Nếu không ghi rõ sau dấu hai chấm thì chương trình tự gọi constructor không tham số của lớp cha. Muốn gọi constructor có tham số của cha thì bắt buộc phải ghi rõ."]},{"h":"Ghi đè phương thức","body":["Khi lớp con khai báo phương thức trùng tên với lớp cha thì bản của cha bị che đi. Gọi qua đối tượng lớp con sẽ chạy bản của lớp con. Muốn gọi bản của cha thì dùng toán tử phạm vi, ví dụ c.Animal::eat()."]},{"h":"Phân biệt quá tải và ghi đè","table":{"head":["Đặc điểm","Quá tải (overload)","Ghi đè (override)"],"rows":[["Xảy ra ở","Cùng một lớp","Lớp con với lớp cha"],["Tên hàm","Giống nhau","Giống nhau"],["Tham số","Phải khác nhau","Phải giống nhau"],["Thời điểm quyết định","Lúc biên dịch","Lúc chạy"]]}},{"h":"Chuyển kiểu giữa lớp cha và lớp con","body":["Lớp con luôn chứa đủ phần của lớp cha nên gán đối tượng con cho biến cha là hợp lệ, phần dư bị bỏ bớt. Ngược lại gán cha cho con thì thiếu dữ liệu nên không hợp lệ."]},{"h":"Đa kế thừa","body":["Khai báo giống đơn kế thừa nhưng liệt kê nhiều lớp cha cách nhau bằng dấu phẩy, mỗi lớp cha phải ghi rõ phạm vi. Constructor của các lớp cha chạy theo đúng thứ tự ghi trong dòng kế thừa."],"code":"class C : public A, public B\n{\npublic:\n    C() : A(), B() { }\n};"}]},{"n":4,"title":"Đa hình và trừu tượng","sections":[{"h":"Hai loại đa hình","list":["Đa hình tĩnh quyết định lúc biên dịch, gồm quá tải hàm và quá tải toán tử.","Đa hình động quyết định lúc chạy, dựa trên kế thừa và phương thức ảo."]},{"h":"Phương thức ảo","body":["Trong C++ phải ghi từ khóa virtual ở lớp cha thì lớp con mới ghi đè theo kiểu đa hình được. Không có virtual thì phương thức được chọn dựa vào kiểu của con trỏ, có virtual thì chọn dựa vào đối tượng thật mà con trỏ đang trỏ tới."],"table":{"head":["Khai báo","Có virtual","Kết quả"],"rows":[["Lớp cha *obj = new Lớp cha","Không xét","Gọi bản của lớp cha"],["Lớp con *obj = new Lớp con","Không xét","Gọi bản của lớp con"],["Lớp cha *obj = new Lớp con","Không","Gọi bản của lớp cha"],["Lớp cha *obj = new Lớp con","Có","Gọi bản của lớp con"],["Lớp con *obj = new Lớp cha","","Lỗi"]]},"body2":["Một điểm rất hay bị bẫy: đa hình chỉ hoạt động qua con trỏ hoặc tham chiếu. Truyền đối tượng theo giá trị thì phần riêng của lớp con bị cắt đi và bản của lớp cha được gọi."]},{"h":"Hàm thuần ảo và lớp trừu tượng","body":["Hàm thuần ảo là hàm ảo không có phần cài đặt ở lớp cha, viết bằng cách gán bằng 0. Lớp nào có ít nhất một hàm thuần ảo thì gọi là lớp trừu tượng.","Không tạo đối tượng trực tiếp từ lớp trừu tượng, nó chỉ dùng làm lớp cha. Lớp con bắt buộc phải cài đặt lại hàm thuần ảo. Lớp trừu tượng vẫn được phép chứa các phương thức có cài đặt bình thường."],"code":"class Animal {\npublic:\n    virtual void sound() = 0;\n};\n\nclass Dog : public Animal {\npublic:\n    void sound() override { cout << \"Woof!\"; }\n};"},{"h":"Vấn đề kim cương và kế thừa ảo","body":["Khi hai lớp cha cùng kế thừa từ một lớp ông chung, lớp cháu sẽ chứa hai bản sao của lớp ông. Điều này gây trùng lặp dữ liệu và nhập nhằng khi gọi phương thức.","Thêm từ khóa virtual vào dòng kế thừa của hai lớp giữa thì chỉ còn một bản duy nhất được chia sẻ. Khi đó lớp cuối cùng chịu trách nhiệm gọi constructor của lớp ông."],"code":"class A { };\nclass B : virtual public A { };\nclass C : virtual public A { };\nclass D : public B, public C { };"}]},{"n":5,"title":"Lập trình hướng đối tượng trong C#","sections":[{"h":"Phạm vi truy cập","list":["private: chỉ trong lớp.","private protected: trong lớp và lớp kế thừa cùng assembly.","protected: trong lớp và mọi lớp kế thừa.","internal: trong cùng assembly.","protected internal: trong assembly và mọi lớp kế thừa.","public: mọi nơi."],"body":["Không ghi phạm vi cho thuộc tính hay phương thức thì mặc định là private. Với lớp thì mặc định là internal."]},{"h":"Lớp lồng nhau","body":["C# cho phép khai báo lớp bên trong lớp khác nhưng không cho khai báo lớp bên trong phương thức. Lớp lồng chỉ dùng được thành phần static của lớp ngoài, muốn dùng biến thực thể thì phải có một tham chiếu tới đối tượng lớp ngoài.","Gọi lớp lồng từ bên ngoài theo dạng LopNgoai.LopTrong, ví dụ A.B obj = new A.B();"]},{"h":"Đối tượng và bộ nhớ","body":["Tạo đối tượng bằng new, có thể tạo đối tượng tạm rồi gọi phương thức ngay theo dạng new Rectangle().Draw(). Không cần tự giải phóng bộ nhớ vì C# dùng Garbage Collection, bộ nhớ được thu hồi khi không còn tham chiếu nào trỏ tới đối tượng."]},{"h":"Constructor","list":["Trùng tên lớp, không có kiểu trả về. Không định nghĩa thì trình biên dịch tự tạo một bản không tham số.","C# khởi tạo mọi thành viên của lớp trước rồi mới chạy thân constructor.","C# không có danh sách khởi tạo bằng dấu hai chấm như C++, thay vào đó dùng từ khóa base.","Constructor tĩnh chạy tự động một lần duy nhất, không tham số, không có từ khóa truy cập, mỗi lớp chỉ có một bản."]},{"h":"Kế thừa","body":["Dùng dấu hai chấm, không ghi phạm vi kế thừa như C++. C# không hỗ trợ đa kế thừa lớp nhưng cho phép thực thi nhiều interface.","Từ khóa base gọi constructor, phương thức hoặc thuộc tính của lớp cha. Từ khóa sealed ngăn không cho lớp bị kế thừa hoặc phương thức bị ghi đè."],"code":"class B : A\n{\n    public B() : base(10) { }\n}"},{"h":"Đa hình","body":["Muốn có đa hình thì lớp cha phải ghi virtual và lớp con phải ghi override. Thiếu cặp từ khóa này thì phương thức của lớp con chỉ che khuất phương thức của cha và bản nào chạy sẽ phụ thuộc vào kiểu của biến."],"table":{"head":["Khai báo","Có virtual và override","Kết quả"],"rows":[["Lớp cha obj = new Lớp cha","Không xét","Gọi bản của lớp cha"],["Lớp con obj = new Lớp con","Không xét","Gọi bản của lớp con"],["Lớp cha obj = new Lớp con","Không","Gọi bản của lớp cha"],["Lớp cha obj = new Lớp con","Có","Gọi bản của lớp con"],["Lớp con obj = new Lớp cha","","Lỗi"]]}},{"h":"Trừu tượng","body":["Từ khóa abstract phải có ở cả khai báo lớp lẫn khai báo phương thức, thiếu một chỗ là lỗi biên dịch. Phương thức trừu tượng không có thân và không được để private. Không tạo đối tượng trực tiếp từ lớp trừu tượng."]},{"h":"Interface","list":["Interface chỉ khai báo, lớp thực thi phải cài đặt đầy đủ các thành phần.","Dùng dấu hai chấm để thực thi interface, một lớp thực thi được nhiều interface cùng lúc.","Interface kế thừa được từ nhiều interface khác.","Không tạo đối tượng trực tiếp từ interface, nhưng gán được đối tượng của lớp thực thi cho biến kiểu interface.","Khi gán như vậy, chỉ truy cập được các thành phần khai báo trong interface.","Từ C# 8.0 trở đi interface được phép có phương thức mặc định có thân."]}]},{"n":6,"title":"Lập trình hướng đối tượng trong Java","sections":[{"h":"Phạm vi truy cập","list":["private: chỉ trong lớp.","default: trong cùng package, đây là mức mặc định khi không ghi gì.","protected: trong package và trong lớp kế thừa ở package khác.","public: mọi nơi."],"body":["Một file chỉ có một lớp được khai báo public và tên lớp phải trùng tên file."]},{"h":"Lớp lồng nhau","body":["Khác C#, Java cho phép khai báo lớp ngay bên trong thân phương thức. Lớp đó chỉ tồn tại trong phạm vi của phương thức chứa nó.","Lớp nội bộ không static xem như một thành phần của lớp ngoài nên thấy mọi biến của lớp ngoài kể cả private. Muốn tạo đối tượng thì phải có đối tượng lớp ngoài trước, viết theo dạng test.new TestInner(). Lớp lồng static thì chỉ dùng được thành phần static và tạo đối tượng trực tiếp được."]},{"h":"Constructor và this","body":["Constructor trùng tên lớp và không có kiểu trả về. Có kiểu trả về thì đó chỉ là một phương thức bình thường, đây là bẫy rất hay gặp.","this dùng để trỏ tới đối tượng hiện tại và cũng dùng để gọi một constructor khác trong cùng lớp. Lệnh this hoặc super phải là câu lệnh đầu tiên trong constructor."]},{"h":"Kế thừa","body":["Dùng từ khóa extends. Từ khóa final ngăn không cho lớp bị kế thừa hoặc phương thức bị ghi đè, dùng với biến thì biến trở thành hằng số.","Từ khóa super tham chiếu tới lớp cha, dùng để gọi constructor hoặc phương thức của cha. Không được dùng super trong phương thức static. Nếu không ghi super thì constructor không tham số của lớp cha được gọi tự động."]},{"h":"Ghi đè và ẩn","body":["Java không có từ khóa virtual. Mọi phương thức trừ static, final và private đều mặc định là ảo nên ghi đè hoạt động ngay, bản được gọi là bản của đối tượng thật.","Phương thức static và biến thành viên thì không có đa hình. Chúng được chọn theo kiểu của biến tham chiếu chứ không theo đối tượng thật, gọi là ẩn chứ không phải ghi đè."],"table":{"head":["Khai báo","Phương thức static","Kết quả"],"rows":[["Lớp cha obj = new Lớp cha","Không xét","Gọi bản của lớp cha"],["Lớp con obj = new Lớp con","Không xét","Gọi bản của lớp con"],["Lớp cha obj = new Lớp con","Có","Gọi bản của lớp cha"],["Lớp cha obj = new Lớp con","Không","Gọi bản của lớp con"],["Lớp con obj = new Lớp cha","","Lỗi"]]}},{"h":"Toán tử instanceof","body":["Kiểm tra một đối tượng có phải thể hiện của một lớp hay một interface hay không, trả về true hoặc false. Đối tượng luôn thuộc về lớp của nó và mọi lớp cha của lớp đó, nhưng đối tượng lớp cha thì không phải là thể hiện của lớp con."],"code":"Animal animal = new Animal();\nDog dog = new Dog();\n\nSystem.out.println(dog instanceof Animal);\nSystem.out.println(animal instanceof Dog);","body2":["Dòng đầu in ra true vì Dog là lớp con của Animal. Dòng sau in ra false vì animal chỉ là một đối tượng Animal thuần túy."]},{"h":"Interface","list":["Lớp dùng từ khóa implements để thực thi interface.","Mọi biến trong interface mặc định là public static final, tức là hằng số nên không gán lại được.","Interface không được có constructor.","Java cho phép khai báo lớp bên trong interface, lớp đó mặc định là public static."]}]}]};
